'use client';

import { createContext, useContext } from 'react';
import ReactMarkdown, { type ExtraProps } from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { AgentStatus } from '../components/AgentStatus/AgentStatus';
import { CodeBlock, type CodeBlockProps } from '../components/CodeBlock/CodeBlock';
import { ChatMessage } from '../components/ChatMessage/ChatMessage';
import { Prose } from '../components/Prose/Prose';
import type { PromptSuggestionsProps } from '../components/PromptSuggestions/PromptSuggestions';
import type { QuestionCardLabels } from '../components/QuestionCard/QuestionCard';
import { Reasoning } from '../components/Reasoning/Reasoning';
import { useChatWidget } from './context';
import { DOCK_QUERY } from './queries';
import { FollowupSuggestions } from './FollowupSuggestions';
import { ResponseActions } from './ResponseActions';
import { TurnCard } from './TurnContent';
import { TurnQuestion } from './TurnQuestion';
import type { ChatTurn, LiveResponse } from './types';

/** The words an assistant turn's parts write, set from ChatWidget's label props. Every key left out keeps the part's English. */
export interface AssistantTurnLabels {
  /** The fenced-code CodeBlocks in a reply; `codeLabel` is given the fence's language. */
  codeBlock?: Pick<CodeBlockProps, 'copyLabel' | 'copyText' | 'copiedLabel'> & {
    codeLabel?: (language: string | undefined) => string;
  };
  /** The reasoning disclosure's summary once thinking is over, given the seconds it took when known. */
  reasoning?: (durationSeconds: number | undefined) => string;
  /** The question card a reply ends in. */
  questionCard?: Partial<QuestionCardLabels>;
  /** The follow-up row's hidden "(chosen)" text. */
  promptSuggestions?: Pick<PromptSuggestionsProps, 'chosenLabel'>;
}

/* The code blocks are drawn by react-markdown through a module-level
   components map, so their labels arrive by context rather than props. */
const CodeBlockLabelsContext = createContext<AssistantTurnLabels['codeBlock']>(undefined);

/**
 * Internal links navigate through the host's link renderer, so a panel
 * mounted from a root layout survives the trip and the conversation keeps
 * going beside the new page. When the panel covers the page (fullscreen
 * view, or any viewport below the dock threshold), navigating behind it
 * would be invisible, so following a link closes the chat first.
 */
function MarkdownLink({ href, children }: React.ComponentPropsWithoutRef<'a'>) {
  const { view, setOpen, renderLink, isInternalHref } = useChatWidget();
  if (!href || !isInternalHref(href)) return <>{children}</>;
  return (
    <>
      {renderLink({
        href,
        children,
        onNavigate: () => {
          if (view === 'full' || !window.matchMedia(DOCK_QUERY).matches) setOpen(false);
        },
      })}
    </>
  );
}

/* A fenced block's hast: a `pre` holding one `code` element whose text is
   the code plus the trailing newline the markdown-to-hast step appends. */
type HastNode = {
  type: string;
  value?: string;
  tagName?: string;
  properties?: Record<string, unknown>;
  children?: HastNode[];
};
const hastText = (node: HastNode): string =>
  node.type === 'text' ? (node.value ?? '') : (node.children ?? []).map(hastText).join('');

/* Fenced code renders as the library CodeBlock, so an install command or a
   snippet the answer hands over is one click from the clipboard. The language
   comes from the fence's info string (```bash), when the model wrote one. */
function MarkdownPre({ node, children, ...props }: React.ComponentPropsWithoutRef<'pre'> & ExtraProps) {
  const { codeLabel, ...labels } = useContext(CodeBlockLabelsContext) ?? {};
  const code = (node as HastNode | undefined)?.children?.find(
    (child) => child.type === 'element' && child.tagName === 'code'
  );
  if (!code) return <pre {...props}>{children}</pre>;
  const classes = code.properties?.className;
  const language = (Array.isArray(classes) ? classes : [])
    .map(String)
    .find((name) => name.startsWith('language-'))
    ?.slice('language-'.length);
  return (
    <CodeBlock
      {...labels}
      codeLabel={codeLabel?.(language)}
      code={hastText(code).replace(/\n$/, '')}
      language={language}
    />
  );
}

/* A markdown table has a natural minimum width that a docked panel cannot
   meet, and the browser resolves that by breaking headings one letter per
   line. Prose makes the table its own scroll container so it stays readable,
   which leaves one thing only the renderer can supply: a scrollable region
   has to be reachable without a mouse, and Prose styles markup it does not
   render, so it cannot put `tabIndex` on the element itself. Never swap this
   for `role="region"` on the table: that replaces the table semantics. */
const markdownComponents = {
  a: MarkdownLink,
  pre: MarkdownPre,
  table: ({ children, ...props }: React.ComponentPropsWithoutRef<'table'>) => (
    <table tabIndex={0} {...props}>
      {children}
    </table>
  ),
};

/* One component for the assistant turn in both states. The live turn and
   its committed form share an id (and so a key), so React reconciles the
   finished response in place: separate components remounted the whole
   subtree at commit, which read as a flicker after the response rendered. */
export function AssistantTurn({
  turn,
  live,
  labels,
}: {
  turn?: ChatTurn;
  live?: LiveResponse;
  labels?: AssistantTurnLabels;
}) {
  const thinking = live?.phase === 'thinking';
  const tracePoints = live ? live.tracePoints : (turn?.tracePoints ?? []);
  const durationSeconds = live ? live.durationSeconds : turn?.durationSeconds;
  const text = live ? live.text : (turn?.text ?? '');
  /* A reply's rich content and card draw as soon as the transport sends
     them, so a tool's result shows while the prose still streams. */
  const content = live ? live.content : turn?.content;
  const card = live ? live.card : turn?.card;

  /* Whether this turn's follow-up questions are still being generated: the
     request fires when a backend answer commits (see ChatProvider) and lands
     as the `followups` field (an empty array when there was nothing to
     offer), so "eligible but unset" is the in-flight window. Shown only
     while this is the newest turn and nothing new is streaming: once the
     visitor has moved on, a late resolution just appears, and a shimmer
     under an old answer would pull the eye backwards. */
  const { turns, live: liveTurn, freshFollowupsId } = useChatWidget();
  const followupsPending =
    !!turn &&
    turn.text !== '' &&
    !!turn.exchangeId &&
    !turn.followups &&
    !turn.question &&
    !liveTurn &&
    turns[turns.length - 1]?.id === turn.id;

  return (
    <ChatMessage
      role="assistant"
      /* Only a committed turn gets the row: while streaming there is nothing
         final to copy or judge, and an empty turn has nothing to act on.
         Pinned visible: in a chat panel the actions are part of the response,
         not a hover affordance to discover. */
      showActions
      actions={turn && turn.text !== '' ? <ResponseActions turn={turn} /> : undefined}
      /* Where the conversation could go next, under the actions row. They
         arrive a beat after the answer commits, and the row shimmers in their
         place while they are generated. */
      footer={
        turn?.followups?.length ? (
          <FollowupSuggestions
            turnId={turn.id}
            suggestions={turn.followups}
            chosen={turn.followupChosen}
            /* Only the row whose suggestions just landed pops its chips in;
               a row remounted by closing and reopening the panel shows them
               standing: they already arrived once. */
            entrance={turn.id === freshFollowupsId}
            chosenLabel={labels?.promptSuggestions?.chosenLabel}
          />
        ) : followupsPending && turn ? (
          <FollowupSuggestions turnId={turn.id} suggestions={[]} pending />
        ) : undefined
      }
    >
      <div className="ds-chat-widget__response">
        {/* While thinking the disclosure carries the live status; once
            streaming, it stays only if a trace actually accumulated: an
            empty collapsed panel is noise. Until a trace point arrives there
            is nothing behind the line either, so it renders as a plain
            status: no chevron, nothing to open. */}
        {(thinking || tracePoints.length > 0) && (
          <Reasoning
            streaming={thinking}
            summaryOnly={tracePoints.length === 0}
            duration={durationSeconds}
            /* Thinking, the AgentStatus below owns the line; the label is
               the text that takes over once it is done. */
            label={labels?.reasoning && !thinking ? labels.reasoning(durationSeconds) : undefined}
            summary={
              thinking && live ? (
                <AgentStatus state="working" label={live.statusLabel} />
              ) : undefined
            }
          >
            {tracePoints.length > 0 && (
              <ul>
                {tracePoints.map((point, index) => (
                  <li key={`${index}-${point.slice(0, 24)}`}>{point}</li>
                ))}
              </ul>
            )}
          </Reasoning>
        )}
        {/* Rich content (a tool call, a card) sits where an agent's
            structured output belongs: after the reasoning, before the prose
            that reads off what it shows. */}
        {content}
        {card && <TurnCard card={card} />}
        {text !== '' && (
          <CodeBlockLabelsContext.Provider value={labels?.codeBlock}>
          <Prose>
            {/* gfm: a real model emits tables and strikethrough, which plain
                CommonMark renders as literal pipes and tildes. */}
            <ReactMarkdown remarkPlugins={[remarkGfm]} components={markdownComponents}>
              {text}
            </ReactMarkdown>
          </Prose>
          </CodeBlockLabelsContext.Provider>
        )}
        {/* The answers to what the prose just asked sit straight under it,
            above the actions row: they are part of the reply. */}
        {turn?.question && <TurnQuestion turn={turn} labels={labels?.questionCard} />}
      </div>
    </ChatMessage>
  );
}

/* The built-in agent pane. The rail owns its shell; this only says how it
   sits in the widget's bottom sheet, where it fills the width rather than
   holding its own column and the sheet's rounded top edge is the surface. */
.ds-chat-agent-pane--sheet {
  width: 100%;
}

/* The pane furniture a host's panes commonly carry: a date heading over a
   run of rows, and a small card. Host content, offered as classes rather
   than components so a pane stays whatever the host writes. */
.ds-chat-agent-pane__group {
  display: flex;
  flex-direction: column;
  gap: var(--gap-100);
}

.ds-chat-agent-pane__group + .ds-chat-agent-pane__group,
.ds-chat-agent-pane__card + .ds-chat-agent-pane__group {
  margin-top: var(--gap-400);
}

.ds-chat-agent-pane__heading {
  font-family: var(--font-overline-family);
  font-size: var(--font-overline-size);
  font-weight: var(--font-overline-weight);
  line-height: var(--font-overline-line-height);
  letter-spacing: var(--font-overline-letter-spacing);
  text-transform: uppercase;
  color: var(--color-text-tertiary);
  padding: var(--padding-100) var(--padding-200);
  margin: 0;
}

/* The chat's card surface: container fill behind a hairline, like every
   card in the conversation. The radius stays a step under the rail's
   --radius-600, concentric with the shell it nests in. */
.ds-chat-agent-pane__card {
  display: flex;
  flex-direction: column;
  gap: var(--gap-200);
  padding: var(--padding-300);
  background-color: var(--color-bg-container-primary);
  border: var(--border-025) solid var(--color-bg-container-border);
  border-radius: var(--radius-400);
}

.ds-chat-agent-pane__card-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--gap-300);
}

.ds-chat-agent-pane__card-label {
  font-family: var(--font-paragraph-sm-emphasis-family);
  font-size: var(--font-paragraph-sm-emphasis-size);
  font-weight: var(--font-paragraph-sm-emphasis-weight);
  line-height: var(--font-paragraph-sm-emphasis-line-height);
  color: var(--color-text-primary);
}

'use client';

import { useState } from 'react';
import {
  AgentRail,
  type AgentRailProfile,
  type AgentRailProps,
  type AgentRailTab,
} from '../components/AgentRail/AgentRail';
import './ChatAgentPane.css';

export interface ChatAgentPaneProps {
  /** The agent this pane belongs to: the portrait block at the top. */
  profile: AgentRailProfile;
  /** The panes, in display order: activity, approvals, automations, personalisation, or whatever the agent has. */
  tabs: AgentRailTab[];
  /** The tab on stage, when the host owns the state; otherwise the pane keeps its own, seeded from `defaultValue`. */
  value?: string;
  /** The tab on stage first when the pane keeps its own state. Defaults to the first tab. */
  defaultValue?: string;
  /** Fires with the chosen tab's id. */
  onValueChange?: (id: string) => void;
  /**
   * Legacy name for `value`.
   *
   * @deprecated Use `value` instead.
   */
  activeTab?: string;
  /**
   * Legacy change callback; fires alongside `onValueChange`.
   *
   * @deprecated Use `onValueChange` instead.
   */
  onTabChange?: (id: string) => void;
  /** The widget seated the pane as a bottom sheet, where it fills the width instead of holding its own column. */
  overlay: boolean;
  /** Fires from the pane's own close button, a cross in its top trailing corner. Omit for a pane with no close of its own. */
  onClose?: () => void;
  /** Accessible name of the pane's own close button. Defaults to "Close the agent panel". */
  closeLabel?: string;
  /** The words the AgentRail writes, merged over its English defaults: the tab strip's name ("Agent views"). */
  agentRailLabels?: Pick<AgentRailProps, 'tabsLabel'>;
}

/**
 * The built-in agent pane: an AgentRail the widget seats on the
 * conversation's trailing edge (inline from ASIDE_RAIL_MIN_WIDTH, a bottom sheet
 * below, the artifact panel's own rule). A host hands it the agent's profile and panes; the widget owns
 * whether it is up. The header's agent toggle opens and closes it, and the
 * pane carries a close of its own in its top corner, where a panel's way
 * out is looked for.
 */
export function ChatAgentPane({
  profile,
  tabs,
  value,
  defaultValue,
  onValueChange,
  activeTab,
  onTabChange,
  overlay,
  onClose,
  closeLabel = 'Close the agent panel',
  agentRailLabels,
}: ChatAgentPaneProps) {
  const [ownTab, setOwnTab] = useState(defaultValue ?? tabs[0]?.id ?? '');
  // `activeTab` is the deprecated spelling of `value`.
  const current = value ?? activeTab ?? ownTab;
  return (
    <AgentRail
      {...agentRailLabels}
      className={overlay ? 'ds-chat-agent-pane--sheet' : undefined}
      profile={profile}
      tabs={tabs}
      value={current}
      onCollapse={onClose}
      collapseVariant="close"
      collapseLabel={closeLabel}
      onValueChange={(id) => {
        setOwnTab(id);
        onValueChange?.(id);
        onTabChange?.(id);
      }}
    />
  );
}

'use client';

import { ArtifactCard } from '../components/ArtifactCard/ArtifactCard';
import { useChatWidget } from './context';
import type { ChatArtifact } from './types';

export interface ChatArtifactCardProps {
  /** The artifact this tile stands for. */
  artifact: ChatArtifact;
}

/**
 * An artifact's place in the thread: an ArtifactCard wired to the provider,
 * which opens its artifact in the artifact panel. Pressing the tile of the
 * artifact already on stage closes the panel again, so the tile is one
 * control both ways. The widget draws it for every `artifact` card; a host
 * building its own thread renders it the same way.
 */
export function ChatArtifactCard({ artifact }: ChatArtifactCardProps) {
  const { artifact: onStage, openArtifact, closeArtifact } = useChatWidget();
  const open = onStage?.id === artifact.id;
  return (
    <ArtifactCard
      title={artifact.title}
      meta={artifact.meta}
      icon={artifact.icon}
      open={open}
      onClick={() => (open ? closeArtifact() : openArtifact(artifact))}
    />
  );
}

'use client';

import { ArtifactPanel, type ArtifactPanelProps } from '../components/ArtifactPanel/ArtifactPanel';
import { EmptyState } from '../components/EmptyState/EmptyState';
import { useChatWidget } from './context';
import type { ChatArtifact } from './types';

/* An artifact's URL is data a model or a server wrote, so it is framed only
   when it is plainly a page: http(s), or a same-site path. Anything else
   (a script URL, a data URL) is not framed at all. */
const FRAMEABLE_URL = /^(?:https?:\/\/|\/(?!\/))/i;

export interface ChatArtifactPaneProps {
  /** The artifact on stage, or null for the empty state: the panel opened before the conversation has made anything. */
  artifact: ChatArtifact | null;
  /** Whether the widget is showing the pane at its expanded size. */
  expanded?: boolean;
  /** Fires with the next state from the expand toggle; omit where the seat has one size. */
  onExpandedChange?: (expanded: boolean) => void;
  /** Fires from the pane's close button; omit where another control closes the seat. */
  onClose?: () => void;
  /** The panel's title while nothing is on stage. Defaults to "Artifacts". */
  emptyPanelTitle?: string;
  /** The empty state's heading. Defaults to "Nothing here yet". */
  emptyTitle?: string;
  /** The empty state's description. Defaults to "What the chat makes for you, like a dashboard or a page, opens in this panel." */
  emptyDescription?: string;
  /**
   * The words the ArtifactPanel writes, merged over its English defaults:
   * the view switch's segments and name ("Preview", "Code", "Artifact
   * view"), the expand toggle and close button's names ("Expand the
   * artifact", "Collapse the artifact", "Close the artifact"), and the code
   * view's copy button and region (`codeBlockLabels`).
   */
  artifactPanelLabels?: Pick<
    ArtifactPanelProps,
    'previewLabel' | 'codeLabel' | 'viewLabel' | 'expandLabel' | 'collapseLabel' | 'closeLabel' | 'codeBlockLabels'
  >;
}

/**
 * The built-in artifact pane: an ArtifactPanel drawn from a `ChatArtifact`.
 * A kind the provider's `artifactRenderers` knows is live React content;
 * otherwise the artifact's document, URL or source decides the preview. The
 * widget owns the seat (beside the conversation, or a sheet over it).
 */
export function ChatArtifactPane({
  artifact,
  expanded,
  onExpandedChange,
  onClose,
  emptyPanelTitle = 'Artifacts',
  emptyTitle = 'Nothing here yet',
  emptyDescription = 'What the chat makes for you, like a dashboard or a page, opens in this panel.',
  artifactPanelLabels,
}: ChatArtifactPaneProps) {
  const { artifactRenderers } = useChatWidget();
  if (!artifact) {
    return (
      <ArtifactPanel {...artifactPanelLabels} title={emptyPanelTitle} icon="space_dashboard" onClose={onClose}>
        <div className="ds-chat-widget__artifact-empty">
          <EmptyState size="compact" icon="draft" title={emptyTitle} description={emptyDescription} />
        </div>
      </ArtifactPanel>
    );
  }
  const custom = Object.hasOwn(artifactRenderers, artifact.kind);
  const render = artifactRenderers[artifact.kind];
  const src = artifact.url && FRAMEABLE_URL.test(artifact.url) ? artifact.url : undefined;
  return (
    <ArtifactPanel
      /* Keyed by artifact, so the view switch and any frame state start
         fresh when another one takes the stage. */
      key={artifact.id}
      {...artifactPanelLabels}
      title={artifact.title}
      meta={artifact.meta}
      icon={artifact.icon}
      html={custom ? undefined : artifact.html}
      src={custom ? undefined : src}
      code={artifact.code ?? (custom ? undefined : artifact.html)}
      language={artifact.language ?? (artifact.code === undefined && artifact.html !== undefined ? 'html' : undefined)}
      expanded={expanded}
      onExpandedChange={onExpandedChange}
      onClose={onClose}
    >
      {custom ? render(artifact) : undefined}
    </ArtifactPanel>
  );
}

'use client';

import { useEffect, useLayoutEffect, useRef, useState, useSyncExternalStore, type ReactNode } from 'react';
import { useScrollLock } from '../behaviors/useScrollLock';
import { AiButton, type AiButtonProps, type AiButtonSummary } from '../components/AiButton/AiButton';
import { ChatWidget, type ChatWidgetProps } from './ChatWidget';
import { useChatWidget } from './context';
import {
  FLOAT_EDGE_GAP,
  FLOAT_MAX_SCALE,
  clampFloatPosition,
  dockWidthFromDrag,
  isFloatDragStart,
} from './placement';
import { DOCK_QUERY, TAKEOVER_QUERY } from './queries';
import './ChatWidget.css';

/** The id the panel carries, for a host control's `aria-controls`. */
export const CHAT_PANEL_ID = 'ds-chat-panel';

/* The eight size grips of the floating card: which way each edge or corner
   pulls, per axis. */
const FLOAT_GRIPS = [
  { dir: 'n', dx: 0, dy: -1 },
  { dir: 's', dx: 0, dy: 1 },
  { dir: 'e', dx: 1, dy: 0 },
  { dir: 'w', dx: -1, dy: 0 },
  { dir: 'ne', dx: 1, dy: -1 },
  { dir: 'nw', dx: -1, dy: -1 },
  { dir: 'se', dx: 1, dy: 1 },
  { dir: 'sw', dx: -1, dy: 1 },
] as const;

const viewportBounds = () => ({
  left: 0,
  top: 0,
  right: window.innerWidth,
  bottom: window.innerHeight,
});

const subscribeQuery = (query: string) => (onChange: () => void) => {
  const media = window.matchMedia(query);
  media.addEventListener('change', onChange);
  return () => media.removeEventListener('change', onChange);
};
const subscribeDock = subscribeQuery(DOCK_QUERY);
const readDocked = () => window.matchMedia(DOCK_QUERY).matches;
const subscribeTakeover = subscribeQuery(TAKEOVER_QUERY);
const readTakeover = () => window.matchMedia(TAKEOVER_QUERY).matches;

export interface ChatLauncherProps {
  /** The floating button's text. */
  label?: string;
  /** The button's icon. */
  icon?: string;
  /**
   * A TLDR panel the button summons on hover: a pre-written summary and
   * prompt chips. A tapped chip opens the chat and sends the chip's
   * `prompt`. The launcher hands it to the closed button's AiButton, which
   * opens the panel on pointer hover; it does no device or hydration gating
   * of its own, so a host that wants the panel on hover-capable devices only,
   * or kept out of server HTML, passes `summary` only there.
   */
  summary?: AiButtonSummary & { chips?: { id: string; label: string; prompt: string }[] };
  /**
   * Render nothing at all: for routes that carry no chrome.
   * Note: not the native `hidden` attribute, which keeps an element mounted and only hides it; the launcher unmounts its button and panel, and spreads no native attributes.
   */
  hidden?: boolean;
  /** The panel's DOM id, for a host control's `aria-controls`. */
  panelId?: string;
  /**
   * The attribute the launcher writes on `<html>` to say how the panel sits
   * (`docked`, `docked-left`, `takeover`), so the host's stylesheet can pad
   * the page or hide it. `false` writes none.
   */
  hostAttribute?: string | false;
  /** Accessible name for the panel. */
  panelLabel?: string;
  /** The words of the floating button's summary panel, over AiButton's English defaults: the panel's name, given the summary's title ("Summary: <title>"), its dismiss button ("Dismiss summary") and its chips' group ("Suggested prompts"). */
  aiButtonLabels?: Pick<AiButtonProps, 'summaryRegionLabel' | 'dismissLabel' | 'suggestionsLabel'>;
  /** Everything the widget takes. The launcher sets the responsive ones itself. */
  widget?: Omit<ChatWidgetProps, 'fullscreenEnabled' | 'placementEnabled' | 'compact' | 'phone'>;
  /** Rendered inside the panel after the widget: for a host's extra chrome. */
  children?: ReactNode;
}

/**
 * The site-wide panel. Mount it once, after the page content, so it sits
 * last in the tab order and never remounts on navigation, which is what
 * lets a mid-stream answer keep streaming while the visitor reads a
 * different page.
 *
 * Docked (wide screens) it is a non-modal complementary region: no scrim,
 * no focus trap, the page stays fully usable beside it. Overlaying (below
 * the threshold, and in fullscreen view) it is modal: scrim, focus trap,
 * body scroll locked, Escape closes.
 *
 * The visitor picks the seat from the header's Chat position menu: either
 * edge for the dock (and for the overlay below the threshold), or floating,
 * a non-modal card that is moved by its header and sized by its edges.
 * Phones get none of it: the takeover is the only form there.
 *
 * The host contract: the launcher sets `hostAttribute` on `<html>` and
 * writes the chosen dock width to `--ds-chat-width` there; a host's
 * stylesheet pads the page beside a docked panel and hides it behind a
 * takeover from those two facts (the package's own stylesheet does not
 * touch the host's body). The panel's geometry reads `--ds-chat-width`,
 * `--ds-chat-inset` and `--ds-chat-float-height`, defaulted on `:root`.
 */
export function ChatLauncher({
  label = 'Ask',
  icon = 'forum',
  summary,
  hidden = false,
  panelId = CHAT_PANEL_ID,
  hostAttribute = 'data-chat',
  panelLabel = 'Chat',
  aiButtonLabels,
  widget,
  children,
}: ChatLauncherProps) {
  const { open, setOpen, panelPhase, view, side, floating, returnFocusRef, send } =
    useChatWidget();

  const launchSuggestion = (id: string) => {
    const chip = summary?.chips?.find((c) => c.id === id);
    if (!chip) return;
    setOpen(true);
    send(chip.prompt);
  };
  const docked = useSyncExternalStore(subscribeDock, readDocked, () => false);
  /* Phone widths: the panel fills the viewport, so it is a takeover whatever
     the view says; the expand toggle is hidden there rather than offering a
     switch from full screen to full screen. */
  const takeover = useSyncExternalStore(subscribeTakeover, readTakeover, () => false);

  const isFull = view === 'full' || takeover;
  /* Floating, the panel is a free card over the page: never modal, never
     insetting the page, at any width above the takeover. */
  const isFloating = floating && !isFull;
  const isDocked = docked && !isFull && !isFloating;
  const modal = open && !hidden && (isFull || (!docked && !isFloating));
  const showPanel = open && !hidden;
  /* Presence outlives `open` by the exit beat, so the close animation is
     seen; every behaviour above keys on `open` and lets go immediately. */
  const renderPanel = (open || panelPhase === 'closing') && !hidden;

  /* The page's relationship to the panel, as an attribute on <html> so the
     host's styling needs no subscription anywhere else:

     - docked: html[data-chat="docked"] is the host's cue to pad the body
       and offset a sticky header, so the page slides over beside the
       panel. The left dock is the same on the other side, under its own
       value, "docked-left". Floating sets nothing: the page keeps its full
       width under the card.
     - takeover (phone widths): html[data-chat="takeover"] is the cue to
       hide the page around the panel, which leaves the fixed layer for
       normal flow at 100dvh: the chat is the document. That is what lets
       the soft keyboard be the browser's problem rather than the panel's.
       A viewport-sized position: fixed panel is exactly what iOS Safari
       renders short under the keyboard, so no fixed geometry is trusted
       there. Hiding the page collapses the document, so the scroll offset
       is read before the attribute lands and restored, instantly, when the
       page comes back. A layout effect, so the in-flow panel never paints
       once below the footer before the page hides. */
  useLayoutEffect(() => {
    if (!hostAttribute) return;
    const root = document.documentElement;
    if (showPanel && takeover) {
      const scrollY = window.scrollY;
      root.setAttribute(hostAttribute, 'takeover');
      window.scrollTo({ top: 0, behavior: 'instant' });
      return () => {
        root.removeAttribute(hostAttribute);
        window.scrollTo({ top: scrollY, behavior: 'instant' });
      };
    }
    if (showPanel && isDocked) {
      root.setAttribute(hostAttribute, side === 'left' ? 'docked-left' : 'docked');
      return () => root.removeAttribute(hostAttribute);
    }
    root.removeAttribute(hostAttribute);
  }, [showPanel, isDocked, side, takeover, hostAttribute]);

  /* Modal mode owns the page behind it. Not on phones: there the page is
     hidden rather than covered, so there is nothing behind to hold still.
     The library's shared counter, so a Dialog opened over the panel and the
     panel can close in either order without unlocking the page under the
     survivor. */
  useScrollLock(modal && !takeover);

  const panelRef = useRef<HTMLDivElement | null>(null);

  /* Closing restores focus to whichever launcher opened the panel, when it
     is still on the page. */
  const wasOpen = useRef(false);
  useEffect(() => {
    if (wasOpen.current && !open) {
      const target = returnFocusRef.current;
      if (target && target.isConnected) target.focus();
    }
    wasOpen.current = open;
  }, [open, returnFocusRef]);

  /* Drag-to-widen, docked view only. Pointer capture, primary button,
     cancel-safe; the panel's outer edge is fixed, so the width delta is the
     inverted pointer delta. A mouse affordance: the panel stays fully usable
     at its resting width without it. */
  const dragRef = useRef<{ startX: number; width: number } | null>(null);
  const [resizing, setResizing] = useState(false);

  const beginResize = (e: React.PointerEvent<HTMLDivElement>) => {
    if ((e.pointerType === 'mouse' && e.button !== 0) || dragRef.current) return;
    const rect = panelRef.current?.getBoundingClientRect();
    if (!rect) return;
    dragRef.current = { startX: e.clientX, width: rect.width };
    e.currentTarget.setPointerCapture(e.pointerId);
    setResizing(true);
    /* Suppresses the glides and page text selection while the pointer drives
       the geometry frame by frame (the panel's own rule, and the host's). */
    document.documentElement.setAttribute('data-chat-resizing', '');
  };

  const moveResize = (e: React.PointerEvent<HTMLDivElement>) => {
    const drag = dragRef.current;
    if (!drag) return;
    /* The drag writes the variable back onto <html>, so everything sized
       from it (the host's body inset, a sticky header's offset) slides with
       the panel edge for free. The chosen width holds for the session. */
    const width = dockWidthFromDrag(drag.width, e.clientX - drag.startX, side);
    document.documentElement.style.setProperty('--ds-chat-width', `${width}px`);
  };

  const endResize = () => {
    dragRef.current = null;
    setResizing(false);
    document.documentElement.removeAttribute('data-chat-resizing');
  };

  /* Drag-to-move, floating view only. The position is null until the first
     drag (the stylesheet's default corner applies), then lives in state as
     viewport pixels. During the drag the pointer writes the two variables
     straight onto the node, so the transcript underneath does not re-render
     per frame; the state commit on release makes React agree. */
  const [floatPos, setFloatPos] = useState<{ x: number; y: number } | null>(null);
  const moveRef = useRef<{ dx: number; dy: number; x: number; y: number } | null>(null);

  const clampFloat = (x: number, y: number, rect: DOMRect) =>
    clampFloatPosition(x, y, rect, viewportBounds());

  const beginMove = (e: React.PointerEvent<HTMLDivElement>) => {
    if (!isFloating || moveRef.current) return;
    if (e.pointerType === 'mouse' && e.button !== 0) return;
    if (!isFloatDragStart(e.target)) return;
    const rect = e.currentTarget.getBoundingClientRect();
    moveRef.current = { dx: e.clientX - rect.left, dy: e.clientY - rect.top, x: rect.left, y: rect.top };
    /* Capture keeps the drag alive when the pointer outruns the card. It
       throws for a pointer the browser no longer considers active, and a
       drag that merely loses that is better than one that never starts. */
    try {
      e.currentTarget.setPointerCapture(e.pointerId);
    } catch {
      /* see above */
    }
    document.documentElement.setAttribute('data-chat-resizing', '');
  };

  const moveMove = (e: React.PointerEvent<HTMLDivElement>) => {
    const move = moveRef.current;
    if (!move) return;
    const node = e.currentTarget;
    const next = clampFloat(e.clientX - move.dx, e.clientY - move.dy, node.getBoundingClientRect());
    move.x = next.x;
    move.y = next.y;
    node.style.setProperty('--ds-chat-float-x', `${next.x}px`);
    node.style.setProperty('--ds-chat-float-y', `${next.y}px`);
  };

  const endMove = () => {
    const move = moveRef.current;
    if (!move) return;
    moveRef.current = null;
    setFloatPos({ x: move.x, y: move.y });
    document.documentElement.removeAttribute('data-chat-resizing');
  };

  /* Drag-to-size, floating view only. The resting size is both the default
     and the floor; each axis grows to FLOAT_MAX_SCALE of it, or to the
     viewport edge if that comes first. An edge that is pulled moves; the
     opposite one holds still, so a north or west grip rewrites the position
     as well. */
  const [floatSize, setFloatSize] = useState<{ w: number; h: number } | null>(null);
  const sizeRef = useRef<{
    dx: number;
    dy: number;
    startX: number;
    startY: number;
    rect: DOMRect;
    minW: number;
    minH: number;
    next: { x: number; y: number; w: number; h: number };
  } | null>(null);

  const beginSize = (e: React.PointerEvent<HTMLDivElement>, dx: number, dy: number) => {
    if ((e.pointerType === 'mouse' && e.button !== 0) || sizeRef.current) return;
    const rect = panelRef.current?.getBoundingClientRect();
    if (!rect) return;
    e.stopPropagation();
    const root = getComputedStyle(document.documentElement);
    const inset = parseFloat(root.getPropertyValue('--ds-chat-inset')) || 0;
    const minW = parseFloat(root.getPropertyValue('--ds-chat-width')) || rect.width;
    /* The resting height is the stylesheet's: the variable, or the viewport
       between the insets when that is shorter. */
    const restH = parseFloat(root.getPropertyValue('--ds-chat-float-height')) || rect.height;
    const minH = Math.min(restH, window.innerHeight - inset * 2);
    sizeRef.current = {
      dx,
      dy,
      startX: e.clientX,
      startY: e.clientY,
      rect,
      minW,
      minH,
      next: { x: rect.left, y: rect.top, w: rect.width, h: rect.height },
    };
    try {
      e.currentTarget.setPointerCapture(e.pointerId);
    } catch {
      /* see beginMove */
    }
    document.documentElement.setAttribute('data-chat-resizing', '');
  };

  const moveSize = (e: React.PointerEvent<HTMLDivElement>) => {
    const drag = sizeRef.current;
    const node = panelRef.current;
    if (!drag || !node) return;
    const { rect, next } = drag;
    if (drag.dx !== 0) {
      /* The room between the held edge and the viewport, on the pulled side. */
      const room =
        drag.dx > 0 ? window.innerWidth - FLOAT_EDGE_GAP - rect.left : rect.right - FLOAT_EDGE_GAP;
      const max = Math.max(drag.minW, Math.min(drag.minW * FLOAT_MAX_SCALE, room));
      next.w = Math.round(
        Math.min(max, Math.max(drag.minW, rect.width + drag.dx * (e.clientX - drag.startX)))
      );
      next.x = Math.round(drag.dx > 0 ? rect.left : rect.right - next.w);
    }
    if (drag.dy !== 0) {
      const room =
        drag.dy > 0 ? window.innerHeight - FLOAT_EDGE_GAP - rect.top : rect.bottom - FLOAT_EDGE_GAP;
      const max = Math.max(drag.minH, Math.min(drag.minH * FLOAT_MAX_SCALE, room));
      next.h = Math.round(
        Math.min(max, Math.max(drag.minH, rect.height + drag.dy * (e.clientY - drag.startY)))
      );
      next.y = Math.round(drag.dy > 0 ? rect.top : rect.bottom - next.h);
    }
    node.style.setProperty('--ds-chat-float-x', `${next.x}px`);
    node.style.setProperty('--ds-chat-float-y', `${next.y}px`);
    node.style.setProperty('--ds-chat-float-w', `${next.w}px`);
    node.style.setProperty('--ds-chat-float-h', `${next.h}px`);
  };

  const endSize = () => {
    const drag = sizeRef.current;
    if (!drag) return;
    sizeRef.current = null;
    setFloatPos({ x: drag.next.x, y: drag.next.y });
    setFloatSize({ w: drag.next.w, h: drag.next.h });
    document.documentElement.removeAttribute('data-chat-resizing');
  };

  /* A shrinking window must not strand the card off screen. */
  useEffect(() => {
    if (!isFloating || !floatPos) return;
    const onResize = () => {
      const rect = panelRef.current?.getBoundingClientRect();
      if (!rect) return;
      setFloatPos((pos) => {
        if (!pos) return pos;
        const next = clampFloat(pos.x, pos.y, rect);
        return next.x === pos.x && next.y === pos.y ? pos : next;
      });
    };
    window.addEventListener('resize', onResize);
    return () => window.removeEventListener('resize', onResize);
  }, [isFloating, floatPos]);

  if (hidden) return null;

  /* Closed: the FAB is the persistent entry point, bottom right on every
     page, never remounting on navigation (so focus restore works everywhere). */
  if (!renderPanel) {
    return (
      <div className="ds-chat-launcher__fab">
        <AiButton
          {...aiButtonLabels}
          label={label}
          icon={icon}
          aria-expanded={false}
          aria-controls={panelId}
          summary={
            summary
              ? {
                  overline: summary.overline,
                  title: summary.title,
                  caption: summary.caption,
                  text: summary.text,
                  suggestions:
                    summary.suggestions ??
                    summary.chips?.map(({ id, label: chipLabel }) => ({ id, label: chipLabel })),
                }
              : undefined
          }
          onSummarySuggestion={launchSuggestion}
          onClick={(event) => {
            returnFocusRef.current = event.currentTarget;
            setOpen(true);
          }}
        />
      </div>
    );
  }

  const handleKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
    /* The widget handles Escape-in-fullscreen itself (and stops propagation);
       this one closes the panel from panel view. */
    if (event.key === 'Escape') {
      /* An Escape a menu or picker inside the panel already handled closed
         that layer, not the panel. */
      if (!event.defaultPrevented) setOpen(false);
      return;
    }
    /* A minimal focus trap, only while modal: Tab wraps within the panel.
       Docked mode is non-modal by design: focus flows through the page. */
    if (modal && event.key === 'Tab' && panelRef.current) {
      const focusables = panelRef.current.querySelectorAll<HTMLElement>(
        'button:not([disabled]), a[href], textarea:not([disabled]), input:not([disabled]), [tabindex]:not([tabindex="-1"])'
      );
      if (focusables.length === 0) return;
      const first = focusables[0];
      const last = focusables[focusables.length - 1];
      if (event.shiftKey && document.activeElement === first) {
        event.preventDefault();
        last.focus();
      } else if (!event.shiftKey && document.activeElement === last) {
        event.preventDefault();
        first.focus();
      }
    }
  };

  const panelClass = [
    'ds-chat-launcher__panel',
    side === 'left' ? 'ds-chat-launcher__panel--left' : '',
    isFloating ? 'ds-chat-launcher__panel--floating' : '',
    isFull ? 'ds-chat-launcher__panel--full' : '',
    panelPhase === 'closing' ? 'ds-chat-launcher__panel--closing' : '',
  ]
    .filter(Boolean)
    .join(' ');

  return (
    <>
      {modal && !isFull && (
        <div className="ds-chat-launcher__scrim" onClick={() => setOpen(false)} aria-hidden="true" />
      )}
      <div
        ref={panelRef}
        id={panelId}
        className={panelClass}
        style={
          isFloating && (floatPos || floatSize)
            ? ({
                ...(floatPos && {
                  '--ds-chat-float-x': `${floatPos.x}px`,
                  '--ds-chat-float-y': `${floatPos.y}px`,
                }),
                ...(floatSize && {
                  '--ds-chat-float-w': `${floatSize.w}px`,
                  '--ds-chat-float-h': `${floatSize.h}px`,
                }),
              } as React.CSSProperties)
            : undefined
        }
        onPointerDown={beginMove}
        onPointerMove={moveMove}
        onPointerUp={endMove}
        onPointerCancel={endMove}
        role={modal ? 'dialog' : 'complementary'}
        aria-modal={modal || undefined}
        aria-label={panelLabel}
        onKeyDown={handleKeyDown}
      >
        {/* compact tracks the host's width, not the view: a takeover on a
            phone still wants phone insets, where one on a desktop does not. */}
        <ChatWidget
          {...widget}
          fullscreenEnabled={!takeover}
          placementEnabled={!takeover}
          compact={takeover || !isFull}
          phone={takeover}
        />
        {children}
        {/* The size grips, inside the card's edge rather than straddling it,
            because the panel clips its own overflow. Pointer-only, like the
            dock's widen grip. */}
        {isFloating &&
          FLOAT_GRIPS.map(({ dir, dx, dy }) => (
            <div
              key={dir}
              className="ds-chat-launcher__float-grip"
              data-dir={dir}
              aria-hidden="true"
              onPointerDown={(e) => beginSize(e, dx, dy)}
              onPointerMove={moveSize}
              onPointerUp={endSize}
              onPointerCancel={endSize}
            />
          ))}
      </div>
      {/* The widen grip, docked form only. It rides the panel's inner edge
          as a fixed sibling (the panel clips its own overflow, so a
          straddling child would be cut in half). */}
      {showPanel && isDocked && (
        <div
          className={[
            'ds-chat-launcher__dock-handle',
            side === 'left' ? 'ds-chat-launcher__dock-handle--left' : '',
            resizing ? 'ds-chat-launcher__dock-handle--resizing' : '',
          ]
            .filter(Boolean)
            .join(' ')}
          aria-hidden="true"
          onPointerDown={beginResize}
          onPointerMove={moveResize}
          onPointerUp={endResize}
          onPointerCancel={endResize}
        />
      )}
    </>
  );
}

'use client';

import { useCallback, useEffect, useMemo, useRef, useState, type ReactNode } from 'react';
import { MOTION_EXIT_SYNC_MS } from '../tokens/motion';
import {
  ChatWidgetContext,
  createFeedbackPoster,
  isInternalPath,
  type ChatArtifactRenderers,
  type ChatCardRenderers,
  type ChatLinkRenderer,
  type ChatView,
  type ChatWidgetContextValue,
  type FeedbackSink,
} from './context';
import {
  DEFAULT_FALLBACK_FOLLOWUPS,
  createFollowupsFetcher,
  followupTarget,
  pickFallbackFollowups,
  type FollowupsSource,
} from './followups';
import type { ChatPlacement, ChatSide } from './placement';
import { useThreads, type ThreadsOptions } from './threads';
import { createFetchTransport } from './transport';
import type { ChatArtifact, ChatFeedbackVerdict, ChatTransport } from './types';
import { DEFAULT_PLACEHOLDER_COPY, useChat, type ChatPlaceholderCopy } from './useChat';
import { useLinkComponent } from '../behaviors/LinkProvider';

/* The default answer link renders through the app's router when a
   LinkProvider sets one, the same link the library's own components use,
   so a provider set once covers the chat too. A component, so it can read
   the provider; the renderer itself is a plain function. */
function DefaultChatLink({ href, children, onNavigate }: Parameters<ChatLinkRenderer>[0]) {
  const Link = useLinkComponent();
  return (
    // The hook returns a stable reference from context (or 'a'), never a
    // component created here, which is what the rule guards against.
    // eslint-disable-next-line react-hooks/static-components
    <Link href={href} onClick={onNavigate}>
      {children}
    </Link>
  );
}

const defaultRenderLink: ChatLinkRenderer = (props) => <DefaultChatLink {...props} />;

export interface ChatProviderProps {
  /**
   * Where the conversation goes. Defaults to the fetch transport against
   * `endpoint`, carrying the visitor's model pick. A script from
   * `scriptChat()` runs the widget with no backend at all.
   */
  transport?: ChatTransport;
  /** The endpoint the default transport posts to. */
  endpoint?: string;
  /** The seat the panel opens in. */
  defaultPlacement?: ChatPlacement;
  /**
   * Where follow-up questions come from after an answer commits: a source
   * function, an endpoint for the built-in fetcher, or `false` for none:
   * with `false` no chips show under an answer at all, not even the written
   * `fallbackFollowups`. Defaults to the fetcher against `/api/chat/followups`.
   */
  followups?: FollowupsSource | string | false;
  /** The written questions offered when the source returns none or fails. Unused when `followups` is `false`. */
  fallbackFollowups?: readonly string[];
  /**
   * Where a thumbs verdict goes: a sink function, an endpoint for the
   * built-in poster, or `false` to hide the thumbs. Defaults to the poster
   * against `/api/chat/feedback`. Thumbs only ever show on a turn the
   * server logged (one with an exchange id).
   */
  feedback?: FeedbackSink | string | false;
  /** Draws `card` events by kind. */
  renderers?: ChatCardRenderers;
  /** Draws an artifact's preview by kind, for artifacts that are live React content rather than a document or a URL. */
  artifactRenderers?: ChatArtifactRenderers;
  /**
   * Renders a same-site link in an answer. The default renders through the
   * nearest LinkProvider's link component, else a plain anchor; passing
   * this wins over both.
   */
  renderLink?: ChatLinkRenderer;
  /** Which hrefs in an answer become links. Everything else renders as text. */
  isInternalHref?: (href: string) => boolean;
  /** Seeds the thread lifecycle behind the `threads` and `tabs` slots. */
  threads?: ThreadsOptions;
  /** Replacement copy for the words the hook writes itself, merged over the English defaults: the status line of a reply that has not started ("Thinking") and the placeholder replies for an empty, stopped or failed turn. */
  placeholders?: Partial<ChatPlaceholderCopy>;
  children: ReactNode;
}

/**
 * The chat's whole client state. Mount it once, high in the tree: a root
 * layout never remounts on client-side navigation, so the transcript, a
 * stream in flight, the half-typed draft and the open state survive
 * clicking between pages for free. A hard reload starts clean by design:
 * no storage, no persistence.
 */
export function ChatProvider({
  transport,
  endpoint = '/api/chat',
  defaultPlacement = 'right',
  followups = '/api/chat/followups',
  fallbackFollowups = DEFAULT_FALLBACK_FOLLOWUPS,
  feedback = '/api/chat/feedback',
  renderers,
  artifactRenderers,
  renderLink = defaultRenderLink,
  isInternalHref = isInternalPath,
  threads: threadsOptions,
  placeholders,
  children,
}: ChatProviderProps) {
  /* The visitor's explicit model pick. Null means "follow the server's
     default", which is a different fact from having picked the model that
     happens to be the default: a budget tier can move the default under a
     visitor who never chose, but never under one who did. The default
     transport closes over the current value, so a pick re-creates it and
     rides on the next send; a stream already in flight keeps the model it
     started on. */
  const [chosenModel, setChosenModel] = useState<string | null>(null);

  const fallbackTransport = useMemo(
    () => createFetchTransport(endpoint, { getModel: () => chosenModel }),
    [endpoint, chosenModel]
  );
  const placeholderCopy = useMemo(
    () => ({ ...DEFAULT_PLACEHOLDER_COPY, ...placeholders }),
    [placeholders]
  );
  const chat = useChat(transport ?? fallbackTransport, placeholderCopy);
  const threads = useThreads(chat, threadsOptions);

  /* Follow-up chips for the answer that just landed. Fired here rather than
     from the turn's own component so it happens once per answer, whether or
     not anything is rendering it: the panel can be closed, or the turn
     scrolled far above the fold, and the chips are still there when the
     visitor arrives. Turn ids are minted in sequence and never reused, so
     the set of ids already asked about is all the bookkeeping this needs. */
  const followupsSource = useMemo<FollowupsSource | null>(() => {
    if (followups === false) return null;
    return typeof followups === 'string' ? createFollowupsFetcher(followups) : followups;
  }, [followups]);
  const { setTurnFollowups } = chat;
  const target = useMemo(() => followupTarget(chat.turns), [chat.turns]);
  const askedRef = useRef<Set<string>>(new Set());
  const [freshFollowupsId, setFreshFollowupsId] = useState<string | null>(null);

  useEffect(() => {
    if (!target || askedRef.current.has(target.id)) return;
    askedRef.current.add(target.id);
    const offer = (suggestions: string[]) => {
      // An empty result substitutes the written fallbacks: the pending row
      // promised chips, and a shimmer that resolves to nothing reads as broken.
      const offered =
        suggestions.length > 0
          ? suggestions
          : pickFallbackFollowups(fallbackFollowups, target.id, target.question);
      setTurnFollowups(target.id, offered);
      setFreshFollowupsId(target.id);
    };
    if (!followupsSource) {
      // `followups={false}` means no chips at all, written fallbacks included.
      // The empty set still lands on the turn, which settles the pending row
      // rather than leaving it shimmering.
      setTurnFollowups(target.id, []);
      return;
    }
    // A write to a turn that has since been cleared by a new chat is a
    // no-op, so there is nothing here to abort or guard.
    void followupsSource(target.question, target.answer, AbortSignal.timeout(10_000))
      .catch(() => [] as string[])
      .then(offer);
  }, [target, setTurnFollowups, followupsSource, fallbackFollowups]);

  const feedbackSink = useMemo<FeedbackSink | null>(() => {
    if (feedback === false) return null;
    return typeof feedback === 'string' ? createFeedbackPoster(feedback) : feedback;
  }, [feedback]);
  const { setTurnFeedback } = chat;
  const submitFeedback = useMemo(
    () =>
      feedbackSink
        ? (turnId: string, exchangeId: string, verdict: ChatFeedbackVerdict) => {
            // Optimistic on purpose: the verdict is the visitor's fact, so it
            // shows immediately; a write the network loses is worth less than
            // a spinner.
            setTurnFeedback(turnId, verdict);
            void feedbackSink(exchangeId, verdict).catch(() => {});
          }
        : null,
    [feedbackSink, setTurnFeedback]
  );

  /* The starters' staged-reveal memory, provider-lifetime by design. */
  const [starterRevealKey, setStarterRevealKey] = useState<string | null>(null);

  /* The starter pools' draw. Provider-lifetime, so client-side navigation
     and re-renders never reshuffle chips the visitor is reading; a hard
     reload rolls it fresh. The starters only render inside the open panel,
     which the server never renders, so the random initialiser cannot reach
     the server HTML. */
  const [starterSeed, setStarterSeed] = useState<number>(() => Math.random());

  /* The artifact on stage. Provider-lifetime like the transcript it came
     from, so it survives the panel closing and reopening around it. */
  const [artifact, setArtifact] = useState<ChatArtifact | null>(null);
  const openArtifact = useCallback((next: ChatArtifact) => setArtifact(next), []);
  const closeArtifact = useCallback(() => setArtifact(null), []);
  /* An artifact belongs to the conversation that made it. Every road back to
     an empty thread (New chat, another thread, a deleted one) takes it off
     stage; adjusted during render so the panel never paints over a welcome
     screen. */
  if (artifact && chat.turns.length === 0 && !chat.live) setArtifact(null);

  /* New chat re-rolls the draw and forgets the staged reveal, so the welcome
     screen replays its short generation beat over a different set. It also
     closes the artifact: the conversation that made it is gone. */
  const { reset: resetChat } = chat;
  const reset = useCallback(() => {
    resetChat();
    setArtifact(null);
    setStarterSeed(Math.random());
    setStarterRevealKey(null);
  }, [resetChat]);

  const [open, setOpenState] = useState(false);
  /* The panel's presence, one beat behind `open` on the way out: closing
     holds the node on screen for MOTION_EXIT_SYNC_MS so the exit animation
     plays before the unmount. Reopening mid-exit cancels the timer. */
  const [panelPhase, setPanelPhase] = useState<'open' | 'closing' | 'closed'>('closed');
  const closeTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  useEffect(
    () => () => {
      if (closeTimer.current) clearTimeout(closeTimer.current);
    },
    []
  );
  const setOpen = useCallback((next: boolean) => {
    if (next) {
      if (closeTimer.current) {
        clearTimeout(closeTimer.current);
        closeTimer.current = null;
      }
      setPanelPhase('open');
      setOpenState(true);
      return;
    }
    /* Closing also forgets which follow-ups were "fresh": everything the
       next open shows has been seen. */
    setFreshFollowupsId(null);
    setOpenState(false);
    setPanelPhase((phase) => (phase === 'open' ? 'closing' : phase));
    closeTimer.current = setTimeout(() => {
      closeTimer.current = null;
      setPanelPhase('closed');
    }, MOTION_EXIT_SYNC_MS);
  }, []);
  const [view, setView] = useState<ChatView>('panel');
  /* Two facts rather than one: floating must not forget the dock edge, or
     the way back (and the overlay below the dock threshold) has no side. */
  const [side, setSide] = useState<ChatSide>(
    defaultPlacement === 'floating' ? 'right' : defaultPlacement
  );
  const [floating, setFloating] = useState(defaultPlacement === 'floating');
  const placement: ChatPlacement = floating ? 'floating' : side;
  const setPlacement = useCallback((next: ChatPlacement) => {
    if (next === 'floating') {
      setFloating(true);
      return;
    }
    setFloating(false);
    setSide(next);
  }, []);
  const [draft, setDraft] = useState('');
  const returnFocusRef = useRef<HTMLElement | null>(null);

  const toggleOpen = useCallback(() => setOpen(!open), [open, setOpen]);

  const renderersValue = useMemo(() => renderers ?? {}, [renderers]);
  const artifactRenderersValue = useMemo(() => artifactRenderers ?? {}, [artifactRenderers]);

  const value = useMemo<ChatWidgetContextValue>(
    () => ({
      ...chat,
      reset,
      chosenModel,
      setChosenModel,
      open,
      setOpen,
      toggleOpen,
      panelPhase,
      starterRevealKey,
      setStarterRevealKey,
      starterSeed,
      freshFollowupsId,
      view,
      setView,
      placement,
      setPlacement,
      side,
      floating,
      draft,
      setDraft,
      returnFocusRef,
      threads,
      renderers: renderersValue,
      artifact,
      openArtifact,
      closeArtifact,
      artifactRenderers: artifactRenderersValue,
      renderLink,
      isInternalHref,
      submitFeedback,
    }),
    [
      chat,
      reset,
      chosenModel,
      open,
      setOpen,
      toggleOpen,
      panelPhase,
      starterRevealKey,
      starterSeed,
      freshFollowupsId,
      view,
      placement,
      setPlacement,
      side,
      floating,
      draft,
      threads,
      renderersValue,
      artifact,
      openArtifact,
      closeArtifact,
      artifactRenderersValue,
      renderLink,
      isInternalHref,
      submitFeedback,
    ]
  );

  return <ChatWidgetContext.Provider value={value}>{children}</ChatWidgetContext.Provider>;
}

'use client';

import { ThreadTabs, type ThreadTabsProps } from '../components/ThreadTabs/ThreadTabs';
import { useChatWidget } from './context';

/**
 * The built-in open-sessions strip: a ThreadTabs over the provider's
 * thread lifecycle. Tabs hold thread ids; selecting one moves the rail's
 * selection, the trailing plus is the same New chat as everywhere else, and
 * closing the last tab lands back on the greeting. Renders nothing while no
 * session is open: a bare plus over the greeting would be the header's pen
 * restated.
 */
export interface ChatTabsProps {
  /** Accessible name for the tab strip. */
  ariaLabel?: string;
  /** Accessible name of each tab's close button. A string is followed by a colon and the tab's title; a function is given the title and returns the whole name. Defaults to "Close chat". */
  closeLabel?: ThreadTabsProps['closeLabel'];
  /** Spoken text for each tab's status, merged over ThreadTabs' English defaults (Working, Unread, Needs input, Failed). */
  statusLabels?: ThreadTabsProps['statusLabels'];
}

export function ChatTabs({ ariaLabel = 'Open chats', closeLabel = 'Close chat', statusLabels }: ChatTabsProps) {
  const { threads } = useChatWidget();
  if (threads.tabs.length === 0) return null;
  return (
    <ThreadTabs
      tabs={threads.tabs}
      activeId={threads.activeThreadId || undefined}
      onTabSelect={threads.select}
      onTabClose={threads.closeTab}
      onAdd={threads.startNew}
      addLabel={threads.newThreadLabel}
      closeLabel={closeLabel}
      statusLabels={statusLabels}
      ariaLabel={ariaLabel}
    />
  );
}

'use client';

import { useMemo, useState, type ReactNode } from 'react';
import {
  ThreadPanel,
  type ThreadPanelProfile,
  type ThreadPanelProps,
} from '../components/ThreadPanel/ThreadPanel';
import { useChatWidget } from './context';

export interface ChatThreadsProps {
  /** The widget seated the rail as a sheet over the conversation rather than beside it. */
  overlay: boolean;
  /** Closes the sheet; a no-op on the inline rail. */
  close: () => void;
  /** The brand row's mark, in both seats. */
  logo?: ReactNode;
  /** The brand row's text. Shown only on the sheet, where the chat header is hidden behind it; the inline rail leaves it out. */
  logoText?: string;
  /** The signed-in person, shown on the inline rail. */
  profile?: ThreadPanelProfile;
  /** Whether the inline rail can collapse to its icon strip. */
  collapsible?: boolean;
  /**
   * Whether the inline rail starts expanded. Defaults to `false`: it starts
   * collapsed to its icon strip. The sheet, and a rail that is not
   * `collapsible`, always show expanded.
   */
  defaultExpanded?: boolean;
  /** Accessible heading over the history. */
  historyLabel?: string;
  /**
   * The words the ThreadPanel writes, merged over its English defaults: the
   * spoken pin and status text ("Pinned", "Working"…), each row's menu
   * trigger ("Thread options"), the rename field ("Rename thread"), the
   * projects header and its add button ("Projects", "New project"), and the
   * collapse toggle ("Collapse the panel", "Expand the panel"). The history's
   * own name is `historyLabel`.
   */
  threadPanelLabels?: Pick<
    ThreadPanelProps,
    | 'statusLabels'
    | 'pinnedLabel'
    | 'threadMenuLabel'
    | 'renameLabel'
    | 'projectsLabel'
    | 'newProjectLabel'
    | 'collapseLabel'
    | 'expandLabel'
  >;
  /** The rows of each thread's menu, by action; a key left out keeps its English. Defaults to "Pin", "Unpin", "Rename" and "Delete". */
  actionLabels?: Partial<Record<'pin' | 'unpin' | 'rename' | 'delete', string>>;
}

/**
 * The built-in session-history rail: a ThreadPanel over the provider's
 * thread lifecycle (`useThreads`). The widget seats it inline on a wide
 * host and as a slide-over sheet on a narrow one, and tells it which.
 */
export function ChatThreads({
  overlay,
  close,
  logo,
  logoText,
  profile,
  collapsible = true,
  defaultExpanded = false,
  historyLabel = 'Chat history',
  threadPanelLabels,
  actionLabels,
}: ChatThreadsProps) {
  const { threads } = useChatWidget();
  const [expanded, setExpanded] = useState(defaultExpanded);
  const hasProjects = threads.projects.length > 0;

  /* The lifecycle writes each row's menu in English; the labels are
     relabelled here by action id, so the ids the menu reports stay the ones
     `runAction` reads. Pin and unpin share an id, so the thread's own pin
     state says which word it wears. */
  const groups = useMemo(() => {
    if (!actionLabels) return threads.groups;
    return threads.groups.map((group) => ({
      ...group,
      threads: group.threads.map((thread) =>
        thread.actions
          ? {
              ...thread,
              actions: thread.actions.map((action) => {
                const key = action.id === 'pin' ? (thread.pinned ? 'unpin' : 'pin') : action.id;
                const label = actionLabels[key as keyof typeof actionLabels];
                return label === undefined ? action : { ...action, label };
              }),
            }
          : thread
      ),
    }));
  }, [threads.groups, actionLabels]);

  return (
    <ThreadPanel
      {...threadPanelLabels}
      groups={groups}
      activeThreadId={threads.activeThreadId}
      onThreadSelect={(id) => {
        threads.select(id);
        close();
      }}
      onThreadAction={threads.runAction}
      renamingThreadId={threads.renamingId ?? undefined}
      onThreadRename={threads.rename}
      onRenameCancel={() => threads.setRenamingId(null)}
      newThreadLabel={threads.newThreadLabel}
      onNewThread={() => {
        threads.startNew();
        close();
      }}
      historyLabel={historyLabel}
      projects={hasProjects ? threads.projects : undefined}
      activeProjectId={threads.activeProjectId}
      onProjectSelect={(id) => {
        threads.selectProject(id);
        close();
      }}
      onProjectCreate={hasProjects ? threads.createProject : undefined}
      logo={logo}
      logoText={overlay ? logoText : undefined}
      expanded={overlay || !collapsible ? true : expanded}
      onExpandedChange={overlay || !collapsible ? undefined : setExpanded}
      profile={overlay ? undefined : profile}
    />
  );
}

/* ============================================
   CHAT WIDGET — the composed chat and the launcher's panel chrome.

   .ds-chat-widget is the widget's internals: header, thread, composer,
   starters, disclaimer, and the optional rails. It fills whichever container
   hosts it; compact hosts (phone-width panels) set data-compact for the
   narrower insets.

   .ds-chat-launcher__* is ChatLauncher's chrome: the floating button, the
   fixed panel in its docked, overlay, floating and takeover forms, the scrim
   and the grips. The three variables on :root are the panel's geometry and
   the one contract a host stylesheet reads: --ds-chat-width (rewritten on
   <html> by the widen grip), --ds-chat-inset and --ds-chat-float-height.
   ============================================ */

:root {
  /* The docked panel's resting width; DOCK_MIN_WIDTH in placement.ts mirrors it. */
  --ds-chat-width: 420px;
  /* The gap the panel and the launcher float off the viewport edges. */
  --ds-chat-inset: 20px;
  /* The floating card's resting height. */
  --ds-chat-float-height: 640px;
}

.ds-chat-widget {
  display: flex;
  flex-direction: column;
  width: 100%;
  height: 100%;
  min-height: 0;
  /* A small breath above the header on every host: it seats the title row on
     the same line as the threads rail's own header, whose panel carries this
     inset built in. */
  padding-top: var(--padding-200);
  /* The one side inset every row shares (header controls, greeting, thread
     bubbles, composer edge, starter pills, disclaimer), so they sit on a
     single rail. A step tighter on compact hosts. */
  --ds-chat-widget-inset: var(--padding-500);
  /* A size container, so the welcome dressing below can step aside when the
     host is too short for it. */
  container-type: size;
  container-name: ds-chat-widget;
}

.ds-chat-widget[data-compact] {
  --ds-chat-widget-inset: var(--padding-400);
}

/* The header rides the same rail as everything under it; the component's
   own default is a step tighter than the widget wants. */
.ds-chat-widget .ds-chat-header {
  padding-inline: var(--ds-chat-widget-inset);
}

/* With a trailing panel seated inline, the controls stand over the panel's
   top inset and the header row has nothing 40px tall left in it, so it
   would collapse to the title's own line. The row
   holds the height its buttons were giving it: the control plus the
   header's own block padding either side. */
.ds-chat-widget[data-lifted-actions] .ds-chat-header {
  min-height: calc(40px + var(--padding-150) * 2);
}

/* The placement menu's wrapper is only there to catch Escape; it must not
   become a box of its own in the header's action row. */
.ds-chat-widget__placement-menu {
  display: contents;
}

/* Open, the menu says what the button is, so the tooltip stands down. And
   the trigger holds the passive wash while its menu is up: a control that
   is open says so. */
.ds-chat-widget__placement-menu .ds-tooltip:has([aria-expanded="true"]) .ds-tooltip__panel {
  display: none;
}

.ds-chat-widget__placement-menu .ds-circular-button[aria-expanded="true"],
.ds-chat-widget__placement-menu .ds-circular-button[aria-expanded="true"]:hover {
  background-color: var(--color-action-passive-bg-hover);
}

/* The open-sessions tab strip: its own row under the header, on the shared
   side inset. */
.ds-chat-widget__tabs-row {
  min-width: 0;
  padding: var(--padding-150) var(--ds-chat-widget-inset) 0;
}

/* The header brand: the mark beside the chat name. */
.ds-chat-widget__brand {
  display: inline-flex;
  align-items: center;
  gap: var(--gap-200);
  min-width: 0;
}

.ds-chat-widget__brand img {
  flex-shrink: 0;
}

.ds-chat-widget__brand-name {
  font-family: var(--font-title-body-family);
  font-size: var(--font-title-body-size);
  font-weight: var(--font-title-body-weight);
  line-height: var(--font-title-body-line-height);
  color: var(--color-text-primary);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* The top region: header + thread. Zero basis so welcome mode splits the
   height exactly with the bottom region, centring the composer. */
.ds-chat-widget__top {
  flex: 1 1 0;
  min-height: 0;
  display: flex;
  flex-direction: column;
}

/* The body hosts the thread, with the welcome greeting overlaid while the
   conversation is empty. */
.ds-chat-widget__body {
  flex: 1;
  min-height: 0;
  position: relative;
  display: flex;
  flex-direction: column;
}

/* The thread owns scrolling, gutters, fades, and send anchoring. However
   wide the container gets, the conversation column caps at 768px and
   centres; the header above is the one row that spans the full width. */
.ds-chat-widget__thread {
  flex: 1;
  --ds-chat-thread-content-max-width: 768px;
  /* Match the composer and header inset, so bubbles, composer edge, and
     the header controls all share one right rail. */
  --ds-chat-thread-padding-inline: var(--ds-chat-widget-inset);
}

/* ============================================
   WELCOME — the new-chat empty state
   ============================================ */

.ds-chat-widget__welcome {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  width: 100%;
  max-width: 768px;
  margin-inline: auto;
  /* The block-end padding is the gap between the greeting and the composer;
     block-start is inert, since the overlay bottom-aligns its content. */
  padding: var(--padding-500) var(--ds-chat-widget-inset) var(--gap-1000);
  pointer-events: none;
}

.ds-chat-widget__greeting {
  display: flex;
  flex-direction: column;
  gap: var(--gap-200);
}

/* Small and semibold over the ask line's large light face: the pair
   separates by weight contrast. Tertiary text, a step quieter than the ask
   line, so the time-of-day pleasantry supports the invitation rather than
   competing with it. */
.ds-chat-widget__hello {
  margin: 0;
  /* The greeting is read from the visitor's clock after mount, so this line
     is empty for the first paint. An empty block has no line box at all:
     reserve the height, or the ask line below jumps up a row and back. */
  min-height: var(--font-heading-3-line-height);
  font-family: var(--font-heading-3-family);
  font-size: var(--font-heading-3-size);
  font-weight: var(--font-heading-3-weight);
  line-height: var(--font-heading-3-line-height);
  letter-spacing: var(--font-heading-3-letter-spacing);
  color: var(--color-text-tertiary);
}

.ds-chat-widget__ask {
  margin: 0;
  font-family: var(--font-sub-display-family);
  font-size: var(--font-sub-display-size);
  font-weight: var(--font-sub-display-weight);
  line-height: var(--font-sub-display-line-height);
  letter-spacing: var(--font-sub-display-letter-spacing);
  color: var(--color-text-primary);
}

/* The panel is a viewport of its own. tokens-typography.css collapses
   sub-display to 24px/36px under a 768px *viewport*, but a docked panel is
   phone-width on a desktop window, where that media query still serves the
   30px desktop size into a 420px card. So the ask line takes the same step
   on the *container's* width, at the same 768px line. The values restate
   the token layer's own phone step rather than referencing it, because a
   value inside an unmatched media query is unreachable; tokens-typography.css
   owns the pair, and the two must move together. */
/* ds-allow(typography): the token layer's 768px sub-display step, restated for the panel's container width — tokens-typography.css owns the values */
@container ds-chat-widget (max-width: 768px) {
  .ds-chat-widget__ask {
    --font-sub-display-size: 24px;
    --font-sub-display-line-height: 36px;
  }
}

/* The bottom region: starters at its top, disclaimer pinned to its bottom.
   Grown while the chat is empty (centring the composer against the
   zero-basis top region), collapsing to the disclaimer's height on the
   first utterance. Basis stays 0 in both states so only flex-grow ever
   animates: the flow-down is one continuous glide. Reduced motion zeroes it
   via the token. */
.ds-chat-widget__bottom {
  display: flex;
  flex-direction: column;
  flex: 0 1 0;
  transition: flex-grow var(--motion-duration-slower) var(--motion-ease-entrance);
}

.ds-chat-widget__bottom--welcome {
  flex-grow: 1;
}

.ds-chat-widget__starters {
  width: 100%;
  max-width: 768px;
  margin-inline: auto;
  padding: var(--gap-1000) var(--ds-chat-widget-inset) 0;
}

/* The widget slot: any content, under the composer (and under the starters
   when both show), on the composer's own bounding box. The cap is the
   conversation column plus the side insets, so the slot's content edges
   land exactly on the composer's. */
.ds-chat-widget__widgets {
  width: 100%;
  max-width: calc(768px + 2 * var(--ds-chat-widget-inset));
  margin-inline: auto;
  padding: var(--gap-1000) var(--ds-chat-widget-inset) var(--padding-400);
}

/* With widgets the region takes its content's height before the slack is
   split, so the composer sits above centre by half the widgets' height
   rather than being squeezed against them. */
.ds-chat-widget__bottom--widgets {
  flex-basis: auto;
  flex-shrink: 0;
}

/* The widgets claim their height first, so on a short window an even split
   of what is left would crowd the greeting into the header. The top region
   keeps room for the header and the greeting. A phone never centres, so it
   has nothing to protect. */
.ds-chat-widget[data-widgets="fit"]:not([data-phone]) .ds-chat-widget__top {
  min-height: 236px;
}

/* The welcome dressing needs roughly 580px of widget for the greeting and
   460px for the starters. Shorter than that, each is decoration the layout
   cannot afford, so it steps aside and the empty state falls back to header,
   centred composer, disclaimer. */
@container ds-chat-widget (max-height: 579px) {
  .ds-chat-widget__welcome {
    display: none;
  }
}

@container ds-chat-widget (max-height: 459px) {
  .ds-chat-widget__starters {
    display: none;
  }
}

/* ============================================
   WIDGETS AS A PAGE — data-widgets="scroll"
   The welcome screen stops fitting itself to one viewport: the top region
   takes a fixed share of the height, the widgets take whatever they need on
   a wider column, and the widget scrolls as one page with the composer
   travelling with it. Nothing here outlives the welcome.
   ============================================ */

.ds-chat-widget[data-widgets="scroll"] {
  overflow-y: auto;
  overscroll-behavior: contain;

  /* The thread's scroll treatment, on the welcome page too. The scrollbar
     is invisible until the page is actually scrolling (data-scrolling, set
     by the widget and settled by MOTION_SCROLL_SETTLE_MS), with its gutter
     reserved so it never reflows the content sideways. */
  scrollbar-width: thin;
  scrollbar-gutter: stable;
  scrollbar-color: transparent transparent;
  transition: scrollbar-color var(--motion-duration-base) var(--motion-ease-standard);

  /* The bottom fade the thread has under the conversation: a CSS mask, so
     the widgets scrolling out through the floor pass through it. The root
     carries no background of its own, so only the content fades.
     ds-allow(color): mask alpha keywords (black/transparent), not palette colours */
  -webkit-mask-image: linear-gradient(to bottom, black calc(100% - var(--gap-1000)), transparent);
  mask-image: linear-gradient(to bottom, black calc(100% - var(--gap-1000)), transparent);
}

.ds-chat-widget[data-widgets="scroll"][data-scrolling] {
  scrollbar-color: var(--color-divider) transparent;
}

.ds-chat-widget[data-widgets="scroll"] .ds-chat-widget__top {
  flex: 0 0 auto;
  height: max(236px, 36cqh);
}

.ds-chat-widget[data-widgets="scroll"] .ds-chat-widget__footer {
  flex: 0 0 auto;
}

/* Never smaller than its content, and it takes any height left over, so
   when the widgets are short the disclaimer still rides the floor. */
.ds-chat-widget[data-widgets="scroll"] .ds-chat-widget__bottom {
  flex: 1 0 auto;
  transition: none;
}

/* A scrolling slot is never dropped for want of height, and ends with room
   under its last row. */
.ds-chat-widget[data-widgets="scroll"] .ds-chat-widget__widgets {
  display: block;
  padding-block: var(--gap-1000) var(--padding-1000);
}

/* A wide slot breaks out of the composer's box: a dashboard wants more
   width than a line of prose does. */
.ds-chat-widget[data-widgets-wide] .ds-chat-widget__widgets {
  max-width: 1080px;
}

/* The phone's bottom-pinned composer has nowhere to pin on a scrolling
   page, so the greeting goes back to sitting on the composer. */
.ds-chat-widget[data-widgets="scroll"][data-phone] .ds-chat-widget__welcome {
  justify-content: flex-end;
}

/* Widgets are the first dressing to go: they are the tallest, and a window
   too short for them still has room for the greeting and the composer. */
@container ds-chat-widget (max-height: 719px) {
  .ds-chat-widget__widgets {
    display: none;
  }
}

/* ============================================
   WELCOME ON A PHONE — data-phone
   The soft keyboard claims the lower half of a phone screen the moment the
   composer is focused, so a phone never centres: the top region takes all
   the slack, which pins the composer to the bottom from the first paint,
   the greeting floats in the middle of the empty thread, and the starters
   render directly above the composer.
   ============================================ */

.ds-chat-widget[data-phone] .ds-chat-widget__welcome {
  /* Restated, not inherited: the desktop height guard above hides the
     overlay under 580px, which is most phones once the keyboard is up. */
  display: flex;
  justify-content: center;
  padding-block: var(--padding-400);
}

.ds-chat-widget[data-phone] .ds-chat-widget__bottom--welcome {
  flex-grow: 0;
}

.ds-chat-widget[data-phone] .ds-chat-widget__bottom {
  transition: none;
}

/* Above the composer: its gap is the block-end padding now. */
.ds-chat-widget[data-phone] .ds-chat-widget__starters {
  display: block;
  padding-block: 0 var(--gap-400);
}

.ds-chat-widget[data-phone][data-widgets="fit"] .ds-chat-widget__widgets {
  padding-block: 0 var(--gap-400);
}

.ds-chat-widget[data-phone][data-widgets="scroll"] .ds-chat-widget__widgets {
  padding-block: var(--gap-500) var(--padding-500);
}

.ds-chat-widget[data-phone][data-widgets="scroll"] .ds-chat-widget__bottom--welcome {
  flex-grow: 1;
}

/* The phone stack needs less height than the centred layout, and it is the
   keyboard, not a short window, that usually takes it away. The greeting
   steps aside first, the starters only when even they would crowd the
   composer. */
@container ds-chat-widget (max-height: 499px) {
  .ds-chat-widget[data-phone] .ds-chat-widget__welcome {
    display: none;
  }
}

@container ds-chat-widget (max-height: 379px) {
  .ds-chat-widget[data-phone] .ds-chat-widget__starters {
    display: none;
  }
}

/* Locked to the bottom of the widget, in every state. */
.ds-chat-widget__disclaimer-row {
  margin-top: auto;
  padding: var(--gap-100) var(--ds-chat-widget-inset) var(--padding-200);
}

.ds-chat-widget__response {
  display: flex;
  flex-direction: column;
  gap: var(--gap-500);
}

/* No divider: the composer floats free of the transcript. */
.ds-chat-widget__footer {
  display: flex;
  flex-direction: column;
  /* The composer never gives up height in a squeeze. */
  flex-shrink: 0;
  padding: 0 var(--ds-chat-widget-inset);
}

/* The composer shares the conversation column's cap and centre. */
.ds-chat-widget__composer {
  width: 100%;
  max-width: 768px;
  margin-inline: auto;
  /* The panel is narrow and its welcome screen centres the composer, so
     queued files sit in smaller tiles here than a full-width composer's. */
  --ds-attachment-tile-size: 104px;
}

/* One quiet line, centred with the composer column, at the floor of the
   type scale: a visitor can find it, and never has to read it to chat. */
.ds-chat-widget__disclaimer {
  margin: 0;
  text-align: center;
  font-family: var(--font-caption-family);
  font-size: var(--font-caption-size);
  font-weight: var(--font-caption-weight);
  line-height: var(--font-caption-line-height);
  letter-spacing: var(--font-caption-letter-spacing);
  color: var(--color-text-tertiary);
}

.ds-chat-widget__disclaimer a {
  color: inherit;
  text-decoration: underline;
  text-underline-offset: 2px;
}

/* ============================================
   MESSAGE ACTIONS — the copy and thumbs row under a committed assistant turn.
   ============================================ */

.ds-chat-widget__action {
  display: grid;
  place-items: center;
  padding: var(--padding-100);
  border: none;
  border-radius: var(--radius-pill);
  background: transparent;
  cursor: pointer;
  transition: background-color var(--motion-duration-fast) var(--motion-ease-standard);
}

.ds-chat-widget__action:hover {
  background-color: var(--color-action-passive-bg-hover);
}

.ds-chat-widget__action:active {
  background-color: var(--color-action-passive-bg-active);
}

.ds-chat-widget__action-icon {
  /* Both of the copy button's icons share this single grid cell, so the
     swap happens in place rather than reflowing the row. */
  grid-area: 1 / 1;
  --icon-size: var(--icon-size-500);
  color: var(--color-icon-secondary);
  transition:
    opacity var(--motion-duration-fast) var(--motion-ease-standard),
    transform var(--motion-duration-fast) var(--motion-ease-standard),
    color var(--motion-duration-fast) var(--motion-ease-standard);
}

.ds-chat-widget__action:hover .ds-chat-widget__action-icon {
  color: var(--color-icon-primary);
}

/* The hidden half of the copy swap: faded and slightly shrunk, so the
   arriving icon reads as popping in rather than teleporting. */
.ds-chat-widget__action-icon--hidden {
  opacity: 0;
  transform: scale(0.6);
}

/* The tick wears the positive status role while it shows. */
.ds-chat-widget__action-icon--tick,
.ds-chat-widget__action:hover .ds-chat-widget__action-icon--tick {
  color: var(--color-status-positive-border);
}

/* A chosen thumb: filled glyph, full-strength colour, no hover needed. */
.ds-chat-widget__action[aria-pressed="true"] .ds-chat-widget__action-icon {
  --material-symbols-fill: 1;
  color: var(--color-icon-primary);
}

/* ============================================
   FOLLOW-UP SUGGESTIONS — the chips under an answer.
   ============================================ */

.ds-chat-widget__followups {
  width: 100%;
  margin-top: var(--gap-200);
  /* They land a beat after the answer commits, so they arrive rather than
     appear. Reduced motion zeroes the duration through the token. */
  animation: ds-chat-widget-followups-in var(--motion-duration-slow) var(--motion-ease-entrance) both;
}

@keyframes ds-chat-widget-followups-in {
  from {
    opacity: 0;
    transform: translateY(var(--gap-100));
  }
}

/* ============================================
   THE RAILS — the optional session-history rail (leading) and agent pane
   (trailing). Wide widgets seat them inline; narrow ones summon the history
   from the header hamburger as a slide-over sheet and the agent pane from a
   header button as a bottom sheet, each behind a scrim.
   ============================================ */

.ds-chat-widget__rails {
  position: relative;
  display: flex;
  width: 100%;
  height: 100%;
  min-height: 0;
  overflow: hidden;
}

.ds-chat-widget--with-threads {
  flex: 1;
  min-width: 0;
}

.ds-chat-widget__threads-rail {
  flex: none;
  display: flex;
  min-height: 0;
  border-right: var(--border-025) solid var(--color-bg-container-border);
}

/* The sheet layer: hidden entirely (visibility) while closed, so nothing in
   it can take focus or reach assistive technology. */
.ds-chat-widget__threads-overlay,
.ds-chat-widget__aside-overlay {
  position: absolute;
  inset: 0;
  z-index: 5;
  visibility: hidden;
  transition: visibility 0s var(--motion-duration-slow);
}

.ds-chat-widget__threads-overlay--open,
.ds-chat-widget__aside-overlay--open {
  visibility: visible;
  transition: visibility 0s;
}

.ds-chat-widget__rail-scrim {
  position: absolute;
  inset: 0;
  border: none;
  padding: 0;
  background-color: var(--color-scrim);
  cursor: pointer;
  opacity: 0;
  transition: opacity var(--motion-duration-slow) var(--motion-ease-standard);
}

.ds-chat-widget__threads-overlay--open .ds-chat-widget__rail-scrim,
.ds-chat-widget__aside-overlay--open .ds-chat-widget__rail-scrim {
  opacity: 1;
}

/* The glass recipe: the translucent fill over a backdrop blur, so the
   dimmed chat shows through the sheet. */
.ds-chat-widget__threads-sheet {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  display: flex;
  background-color: var(--color-bg-glass);
  backdrop-filter: blur(24px);
  border-right: var(--border-025) solid var(--color-bg-container-border);
  box-shadow: var(--shadow-floating);
  transform: translateX(-100%);
  transition: transform var(--motion-duration-slow) var(--motion-ease-emphasized);
}

.ds-chat-widget__threads-overlay--open .ds-chat-widget__threads-sheet {
  transform: translateX(0);
}

/* The agent rail floats rather than butting against the widget's edges: its
   own rounded card, inset on three sides. The top margin is the header
   row's exact height (the chat column's top padding, plus the header's own
   block padding either side of a 40px control), so the panel begins where
   that row ends and the widget's controls sit in the clear above it. */
.ds-chat-widget__aside-rail {
  display: flex;
  flex: none;
  /* The open and close glide, the artifact panel's own: the rail's width
     runs from nothing to the pane's, and the card is the rail at every
     frame, a whole rounded card growing from the trailing edge with its
     content revealed behind the leading border. The target is the pane's
     natural width, which the widget measures and hands over as
     --ds-chat-aside-width (a rail holds a width of its own, so there is no
     share of the row to animate as the artifact does). Closed, the rail
     keeps no width, no inset and no border, and goes invisible once the
     collapse has finished (the visibility delay), so nothing of it can be
     seen, hovered or reached. The reduced-motion guard in tokens-motion.css
     zeroes every duration here. */
  width: 0;
  min-width: 0;
  min-height: 0;
  margin: calc(var(--padding-200) + var(--padding-150) * 2 + 40px) 0 var(--padding-500) 0;
  opacity: 0;
  visibility: hidden;
  overflow: hidden;
  transition:
    width var(--motion-duration-slow) var(--motion-ease-emphasized),
    margin var(--motion-duration-slow) var(--motion-ease-emphasized),
    opacity var(--motion-duration-base) var(--motion-ease-standard),
    visibility 0s linear var(--motion-duration-slow);
}

.ds-chat-widget__aside-rail--open {
  /* Before the first measurement there is no number to glide to, so the
     rail simply takes its content's width. */
  width: var(--ds-chat-aside-width, max-content);
  margin-right: var(--padding-500);
  opacity: 1;
  visibility: visible;
  transition:
    width var(--motion-duration-slow) var(--motion-ease-emphasized),
    margin var(--motion-duration-slow) var(--motion-ease-emphasized),
    opacity var(--motion-duration-base) var(--motion-ease-standard) calc(var(--motion-duration-slow) - var(--motion-duration-base)),
    visibility 0s linear 0s;
}

/* The pane's card fills the rail, so the two are one shape through the
   glide; the pane inside keeps its own width and is clipped by the card. A
   trailing panel is a solid surface, the page's own ground, not the
   widget's glass: it is a place to read and work in, and what shows through
   glass (the host's page, an ambient background) would sit under its
   content. */
.ds-chat-widget__aside-rail-inner {
  box-sizing: border-box;
  display: flex;
  flex: 1 0 auto;
  width: 100%;
  min-width: 0;
  min-height: 0;
  border: var(--border-025) solid var(--color-bg-container-border);
  border-radius: var(--radius-600);
  background-color: var(--color-bg-page-primary);
  overflow: hidden;
}

/* The pane never squeezes with the card around it. */
.ds-chat-widget__aside-rail-inner > * {
  flex: none;
}

/* ============================================
   THE ARTIFACT PANEL — the trailing seat's other tenant. Wide widgets seat
   it beside the conversation as a second column; narrow ones raise it as a
   tall bottom sheet. Unlike the agent rail it has no width of its own: it
   shares the row with the conversation, a little the larger of the two.
   ============================================ */

/* Any child of the row that is the conversation takes the room the rails
   leave, and can shrink under an artifact. */
.ds-chat-widget__rails > .ds-chat-widget {
  flex: 1 1 0;
  min-width: 0;
}

/* The artifact's card floats exactly as the agent rail's does: inset from
   the widget's edges, beginning under the header row (the same top margin,
   the row's own height), with the widget's lifted controls in the clear
   above it. The glide is the flex share running from nothing, the card
   fading in behind it; closed, the rail keeps no width and no inset and
   goes invisible once the collapse has finished. The reduced-motion guard
   in tokens-motion.css zeroes every duration here. */
.ds-chat-widget__artifact-rail {
  display: flex;
  flex: 0 1 0;
  min-width: 0;
  min-height: 0;
  margin: calc(var(--padding-200) + var(--padding-150) * 2 + 40px) 0 var(--padding-500) 0;
  opacity: 0;
  visibility: hidden;
  overflow: hidden;
  transition:
    flex-grow var(--motion-duration-slow) var(--motion-ease-emphasized),
    margin var(--motion-duration-slow) var(--motion-ease-emphasized),
    opacity var(--motion-duration-base) var(--motion-ease-standard),
    visibility 0s linear var(--motion-duration-slow);
}

.ds-chat-widget__artifact-rail--open {
  flex-grow: 1.2;
  margin-right: var(--padding-500);
  opacity: 1;
  visibility: visible;
  transition:
    flex-grow var(--motion-duration-slow) var(--motion-ease-emphasized),
    margin var(--motion-duration-slow) var(--motion-ease-emphasized),
    opacity var(--motion-duration-base) var(--motion-ease-standard) calc(var(--motion-duration-slow) - var(--motion-duration-base)),
    visibility 0s linear 0s;
}

.ds-chat-widget__artifact-rail-inner {
  display: flex;
  flex: 1;
  min-width: 0;
  min-height: 0;
  border: var(--border-025) solid var(--color-bg-container-border);
  border-radius: var(--radius-600);
  /* Solid, the agent pane's ground: see the aside rail's card. */
  background-color: var(--color-bg-page-primary);
  overflow: hidden;
}

/* The panel opened before the conversation has made anything. */
.ds-chat-widget__artifact-empty {
  display: grid;
  place-items: center;
  min-height: 100%;
  padding: var(--padding-400);
}

/* Sized by the grip: the panel holds the width the visitor gave it, and
   gives it back before the conversation drops under its floor (the 320px
   mirrors ARTIFACT_MIN_COLUMN_WIDTH in queries.ts). */
.ds-chat-widget__rails[data-artifact-sized] > .ds-chat-widget__artifact-rail--open {
  flex: 0 1 var(--ds-chat-artifact-width);
}

.ds-chat-widget__rails[data-artifact-sized] > .ds-chat-widget {
  flex: 1 0 320px;
}

/* The pointer drives the width frame by frame, so the glides stand down
   and nothing under the drag selects. */
.ds-chat-widget__rails[data-artifact-resizing] {
  user-select: none;
}

.ds-chat-widget__rails[data-artifact-resizing] > .ds-chat-widget__artifact-rail {
  transition: none;
}

/* The grip: the dock's widen grip, restated for the card's leading edge. A
   20px grab zone straddling the border, with a hover-revealed 4×48px pill.
   The seat itself has no width, so the row's layout never knows it is
   there; the zone spans the card's own height. */
.ds-chat-widget__artifact-grip {
  position: relative;
  z-index: 4;
  flex: none;
  width: 0;
  margin: calc(var(--padding-200) + var(--padding-150) * 2 + 40px) 0 var(--padding-500) 0;
  cursor: ew-resize;
  touch-action: none;
}

.ds-chat-widget__artifact-grip::before {
  content: "";
  position: absolute;
  top: 0;
  bottom: 0;
  left: -10px;
  width: 20px;
}

.ds-chat-widget__artifact-grip::after {
  content: "";
  position: absolute;
  top: calc(50% - 24px);
  left: -2px;
  width: 4px;
  height: 48px;
  border-radius: var(--radius-pill);
  background: transparent;
  transition: background var(--motion-duration-fast) var(--motion-ease-standard);
}

.ds-chat-widget__artifact-grip:hover::after,
.ds-chat-widget__artifact-grip--resizing::after {
  background: var(--color-text-tertiary);
}

.ds-chat-widget__artifact-grip:active::after {
  background: var(--color-text-secondary);
}

/* Expanded, the artifact has the widget: the conversation and the history
   leave the row (and with them the tab order), and the card takes an inset
   on its leading edge too. */
.ds-chat-widget__rails[data-artifact-expanded] > .ds-chat-widget,
.ds-chat-widget__rails[data-artifact-expanded] > .ds-chat-widget__threads-rail {
  display: none;
}

.ds-chat-widget__rails[data-artifact-expanded] > .ds-chat-widget__artifact-rail--open {
  flex: 1 1 0;
  margin-left: var(--padding-500);
}

/* The sheet runs nearly the widget's height: a preview has no natural
   height to hug, and a short frame is no preview. The strip left above it
   keeps the header, and so the way back, in view. */
.ds-chat-widget__aside-sheet--artifact {
  height: 92%;
  max-height: none;
}

/* The room the floating controls take in the header row while no panel is
   up: as many 40px controls as the cluster holds, a gap between each. */
.ds-chat-widget__actions-spacer {
  flex: none;
  width: calc(
    var(--ds-chat-action-count) * 40px + (var(--ds-chat-action-count) - 1) * var(--gap-100)
  );
  height: 40px;
}

/* The widget's controls at the card's own top trailing corner, their one
   home wherever a trailing panel can seat inline. */
.ds-chat-widget__rail-actions {
  position: absolute;
  top: calc(var(--padding-200) + var(--padding-150));
  right: var(--padding-500);
  z-index: 6;
  display: flex;
  align-items: center;
  gap: var(--gap-100);
}

/* Narrow hosts raise the agent pane from the bottom: a phone's secondary
   surface comes up from the edge the thumb is nearest. Deliberately short
   of the full height, so the last turns stay visible above it. */
.ds-chat-widget__aside-sheet {
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  display: flex;
  flex-direction: column;
  max-height: 82%;
  /* The same solid ground the panel has inline: one panel, two seats. */
  background-color: var(--color-bg-page-primary);
  border-top: var(--border-025) solid var(--color-bg-container-border);
  border-radius: var(--radius-600) var(--radius-600) 0 0;
  box-shadow: var(--shadow-floating);
  transform: translateY(100%);
  transition: transform var(--motion-duration-slow) var(--motion-ease-emphasized);
}

.ds-chat-widget__aside-overlay--open .ds-chat-widget__aside-sheet {
  transform: translateY(0);
}

.ds-chat-widget__aside-grabber {
  flex: none;
  width: 36px;
  height: 4px;
  margin: var(--gap-200) auto 0;
  border-radius: var(--radius-pill);
  background-color: var(--color-divider);
}

.ds-chat-widget__aside-sheet-body {
  display: flex;
  flex: 1;
  min-height: 0;
}

/* The agent toggle's on-state: the passive wash, held down while the panel
   is up. Paired with the library class so it beats the variant's resting
   background whatever order the stylesheets load in. */
.ds-circular-button.ds-chat-widget__agent-toggle--on,
.ds-circular-button.ds-chat-widget__agent-toggle--on:hover {
  background-color: var(--color-action-passive-bg-hover);
}

/* ============================================
   THE LAUNCHER'S PANEL — a card inset from the viewport edges, docked above
   the threshold to the edge the visitor chose; an overlay with a scrim below
   it; a free, non-modal card when floated; a blurred full takeover in
   fullscreen view. On phones it fills the viewport.
   ============================================ */

.ds-chat-launcher__panel {
  position: fixed;
  top: var(--ds-chat-inset);
  /* Placed from the left on both docks, so one property carries every move
     the card makes and they all glide. */
  left: calc(100% - var(--ds-chat-width) - var(--ds-chat-inset));
  height: calc(100dvh - var(--ds-chat-inset) * 2);
  width: var(--ds-chat-width);
  max-width: calc(100vw - var(--ds-chat-inset) * 2);
  display: flex;
  flex-direction: column;
  /* The glass token: deliberately translucent in both themes, so the page's
     colours reach the surface; the blur is what keeps the transcript
     readable over them. */
  background: var(--color-bg-glass);
  border: var(--border-025) solid var(--color-bg-container-border);
  border-radius: var(--radius-600);
  box-shadow: var(--shadow-floating);
  overflow: hidden;
  backdrop-filter: blur(24px);
  z-index: var(--layer-chat-panel);
  /* The panel-to-takeover glide: the same card grows to fill the viewport,
     so every property that differs between the two views animates together. */
  transition:
    top var(--motion-duration-slow) var(--motion-ease-emphasized),
    left var(--motion-duration-slow) var(--motion-ease-emphasized),
    width var(--motion-duration-slow) var(--motion-ease-emphasized),
    height var(--motion-duration-slow) var(--motion-ease-emphasized),
    max-width var(--motion-duration-slow) var(--motion-ease-emphasized),
    border-radius var(--motion-duration-slow) var(--motion-ease-emphasized),
    border-color var(--motion-duration-slow) var(--motion-ease-emphasized),
    backdrop-filter var(--motion-duration-slow) var(--motion-ease-emphasized);
  /* Open: the card fades in with a small rise from its resting spot. Plays
     on mount, so the view toggle, which keeps the node, never replays it. */
  animation: ds-chat-launcher-panel-in var(--motion-duration-slow) var(--motion-ease-entrance);
}

/* The widen grip drives --ds-chat-width frame by frame; the width glide
   above would rubber-band behind the pointer, so resizing suspends it. */
html[data-chat-resizing] .ds-chat-launcher__panel {
  transition: none;
}

/* Close: the mirror image. The provider keeps the panel mounted for
   MOTION_EXIT_SYNC_MS while this plays, and pointer-events off so a dying
   panel swallows no clicks. */
.ds-chat-launcher__panel--closing {
  animation: ds-chat-launcher-panel-out var(--motion-duration-base) var(--motion-ease-standard) forwards;
  pointer-events: none;
}

@keyframes ds-chat-launcher-panel-in {
  from {
    opacity: 0;
    transform: translateY(10px);
  }

  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes ds-chat-launcher-panel-out {
  to {
    opacity: 0;
    transform: translateY(10px);
  }
}

/* The left dock: the same card on the other edge. */
.ds-chat-launcher__panel--left {
  left: var(--ds-chat-inset);
}

/* Fullscreen view: a true viewport takeover. The stronger blur keeps the
   transcript readable while the page's colours still shine through. The
   border fades rather than vanishing, so the geometry never snaps mid-glide. */
.ds-chat-launcher__panel--full {
  top: 0;
  left: 0;
  height: 100dvh;
  width: 100vw;
  max-width: 100vw;
  border-color: transparent;
  border-radius: 0;
  backdrop-filter: blur(40px);
}

/* Below the dock threshold the panel overlays the page behind a scrim. */
.ds-chat-launcher__scrim {
  position: fixed;
  inset: 0;
  background: var(--color-scrim);
  z-index: var(--layer-chat-scrim);
  animation: ds-chat-launcher-scrim-in var(--motion-duration-slow) var(--motion-ease-standard);
}

@keyframes ds-chat-launcher-scrim-in {
  from {
    opacity: 0;
  }
}

/* The widen grip: a 20px grab zone straddling the panel's inner edge, with
   a hover-revealed 4×48px pill. A fixed sibling of the panel, positioned
   from the same variables, so it tracks the edge as the drag rewrites
   --ds-chat-width. */
.ds-chat-launcher__dock-handle {
  position: fixed;
  top: var(--ds-chat-inset);
  height: calc(100dvh - var(--ds-chat-inset) * 2);
  right: calc(var(--ds-chat-inset) + var(--ds-chat-width) - 10px);
  width: 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: ew-resize;
  touch-action: none;
  z-index: calc(var(--layer-chat-panel) + 1);
}

.ds-chat-launcher__dock-handle--left {
  right: auto;
  left: calc(var(--ds-chat-inset) + var(--ds-chat-width) - 10px);
}

.ds-chat-launcher__dock-handle::after {
  content: "";
  width: 4px;
  height: 48px;
  border-radius: var(--radius-pill);
  background: transparent;
  transition: background var(--motion-duration-fast) var(--motion-ease-standard);
}

.ds-chat-launcher__dock-handle:hover::after,
.ds-chat-launcher__dock-handle--resizing::after {
  background: var(--color-text-tertiary);
}

.ds-chat-launcher__dock-handle:active::after {
  background: var(--color-text-secondary);
}

/* On short viewports the vertical insets are height the widget needs more
   than the chrome does. */
@media (max-height: 619px) {
  .ds-chat-launcher__panel {
    top: 0;
    height: 100dvh;
  }

  .ds-chat-launcher__dock-handle {
    top: 0;
    height: 100dvh;
  }
}

/* Floating: popped out of the dock into a shorter card the visitor drags by
   its header. The launcher writes the position variables once it has been
   moved; until then it rests in the launcher's corner. After the
   short-viewport rule above on purpose, so the card keeps its own height. */
.ds-chat-launcher__panel--floating {
  --ds-chat-float-h: min(
    var(--ds-chat-float-height),
    calc(100dvh - var(--ds-chat-inset) * 2)
  );
  top: var(--ds-chat-float-y, calc(100dvh - var(--ds-chat-float-h) - var(--ds-chat-inset)));
  left: var(--ds-chat-float-x, calc(100% - var(--ds-chat-width) - var(--ds-chat-inset)));
  width: var(--ds-chat-float-w, var(--ds-chat-width));
  height: var(--ds-chat-float-h);
  max-height: 100dvh;
}

/* The size grips: an 8px zone along each edge and a 16px square in each
   corner, all inside the card. */
.ds-chat-launcher__float-grip {
  position: absolute;
  /* ds-allow(stacking): local order inside the floating card, above its own content; the card itself sits on --layer-chat-panel. */
  z-index: 10;
  display: flex;
  align-items: center;
  justify-content: center;
  touch-action: none;
}

.ds-chat-launcher__float-grip[data-dir="n"],
.ds-chat-launcher__float-grip[data-dir="s"] {
  left: 16px;
  right: 16px;
  height: 8px;
  cursor: ns-resize;
}

.ds-chat-launcher__float-grip[data-dir="e"],
.ds-chat-launcher__float-grip[data-dir="w"] {
  top: 16px;
  bottom: 16px;
  width: 8px;
  cursor: ew-resize;
}

.ds-chat-launcher__float-grip[data-dir="n"] { top: 0; }
.ds-chat-launcher__float-grip[data-dir="s"] { bottom: 0; }
.ds-chat-launcher__float-grip[data-dir="e"] { right: 0; }
.ds-chat-launcher__float-grip[data-dir="w"] { left: 0; }

.ds-chat-launcher__float-grip[data-dir="ne"],
.ds-chat-launcher__float-grip[data-dir="nw"],
.ds-chat-launcher__float-grip[data-dir="se"],
.ds-chat-launcher__float-grip[data-dir="sw"] {
  width: 16px;
  height: 16px;
}

.ds-chat-launcher__float-grip[data-dir="ne"] { top: 0; right: 0; cursor: nesw-resize; }
.ds-chat-launcher__float-grip[data-dir="sw"] { bottom: 0; left: 0; cursor: nesw-resize; }
.ds-chat-launcher__float-grip[data-dir="nw"] { top: 0; left: 0; cursor: nwse-resize; }
.ds-chat-launcher__float-grip[data-dir="se"] { bottom: 0; right: 0; cursor: nwse-resize; }

.ds-chat-launcher__float-grip[data-dir="n"]::after,
.ds-chat-launcher__float-grip[data-dir="s"]::after,
.ds-chat-launcher__float-grip[data-dir="e"]::after,
.ds-chat-launcher__float-grip[data-dir="w"]::after {
  content: "";
  border-radius: var(--radius-pill);
  background: transparent;
  transition: background var(--motion-duration-fast) var(--motion-ease-standard);
}

.ds-chat-launcher__float-grip[data-dir="n"]::after,
.ds-chat-launcher__float-grip[data-dir="s"]::after {
  width: 48px;
  height: 4px;
}

.ds-chat-launcher__float-grip[data-dir="e"]::after,
.ds-chat-launcher__float-grip[data-dir="w"]::after {
  width: 4px;
  height: 48px;
}

.ds-chat-launcher__float-grip:hover::after {
  background: var(--color-text-tertiary);
}

.ds-chat-launcher__float-grip:active::after {
  background: var(--color-text-secondary);
}

.ds-chat-launcher__panel--floating .ds-chat-header {
  cursor: grab;
  touch-action: none;
}

html[data-chat-resizing] .ds-chat-launcher__panel--floating .ds-chat-header {
  cursor: grabbing;
}

/* Phone widths: the chat is the document, not an overlay. The panel leaves
   the fixed layer for normal flow at 100dvh, and the host hides the page
   around it on the takeover attribute, so the soft keyboard is handled the
   way the browser handles any page with a field at the bottom. The launcher
   reads the same threshold as TAKEOVER_QUERY; this rule covers the first
   render, before a media query has been read, so the two must stay in step.
   No transition: there is no card form to glide from. */
@media (max-width: 719px) {
  .ds-chat-launcher__panel {
    position: relative;
    top: auto;
    left: auto;
    height: 100dvh;
    width: 100%;
    max-width: none;
    border: none;
    border-radius: 0;
    box-shadow: none;
    transition: none;
  }
}

/* ============================================
   THE FAB — the chat's persistent entry point, bottom right on every page.
   Hidden while the panel is open; the panel's close returns here.
   ============================================ */

.ds-chat-launcher__fab {
  position: fixed;
  right: var(--ds-chat-inset);
  bottom: var(--ds-chat-inset);
  z-index: var(--layer-chat-launcher);
}

/* The button's own solid field keeps it legible over whatever content
   scrolls beneath it; the FAB only adds the floating elevation. No
   backdrop-filter here: the fill is opaque, and an ancestor backdrop root
   would blind the summary panel's frost. */
.ds-chat-launcher__fab .ds-ai-button {
  border-radius: var(--radius-pill);
  box-shadow: var(--shadow-floating);
}

