'use client';

import { createContext, useContext } from 'react';
import { PromptSuggestions } from '../components/PromptSuggestions/PromptSuggestions';
import { useChatWidget } from './context';

/* Carried by context, like the reply row's labels, because the row sits under
   ChatWidget through AssistantTurn; ChatWidget's `followupsLabel` feeds it. */
// eslint-disable-next-line react-refresh/only-export-components -- the label context is the row's one input from ChatWidget and lives with the row
export const FollowupSuggestionsLabelContext = createContext('Follow-up questions');

/**
 * The follow-up questions under a finished answer. Deliberately the same
 * component, layout and scale as the welcome screen's conversation starters:
 * one pattern for "here is something you could ask", whether the conversation
 * has started or not. The only difference is where the questions come from.
 *
 * Tapping one sends it as the next message and keeps the row as the record
 * of that choice: the chip checked, the rest dimmed and inert. A tap while a
 * response is already streaming is ignored by `send`, the same as pressing
 * enter in the composer would be, and leaves the row as it was.
 *
 * While the questions are still being generated, `pending` shows the row's
 * shimmer placeholders in their place: a real loading state, unlike the
 * welcome starters' staged one.
 */
export function FollowupSuggestions({
  turnId,
  suggestions,
  pending = false,
  entrance = true,
  chosen,
  chosenLabel,
}: {
  /** The turn these belong to; makes each suggestion's id unique in the thread. */
  turnId: string;
  suggestions: string[];
  /** The follow-ups request is still in flight; show placeholders. */
  pending?: boolean;
  /** Play the chips' staggered pop-in. Off for rows remounted by a reopen, whose suggestions already arrived once. */
  entrance?: boolean;
  /** The label already sent from this row, which keeps the row as a record. */
  chosen?: string;
  /** Visually hidden text read after the sent suggestion. Defaults to PromptSuggestions' "(chosen)". */
  chosenLabel?: string;
}) {
  const { chooseFollowup } = useChatWidget();
  const rowLabel = useContext(FollowupSuggestionsLabelContext);

  const items = suggestions.map((label, index) => ({
    id: `${turnId}-followup-${index}`,
    label,
  }));

  return (
    <PromptSuggestions
      className="ds-chat-widget__followups"
      layout="stack"
      ariaLabel={rowLabel}
      chosenLabel={chosenLabel}
      pending={pending}
      entrance={entrance}
      suggestions={items}
      value={chosen !== undefined ? items.find((item) => item.label === chosen)?.id : undefined}
      onValueChange={(id) => {
        const item = items.find((candidate) => candidate.id === id);
        if (item) chooseFollowup(turnId, item.label);
      }}
    />
  );
}

'use client';

import { createContext, useContext, useEffect, useRef, useState } from 'react';
import { MOTION_FEEDBACK_RESET_MS } from '../tokens/motion';
import { useChatWidget } from './context';
import type { ChatTurn } from './types';
import '../behaviors/visually-hidden.css';

/** The row's accessible names and its copy announcement, set from ChatWidget's label props. */
export interface ResponseActionsLabels {
  /** The copy button's name. */
  copy: string;
  /** The copy button's name once the copy has landed. */
  copied: string;
  /** What the polite live region says once the copy has landed. */
  copiedAnnouncement: string;
  /** The thumbs-up button's name. */
  good: string;
  /** The thumbs-down button's name. */
  bad: string;
}

/* Carried by context rather than props because the row sits two levels under
   ChatWidget (through AssistantTurn), and only the widget's own label props
   ever set it. */
// eslint-disable-next-line react-refresh/only-export-components -- the labels context is the row's one input from ChatWidget and lives with the row
export const ResponseActionsLabelsContext = createContext<ResponseActionsLabels>({
  copy: 'Copy response',
  copied: 'Copied',
  copiedAnnouncement: 'Copied to clipboard',
  good: 'Good response',
  bad: 'Bad response',
});

/**
 * The row under a committed assistant turn: copy, and, when the server
 * logged the exchange and the provider has somewhere to send a verdict,
 * thumbs up and down. A scripted transport never sends an exchange id, so
 * it shows copy alone: the thumbs would have nothing to rate.
 *
 * Deliberately not the library's MessageActions component: its items API
 * swaps an icon by name, which cannot crossfade, and this row's copied-tick
 * (status colour, scale-and-fade swap) and filled chosen thumb both need
 * styling per element that the items shape does not carry.
 *
 * Copy takes the turn's raw markdown, not the rendered text: it pastes back
 * into anything that reads markdown, and plain readers still get the words.
 */
export function ResponseActions({ turn }: { turn: ChatTurn }) {
  const { submitFeedback } = useChatWidget();
  const labels = useContext(ResponseActionsLabelsContext);
  const [copied, setCopied] = useState(false);
  const revertTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(
    () => () => {
      if (revertTimer.current !== null) clearTimeout(revertTimer.current);
    },
    []
  );

  const copy = async () => {
    try {
      await navigator.clipboard.writeText(turn.text);
    } catch {
      // Clipboard denied: nothing was copied, so the button must not say it was.
      return;
    }
    setCopied(true);
    if (revertTimer.current !== null) clearTimeout(revertTimer.current);
    revertTimer.current = setTimeout(() => setCopied(false), MOTION_FEEDBACK_RESET_MS);
  };

  const vote = (verdict: 'up' | 'down') => {
    if (!turn.exchangeId || !submitFeedback || turn.feedback === verdict) return;
    submitFeedback(turn.id, turn.exchangeId, verdict);
  };

  const iconClass = (hidden: boolean, tick = false) =>
    [
      'ds-chat-widget__action-icon',
      tick ? 'ds-chat-widget__action-icon--tick' : '',
      hidden ? 'ds-chat-widget__action-icon--hidden' : '',
      'material-symbols-rounded',
    ]
      .filter(Boolean)
      .join(' ');

  return (
    <>
      <button
        type="button"
        className="ds-chat-widget__action"
        onClick={copy}
        aria-label={copied ? labels.copied : labels.copy}
      >
        {/* Both icons occupy the same cell; the swap is a crossfade-and-scale
            between them, not a text change, which is what makes it animatable. */}
        <span className={iconClass(copied)} aria-hidden="true">
          content_copy
        </span>
        <span className={iconClass(!copied, true)} aria-hidden="true">
          check
        </span>
      </button>

      {turn.exchangeId && submitFeedback && (
        <>
          <button
            type="button"
            className="ds-chat-widget__action"
            onClick={() => vote('up')}
            aria-label={labels.good}
            aria-pressed={turn.feedback === 'up'}
          >
            <span className={iconClass(false)} aria-hidden="true">
              thumb_up
            </span>
          </button>
          <button
            type="button"
            className="ds-chat-widget__action"
            onClick={() => vote('down')}
            aria-label={labels.bad}
            aria-pressed={turn.feedback === 'down'}
          >
            <span className={iconClass(false)} aria-hidden="true">
              thumb_down
            </span>
          </button>
        </>
      )}

      {/* The visual state change is silent to a screen reader; this is not. */}
      <span className="ds-visually-hidden" aria-live="polite">
        {copied ? labels.copiedAnnouncement : ''}
      </span>
    </>
  );
}

'use client';

import { useContext } from 'react';
import { cardArtifact } from './artifacts';
import { ChatArtifactCard } from './ChatArtifactCard';
import { ArtifactSeatContext, useChatWidget } from './context';
import type { ChatCard } from './types';

/**
 * A turn's `card`, drawn through the provider's renderers. A kind with no
 * renderer draws nothing: a card is an enrichment of an answer that already
 * stands in text, so an unknown kind degrades to the words alone. The one
 * built-in kind is the artifact, drawn as its tile unless the host has
 * taken the kind over with a renderer of its own.
 */
export function TurnCard({ card }: { card: ChatCard }) {
  const { renderers } = useChatWidget();
  const artifactSeat = useContext(ArtifactSeatContext);
  const render = renderers[card.kind];
  if (!render) {
    /* No seat, no tile: a widget with `artifacts` off has no panel for the
       tile to open, and the answer already stands in its text. */
    const artifact = artifactSeat ? cardArtifact(card) : null;
    return artifact ? <ChatArtifactCard artifact={artifact} /> : null;
  }
  return <>{render(card.data)}</>;
}

'use client';

import { useEffect, useRef } from 'react';
import {
  QuestionCard,
  QuestionSummary,
  type QuestionCardLabels,
} from '../components/QuestionCard/QuestionCard';
import { useChatWidget } from './context';
import { isBlockingQuestion } from './questions';
import type { ChatReply, ChatTurn } from './types';

/**
 * The questions an assistant turn asks, drawn under its prose. Live only
 * while the turn is the newest and nothing is streaming: once the
 * conversation moves on without an answer the card stays as it was offered,
 * inert, so the transcript still shows what was asked.
 */
export function TurnQuestion({
  turn,
  labels,
}: {
  turn: ChatTurn;
  /** The card's words, merged over QuestionCard's English defaults. */
  labels?: Partial<QuestionCardLabels>;
}) {
  const { turns, live, answerQuestion, skipQuestion } = useChatWidget();
  const set = turn.question;
  const newest = turns[turns.length - 1]?.id === turn.id;
  const blocking = newest && isBlockingQuestion(turn, live !== null);
  const ref = useRef<HTMLDivElement>(null);

  /* A set holds the composer, so focus goes where the input now is: the
     first option. Only on arrival, never on a later render. */
  useEffect(() => {
    if (!blocking) return;
    ref.current?.querySelector<HTMLElement>('button:not(:disabled)')?.focus({ preventScroll: true });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  if (!set) return null;
  return (
    <QuestionCard
      ref={ref}
      className="ds-chat-widget__question"
      labels={labels}
      questions={set.questions}
      values={turn.answers}
      disabled={turn.answers === undefined && (!newest || live !== null)}
      onValuesChange={(answers) => answerQuestion(turn.id, answers)}
      onSkip={blocking ? () => skipQuestion(turn.id) : undefined}
    />
  );
}

/**
 * A user turn that answered a set of questions: each question over its
 * answers. One question, with one pick or several, stays the ordinary
 * bubble, its picks joined with commas.
 */
export function ReplyBody({
  reply,
  text,
  missingLabel,
}: {
  reply?: ChatReply;
  text: string;
  /** What stands in for a question left without an answer. Defaults to QuestionSummary's "No answer". */
  missingLabel?: string;
}) {
  /* One question, however many picks, reads as its answers in a line: the
     plain text the model receives, commas and all. */
  if (!reply || reply.items.length === 1) return <>{text}</>;
  /* The same summary QuestionCard folds a set to, frameless inside the
     bubble: the question and the reply read as one pattern. */
  return <QuestionSummary variant="plain" items={reply.items} missingLabel={missingLabel} />;
}

import { ARTIFACT_CARD_KIND, type ChatArtifact, type ChatCard } from './types';

/* A card's data crossed a network, so it is checked before it is trusted
   with the panel: an artifact needs an id, a name and a kind to be one. */
const isArtifact = (data: unknown): data is ChatArtifact => {
  const candidate = data as Partial<ChatArtifact> | null;
  return (
    typeof candidate === 'object' &&
    candidate !== null &&
    typeof candidate.id === 'string' &&
    typeof candidate.title === 'string' &&
    typeof candidate.kind === 'string'
  );
};

/** The artifact a card carries, or null when it is some other kind of card. */
export const cardArtifact = (card: ChatCard | undefined): ChatArtifact | null =>
  card?.kind === ARTIFACT_CARD_KIND && isArtifact(card.data) ? card.data : null;

/** Wraps an artifact as the card a transport sends. */
export const artifactCard = (artifact: ChatArtifact): ChatCard => ({
  kind: ARTIFACT_CARD_KIND,
  data: artifact,
});

'use client';

import { createContext, useContext, type ReactNode } from 'react';
import type { ChatPlacement, ChatSide } from './placement';
import type { ThreadsState } from './threads';
import type { ChatArtifact, ChatFeedbackVerdict } from './types';
import type { ChatState } from './useChat';

/** Panel is the docked rail; full is the viewport takeover. */
export type ChatView = 'panel' | 'full';

/**
 * Draws a `card` event's data as a React node. Keyed by the card's `kind`;
 * a kind with no renderer draws nothing.
 */
export type ChatCardRenderers = Record<string, (data: unknown) => ReactNode>;

/**
 * Draws an artifact's preview as a React node, keyed by the artifact's
 * `kind`. A kind with no renderer falls back to the built-in frames.
 */
export type ChatArtifactRenderers = Record<string, (artifact: ChatArtifact) => ReactNode>;

/**
 * Whether the widget rendering this subtree seats the artifact panel (its
 * `artifacts` prop). With no seat an artifact has nowhere to open, so the
 * thread draws no tile for it: the feature is whole or it is absent.
 */
export const ArtifactSeatContext = createContext(false);

/** How the widget renders a link the model wrote. */
export type ChatLinkRenderer = (props: {
  href: string;
  children: ReactNode;
  /** Call on navigation: closes the panel when it covers the page. */
  onNavigate: () => void;
}) => ReactNode;

/** Sends a thumbs verdict somewhere. */
export type FeedbackSink = (exchangeId: string, verdict: ChatFeedbackVerdict) => Promise<void>;

export interface ChatWidgetContextValue extends ChatState {
  /** The visitor's explicit model pick (a wire value), null while following the server's default. */
  chosenModel: string | null;
  /** Records an explicit pick; it rides on every send until changed or cleared by a lock. */
  setChosenModel: (value: string | null) => void;
  open: boolean;
  setOpen: (open: boolean) => void;
  toggleOpen: () => void;
  /** Where the panel is in its lifecycle: `closing` is the exit beat after a close, during which the launcher keeps the panel rendered so its exit animation is seen. Everything behavioural keys on `open`; only presence reads this. */
  panelPhase: 'open' | 'closing' | 'closed';
  /** Which starters key has played its staged reveal, so a reopen shows the set standing rather than generating again. */
  starterRevealKey: string | null;
  setStarterRevealKey: (key: string | null) => void;
  /** The draw for the starter pools: rolled once per load and again by reset(). */
  starterSeed: number;
  /** The turn whose follow-ups landed most recently in this open session, or null. Its row plays the entrance. */
  freshFollowupsId: string | null;
  view: ChatView;
  setView: (view: ChatView) => void;
  /** The panel's seat: a dock edge or floating. Provider-lifetime, so a reload returns to the host's default. */
  placement: ChatPlacement;
  setPlacement: (placement: ChatPlacement) => void;
  /** The dock edge, remembered while floating, so the card has an edge to return to and to overlay from. */
  side: ChatSide;
  /** Popped out of the dock: a non-modal card the visitor moves and sizes. */
  floating: boolean;
  draft: string;
  setDraft: (draft: string) => void;
  /** The element to restore focus to when the panel closes. */
  returnFocusRef: React.MutableRefObject<HTMLElement | null>;
  /** The thread lifecycle behind the built-in threads and tabs. */
  threads: ThreadsState;
  renderers: ChatCardRenderers;
  /** The artifact on stage in the artifact panel, or null while it is closed. */
  artifact: ChatArtifact | null;
  /** Puts an artifact on stage. The widget seats the panel; this only says which. */
  openArtifact: (artifact: ChatArtifact) => void;
  closeArtifact: () => void;
  artifactRenderers: ChatArtifactRenderers;
  renderLink: ChatLinkRenderer;
  isInternalHref: (href: string) => boolean;
  /** Record and send a thumbs verdict; null when feedback is off. */
  submitFeedback: ((turnId: string, exchangeId: string, verdict: ChatFeedbackVerdict) => void) | null;
}

export const ChatWidgetContext = createContext<ChatWidgetContextValue | null>(null);

/** The chat's state and actions, for anything rendered inside `ChatProvider`. */
export function useChatWidget(): ChatWidgetContextValue {
  const context = useContext(ChatWidgetContext);
  if (!context) {
    throw new Error('useChatWidget must be used inside a ChatProvider');
  }
  return context;
}

/* Model output is untrusted, so an href becomes a link only when it is a
   same-site path: lowercase slug segments, optionally rooted at "/".
   Anything else (external hosts, protocols, fragments) renders as plain
   text. A hallucinated-but-clean path is inert: it lands on the host's 404. */
const INTERNAL_PATH = /^\/(?:[a-z0-9-]+(?:\/[a-z0-9-]+){0,3})?$/;
export const isInternalPath = (href: string) => INTERNAL_PATH.test(href);

/** A sink that posts a verdict to an endpoint speaking the feedback protocol (`createFeedbackHandler`). */
export function createFeedbackPoster(endpoint = '/api/chat/feedback'): FeedbackSink {
  return async (id, verdict) => {
    await fetch(endpoint, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ id, verdict }),
    });
  };
}

