/* The demo's card furniture: a drawn stand-in for product imagery, a row of
   source chips, a stack of two cards landing as one turn, and the lettered
   disc a source chip wears for a logo. Chart-series tokens keep it on-theme
   in both modes and re-theme with the rest of a theme like every chart. */

.ds-chat-demo__card-media {
  height: 120px;
  background: linear-gradient(135deg, var(--color-chart-series-1), var(--color-chart-series-2));
}

.ds-chat-demo__source-row {
  display: flex;
  flex-wrap: wrap;
  gap: var(--gap-200);
}

.ds-chat-demo__stack {
  display: flex;
  flex-direction: column;
  gap: var(--gap-300);
}

.ds-chat-demo__logo {
  display: inline-grid;
  place-items: center;
  width: 100%;
  height: 100%;
  border-radius: var(--radius-pill);
  font-family: var(--font-caption-family);
  font-size: var(--font-caption-size);
  font-weight: var(--font-title-body-weight);
  line-height: 1;
  color: var(--color-text-inverse);
}

.ds-chat-demo__logo--one {
  background-color: var(--color-chart-series-1);
}

.ds-chat-demo__logo--two {
  background-color: var(--color-chart-series-2);
}

.ds-chat-demo__logo--three {
  background-color: var(--color-chart-series-3);
}

/* The dashboard artifact: the welcome board, given the inset a panel's
   live content brings for itself. */
.ds-chat-demo__artifact-board {
  padding: var(--padding-400);
}

/**
 * rift-ds/chat/demo: a scripted conversation for a fictional workspace
 * product, with the rich cards, mock data and welcome fillings that show
 * every feature of the widget before a consumer has a model, a route or a
 * key. `createDemoTransport()` plays it; `DEMO_RENDERERS` draws its cards;
 * the fixtures seat the threads rail, the tabs, the agent pane, the
 * mentions and the model picker.
 *
 * Imports recharts for the chart cards, which is why this is its own
 * subpath with its own optional peer rather than part of rift-ds/chat.
 * Everything here is invented: the product, the people, the numbers.
 */
