 * rift-ds/chat/server: the widget's backend, as web-standard request
 * handlers. Mount `createChatHandler` on a POST route (Next's app router,
 * Remix, Hono, a plain Node server over the fetch API) and the fetch
 * transport in the widget speaks to it unchanged. Its two siblings serve
 * the follow-up questions and the thumbs verdicts the widget sends.
 *
 * The protocol is fixed here; the configuration is the host's. Fixed: the
 * NDJSON framing, the event order (`status`, `model`, `models`, then status
 * and delta events, a `question` when the model asked one through the
 * opt-in `ask_user` tool, an optional `notice`, `exchange`, and always
 * `done` last), the body caps, the rule that guardrail outcomes are 200 plus a
 * `notice` (a rate limit reads as a reply, not a broken widget; non-2xx is
 * reserved for malformed requests), and the rule that `error` is only ever
 * emitted before the first delta (an error event replaces streamed text, so
 * once text is flowing a failure ends the turn with `done` and the partial
 * stands). The host supplies the system prompt, the model list, the tools,
 * the guardrails and the copy.
 *
 * Needs the optional peer `@anthropic-ai/sdk`. No Next.js import anywhere:
 * the route file a host writes (or `npx rift-ds init chat` writes for it)
 * owns the segment config and the environment reads.
 */
import Anthropic from '@anthropic-ai/sdk';
import { ASK_USER_INPUT_SCHEMA, sanitizeQuestionSet } from './questions';
import { SUGGESTION_MAX_CHARS, fitsChip } from './suggestions';
import type { ChatCard, ChatEvent, ChatFeedbackVerdict, ChatModelOption, ChatTransportMessage } from './types';

/* ============================================
   Tools
   ============================================ */

/** What a tool hands back: text for the model, and optionally a card for the visitor. */
export interface ChatToolResult {
  /** The tool result the model reads. */
  text: string;
  /** Rich content streamed to the widget as a `card` event, drawn by the provider's renderers. */
  card?: ChatCard;
}

/** One deterministic tool the model may call. */
export interface ChatTool {
  /** The Anthropic tool definition: name, description, input schema. */
  definition: Anthropic.Messages.Tool;
  /** Runs the tool. Return a string for the model, or a result with a card for the visitor too. Never throw for bad input: return an error string the model can recover from. */
  execute: (input: Record<string, unknown>) => string | ChatToolResult | Promise<string | ChatToolResult>;
  /** The trace point shown while the round runs, e.g. "Checked the Button prop contract". */
  tracePoint?: (input: Record<string, unknown>) => string;
}

/** The name of the built-in tool the model asks the visitor questions through. */
export const ASK_USER_TOOL_NAME = 'ask_user';

/**
 * What the model is told about asking. Lives in the tool's description, not
 * the system prompt, so switching it on never disturbs a cached prefix.
 */
export const DEFAULT_ASK_USER_DESCRIPTION = [
  'Offer the person answers to pick for a question your reply has just asked in words.',
  'Use it only when the most useful next step depends on their answer and the likely answers can be listed: which framework, which of these options, which parts apply.',
  'Do not use it for open questions, for confirming something they already said, or when you can simply answer. Most replies should not ask.',
  'Write the question in your reply first, then call this once, as your last action. The conversation waits for their answer.',
  'Prefer one question. Use several (at most 4) only when you need all the answers before you can continue. mode is single when one answer fits and multi when several can be true together.',
  'Set other to true when the options may not cover every answer.',
].join(' ');

/* ============================================
   Guardrails
   ============================================ */

/**
 * How much of the day's budget remains, as a model policy: `open` means the
 * default model serves, `reduced` means the budget model is the default (the
 * better one stays selectable), `locked` means only the budget model serves.
 */
export type ModelTier = 'open' | 'reduced' | 'locked';

export type GuardrailVerdict =
  | { allowed: true; tier: ModelTier }
  | { allowed: false; notice: string };

/** Anthropic's usage block, narrowed to the fields a spend estimate needs. */
export interface TokenUsage {
  input_tokens?: number | null;
  output_tokens?: number | null;
  cache_creation_input_tokens?: number | null;
  cache_read_input_tokens?: number | null;
}

/** One logged exchange: what was asked, what came back, and the numbers. */
export interface ExchangeLog {
  /** Minted per request and streamed to the widget, so a feedback verdict can be joined back to this line. */
  id: string;
  question: string;
  answer: string;
  /** The sanitised context the request carried, or null. */
  path: string | null;
  /** The model id that served, absent on guardrail notices. */
  model?: string;
  usage?: TokenUsage;
  /** Milliseconds from request to the stream closing. */
  latencyMs: number;
  /** Milliseconds to the first response text, what the visitor feels. */
  firstTextMs: number | null;
  /** True when the answer is a guardrail notice, not a model response. */
  notice: boolean;
  /** The opaque per-visitor key. */
  visitor: string;
}

/**
 * The hooks the handlers call around a request. Every member is optional
 * and every one fails open: a missing hook means no limit, no log, no
 * tiering. `rift-ds/chat/upstash` implements the set over Redis.
 */
export interface ChatGuardrails {
  /** Rate limits and the daily breaker. Return a notice to answer with instead of calling the model. */
  check?: (request: Request) => Promise<GuardrailVerdict>;
  /** A stable, opaque key for the visitor (a salted hash, never an address). */
  visitorKey?: (request: Request) => Promise<string> | string;
  /** Called with the real token counts after every model call. */
  onUsage?: (usage: TokenUsage, modelId: string) => Promise<void>;
  /** Called once per exchange. Its presence is what makes the handler stream an `exchange` id, and so what shows the thumbs. */
  onExchange?: (entry: ExchangeLog) => Promise<void>;
  /** Per-visitor limit for the follow-ups handler. */
  checkFollowups?: (request: Request) => Promise<boolean>;
  /** Per-visitor limit for the feedback handler. */
  checkFeedback?: (request: Request) => Promise<boolean>;
  /** Stores one verdict per exchange id. */
  onFeedback?: (exchangeId: string, verdict: ChatFeedbackVerdict, visitor: string) => Promise<void>;
}

/* ============================================
   The chat handler
   ============================================ */

export interface ChatLimits {
  /** Turns kept from the client's history. Older context is dropped. */
  maxTurns: number;
  /** Longest single message accepted, in characters. */
  maxMessageChars: number;
  /** Longest whole conversation accepted, summed across every kept turn. */
  maxTotalChars: number;
  /** Hard ceiling on the raw request body, rejected before it is parsed. */
  maxBodyChars: number;
  /** Trace points shown under the status label before the rest is dropped. */
  maxTracePoints: number;
}

export const DEFAULT_CHAT_LIMITS: ChatLimits = {
  maxTurns: 10,
  maxMessageChars: 4000,
  maxTotalChars: 40000,
  maxBodyChars: 64 * 1024,
  maxTracePoints: 8,
};

export interface ChatHandlerCopy {
  /** The reply when the chat is switched off or unconfigured. */
  disabled: string;
  /** The reply to a message over `maxMessageChars`. */
  tooLong: string;
  /** The reply when the model refuses and nothing was streamed. */
  refusal: string;
  /** Appended when the answer hit the token cap. */
  cutOff: string;
  /** The first status label, proving the stream opened. */
  reading: string;
  /** The status label while thinking. */
  thinking: string;
  /** The status label while a tool round runs. */
  lookingUp: string;
  /** The reply text when the model asks several questions without writing any. One question stands in for itself. */
  questionsIntro: string;
  /** The error for a busy or overloaded model. */
  busy: string;
  /** The error for a rejected key. */
  unauthorised: string;
  /** The error for anything else before the first text. */
  failed: string;
}

export const DEFAULT_CHAT_COPY: ChatHandlerCopy = {
  disabled: 'This chat is switched off at the moment.',
  tooLong: 'That message is longer than this chat can take. Trim it to the essentials and send it again.',
  refusal: 'That one is outside what this chat covers.',
  cutOff: '\n\n(Cut off at the length limit.)',
  reading: 'Reading',
  thinking: 'Thinking',
  lookingUp: 'Looking it up',
  questionsIntro: 'A few questions before I go on.',
  busy: 'The model is busy right now. Give it a moment and ask again.',
  unauthorised: 'This chat is not configured correctly at the moment.',
  failed: 'Something went wrong reaching the model. Try that again in a moment.',
};

export type SystemBlocks = Anthropic.Messages.TextBlockParam[];

export interface ChatHandlerOptions {
  /** An Anthropic client to reuse, or `apiKey` to build one from. */
  client?: Anthropic;
  apiKey?: string;
  /** The off switch. Defaults to whether a client or key is present. */
  enabled?: boolean;
  /**
   * The system prompt, as blocks. A string is one block; a function builds
   * them per request from the sanitised context. Put `cache_control` on the
   * block that holds your corpus, and nothing volatile before it.
   */
  system: string | SystemBlocks | ((context: { path: string | null }) => string | SystemBlocks);
  /**
   * An uncached trailing block built from the request's context, after the
   * cache breakpoint. Defaults to naming the page; return null for none.
   */
  contextBlock?: (path: string) => string | null;
  /** The models on offer. The client sends a `value`; the handler calls the matching `id`. */
  models: ChatModelOption[];
  /** The wire value that serves when the budget has headroom and the visitor has not chosen. Defaults to the first model. */
  defaultModel?: string;
  /** The wire value that serves once the budget steps down, and the only one past the lock. Defaults to `defaultModel`. */
  budgetModel?: string;
  tools?: ChatTool[];
  /**
   * Give the model the built-in `ask_user` tool, through which a reply can
   * end in questions the widget draws as answers to pick. Pass an object to
   * replace the guidance the model reads. Off by default. Calling it ends
   * the exchange: no further model call is made, so it never counts against
   * `maxModelCalls` beyond the pass that asked.
   */
  askUser?: boolean | { description?: string };
  /** Model calls per exchange: the first pass plus tool rounds. The last allowed pass withholds the tools. */
  maxModelCalls?: number;
  /** Caps thinking and response text together. */
  maxTokens?: number;
  /** Adaptive thinking's effort dial, for models that take it. */
  effort?: 'low' | 'medium' | 'high';
  guardrails?: ChatGuardrails;
  limits?: Partial<ChatLimits>;
  copy?: Partial<ChatHandlerCopy>;
  /** Turns the request's raw `path` into context, or null to drop it. The default accepts lowercase slug paths only. */
  sanitiseContext?: (value: unknown) => string | null;
  /** Keeps a fire-and-forget promise alive on platforms that end work with the response. */
  waitUntil?: (promise: Promise<unknown>) => void;
}

const NDJSON_HEADERS = {
  'Content-Type': 'application/x-ndjson; charset=utf-8',
  'Cache-Control': 'no-store',
  // Proxies that buffer by default would hold the whole reply and destroy the
  // streaming choreography the widget exists to show.
  'X-Accel-Buffering': 'no',
} as const;

const encoder = new TextEncoder();
const serialise = (event: ChatEvent) => encoder.encode(`${JSON.stringify(event)}\n`);

/** A complete response made of known events, for the paths that never call the model. */
function ndjson(...events: ChatEvent[]): Response {
  return new Response(events.map((event) => `${JSON.stringify(event)}\n`).join(''), {
    headers: NDJSON_HEADERS,
  });
}

/**
 * The request's context, sanitised as untrusted input: it lands in a system
 * block, a stronger position than the user turn. Lowercase slug segments
 * only, capped short; nothing expressible in that alphabet can carry an
 * instruction. Anything else is dropped, never rejected.
 */
export function sanitisePath(value: unknown): string | null {
  if (typeof value !== 'string') return null;
  if (value === '/') return '/';
  return /^\/[a-z0-9-]+(?:\/[a-z0-9-]+){0,3}$/.test(value) && value.length <= 64 ? value : null;
}

type ParsedBody =
  | { ok: true; messages: ChatTransportMessage[]; path: string | null; model: ChatModelOption | null }
  | { ok: false; status: number; reason: string };

function parseBody(
  payload: unknown,
  limits: ChatLimits,
  models: ChatModelOption[],
  sanitise: (value: unknown) => string | null
): ParsedBody {
  if (typeof payload !== 'object' || payload === null) {
    return { ok: false, status: 400, reason: 'body must be an object' };
  }
  const { messages, path, model } = payload as { messages?: unknown; path?: unknown; model?: unknown };
  if (!Array.isArray(messages) || messages.length === 0) {
    return { ok: false, status: 400, reason: 'messages must be a non-empty array' };
  }

  const parsed: ChatTransportMessage[] = [];
  for (const entry of messages) {
    if (typeof entry !== 'object' || entry === null) {
      return { ok: false, status: 400, reason: 'each message must be an object' };
    }
    const { role, content } = entry as { role?: unknown; content?: unknown };
    if (role !== 'user' && role !== 'assistant') {
      return { ok: false, status: 400, reason: "role must be 'user' or 'assistant'" };
    }
    if (typeof content !== 'string') {
      return { ok: false, status: 400, reason: 'content must be a string' };
    }
    if (content.trim()) parsed.push({ role, content });
  }
  if (parsed.length === 0) return { ok: false, status: 400, reason: 'no messages with content' };

  // The conversation must start with a user turn; dropping old turns can
  // leave an assistant one first.
  const trimmed = parsed.slice(-limits.maxTurns);
  while (trimmed.length > 0 && trimmed[0].role === 'assistant') trimmed.shift();
  if (trimmed.length === 0) {
    return { ok: false, status: 400, reason: 'no user message in the recent turns' };
  }

  const totalChars = trimmed.reduce((sum, message) => sum + message.content.length, 0);
  if (totalChars > limits.maxTotalChars) {
    return { ok: false, status: 413, reason: 'conversation is too large' };
  }

  // The model field is a request, resolved like the path: an allowlisted
  // value or nothing. An unrecognised one falls back to the tier default.
  const requested =
    typeof model === 'string' ? (models.find((option) => option.value === model) ?? null) : null;
  return { ok: true, messages: trimmed, path: sanitise(path), model: requested };
}

/* Summarised thinking arrives as prose. Each finished sentence becomes one
   trace point under the status label, which is what the Reasoning component
   renders while the response is still being composed. */
function cleanPoint(text: string): string {
  const flat = text.replace(/\*\*/g, '').replace(/\s+/g, ' ').trim();
  if (flat.length <= 200) return flat;
  const cut = flat.slice(0, 200);
  return `${cut.slice(0, cut.lastIndexOf(' ')) || cut}…`;
}

function createReasoningBuffer(limit: number, emit: (point: string) => void) {
  let buffer = '';
  let emitted = 0;
  const flush = (final: boolean) => {
    if (emitted >= limit) {
      buffer = '';
      return;
    }
    const sentences = buffer.split(/(?<=[.!?])\s+/);
    // The trailing fragment is usually mid-sentence, so hold it until either
    // more text arrives or the thinking block closes.
    buffer = final ? '' : (sentences.pop() ?? '');
    for (const sentence of sentences) {
      if (emitted >= limit) break;
      const point = cleanPoint(sentence);
      if (point.length < 12) continue;
      emit(point);
      emitted += 1;
    }
  };
  return {
    push(text: string) {
      buffer += text;
      flush(false);
    },
    close() {
      flush(true);
    },
  };
}

function friendlyError(error: unknown, copy: ChatHandlerCopy): string {
  const status = (error as { status?: number })?.status;
  if (status === 429 || status === 529) return copy.busy;
  if (status === 401 || status === 403) return copy.unauthorised;
  return copy.failed;
}

const toBlocks = (system: string | SystemBlocks): SystemBlocks =>
  typeof system === 'string' ? [{ type: 'text', text: system }] : system;

/**
 * The chat handler: `(request) => Response`, streaming NDJSON `ChatEvent`s.
 */
export function createChatHandler(options: ChatHandlerOptions): (request: Request) => Promise<Response> {
  const limits = { ...DEFAULT_CHAT_LIMITS, ...options.limits };
  const copy = { ...DEFAULT_CHAT_COPY, ...options.copy };
  const sanitise = options.sanitiseContext ?? sanitisePath;
  const tools = options.tools ?? [];
  const askUserDefinition: Anthropic.Messages.Tool | null = options.askUser
    ? {
        name: ASK_USER_TOOL_NAME,
        description:
          (typeof options.askUser === 'object' ? options.askUser.description : undefined) ??
          DEFAULT_ASK_USER_DESCRIPTION,
        input_schema: ASK_USER_INPUT_SCHEMA as unknown as Anthropic.Messages.Tool.InputSchema,
      }
    : null;
  const toolDefinitions = [
    ...tools.map((tool) => tool.definition),
    ...(askUserDefinition ? [askUserDefinition] : []),
  ];
  const toolByName = new Map(tools.map((tool) => [tool.definition.name, tool]));
  const maxModelCalls = options.maxModelCalls ?? 3;
  const maxTokens = options.maxTokens ?? 3000;
  const effort = options.effort ?? 'low';
  const guardrails = options.guardrails ?? {};
  const contextBlock =
    options.contextBlock ?? ((path: string) => `The visitor is currently on the page ${path}.`);
  const client =
    options.client ?? (options.apiKey ? new Anthropic({ apiKey: options.apiKey }) : null);
  const enabled = options.enabled ?? client !== null;

  const defaultModel =
    options.models.find((option) => option.value === options.defaultModel) ?? options.models[0];
  const budgetModel =
    options.models.find((option) => option.value === options.budgetModel) ?? defaultModel;
  if (!defaultModel) throw new Error('createChatHandler: `models` must name at least one model.');

  /* The one place client preference meets budget policy. The tier is the
     trump: past the lock only the budget model serves. Inside the lock, an
     explicit pick is honoured, and no pick follows the tier's default. */
  const resolveServingModel = (requested: ChatModelOption | null, tier: ModelTier) => {
    if (tier === 'locked') return budgetModel;
    if (requested) return requested;
    return tier === 'reduced' ? budgetModel : defaultModel;
  };

  const runTool = async (name: string, input: unknown): Promise<ChatToolResult> => {
    const args = (typeof input === 'object' && input !== null ? input : {}) as Record<string, unknown>;
    const tool = toolByName.get(name);
    if (!tool) return { text: JSON.stringify({ error: `Unknown tool ${JSON.stringify(name)}.` }) };
    try {
      const result = await tool.execute(args);
      return typeof result === 'string' ? { text: result } : result;
    } catch (error) {
      return { text: JSON.stringify({ error: String((error as Error)?.message ?? error) }) };
    }
  };

  return async function chatHandler(request: Request): Promise<Response> {
    // Off switch first, before any parsing or network. A route can deploy
    // ahead of its environment on purpose, so an unconfigured one has to
    // answer politely rather than throw.
    if (!enabled || !client) {
      return ndjson({ type: 'notice', text: copy.disabled }, { type: 'done' });
    }

    let payload: unknown;
    try {
      const raw = await request.text();
      if (raw.length > limits.maxBodyChars) {
        return Response.json({ error: 'request body too large' }, { status: 413 });
      }
      payload = JSON.parse(raw);
    } catch {
      return Response.json({ error: 'invalid JSON' }, { status: 400 });
    }

    const parsed = parseBody(payload, limits, options.models, sanitise);
    if (!parsed.ok) return Response.json({ error: parsed.reason }, { status: parsed.status });

    const latest = parsed.messages[parsed.messages.length - 1];
    if (latest.content.length > limits.maxMessageChars) {
      return ndjson({ type: 'notice', text: copy.tooLong }, { type: 'done' });
    }

    const startedAt = Date.now();
    const visitor = (await guardrails.visitorKey?.(request)) ?? 'anonymous';
    const question = latest.content;
    /* The exchange's log id. Minted before the guardrails so every logged
       line carries one, and streamed to the client only on the model path. */
    const exchangeId = crypto.randomUUID();
    const log = (entry: ExchangeLog) => {
      if (!guardrails.onExchange) return Promise.resolve();
      return guardrails.onExchange(entry).catch(() => {});
    };

    const verdict: GuardrailVerdict = (await guardrails.check?.(request)) ?? { allowed: true, tier: 'open' };
    if (!verdict.allowed) {
      // Guardrail notices are logged too: how often the limits fire, and what
      // people were asking when they did, is exactly what tunes the caps.
      const logged = log({
        id: exchangeId,
        question,
        answer: verdict.notice,
        path: parsed.path,
        latencyMs: Date.now() - startedAt,
        firstTextMs: null,
        notice: true,
        visitor,
      });
      options.waitUntil?.(logged);
      return ndjson({ type: 'notice', text: verdict.notice }, { type: 'done' });
    }

    const serving = resolveServingModel(parsed.model, verdict.tier);
    /* What the picker should offer right now: the tier's default, and which
       values are locked out. Everything but the budget model locks together. */
    const tierDefault = verdict.tier === 'open' ? defaultModel.value : budgetModel.value;
    const lockedValues =
      verdict.tier === 'locked'
        ? options.models.filter((option) => option !== budgetModel).map((option) => option.value)
        : [];

    // Client disconnect and stream cancellation both abort the upstream call,
    // so a visitor closing the tab stops the tokens being billed.
    const upstream = new AbortController();
    request.signal.addEventListener('abort', () => upstream.abort());

    const systemBase = toBlocks(
      typeof options.system === 'function' ? options.system({ path: parsed.path }) : options.system
    );
    const trailing = parsed.path ? contextBlock(parsed.path) : null;
    const system: SystemBlocks = trailing
      ? [...systemBase, { type: 'text', text: trailing }]
      : systemBase;

    const body = new ReadableStream<Uint8Array>({
      async start(controller) {
        let closed = false;
        const send = (event: ChatEvent) => {
          if (closed) return;
          try {
            controller.enqueue(serialise(event));
          } catch {
            closed = true;
          }
        };

        let streamedText = false;
        let answerText = '';
        let noticeText: string | null = null;
        let firstTextMs: number | null = null;

        try {
          // First line out. It proves the stream opened, which clears the
          // transport's first-byte watchdog.
          send({ type: 'status', label: copy.reading });
          send({ type: 'model', label: serving.label });
          send({ type: 'models', default: tierDefault, locked: lockedValues });

          const reasoning = createReasoningBuffer(limits.maxTracePoints, (point) =>
            send({ type: 'status', label: copy.thinking, point })
          );

          // The tool loop: stream a pass, and when it ends in tool_use, run
          // the requested tools and stream again with the results appended.
          // Bounded, and the last allowed pass has the tools withheld, so it
          // must answer in text.
          const working: Anthropic.Messages.MessageParam[] = parsed.messages.map(({ role, content }) => ({
            role,
            content,
          }));
          let final: Anthropic.Messages.Message;

          for (let call = 0; ; call += 1) {
            const lastCall = call === maxModelCalls - 1;
            const stream = client.messages.stream(
              {
                model: serving.id,
                max_tokens: maxTokens,
                // A model that predates adaptive thinking and the effort dial
                // rejects both, so it gets a plain request.
                ...(serving.adaptiveThinking
                  ? {
                      thinking: { type: 'adaptive' as const, display: 'summarized' as const },
                      output_config: { effort },
                    }
                  : {}),
                ...(toolDefinitions.length > 0 ? { tools: toolDefinitions } : {}),
                ...(lastCall && toolDefinitions.length > 0 ? { tool_choice: { type: 'none' as const } } : {}),
                system,
                messages: working,
              },
              { signal: upstream.signal }
            );

            for await (const event of stream) {
              if (upstream.signal.aborted) break;
              if (event.type !== 'content_block_delta') continue;
              if (event.delta.type === 'text_delta') {
                if (!streamedText) {
                  reasoning.close();
                  streamedText = true;
                  firstTextMs = Date.now() - startedAt;
                }
                answerText += event.delta.text;
                send({ type: 'delta', text: event.delta.text });
              } else if (event.delta.type === 'thinking_delta') {
                reasoning.push(event.delta.thinking);
              }
            }

            final = await stream.finalMessage();
            // Real token counts per call, so a daily breaker tracks the whole
            // exchange, tool rounds included.
            await guardrails.onUsage?.(final.usage, serving.id).catch(() => {});

            if (final.stop_reason !== 'tool_use' || lastCall || upstream.signal.aborted) break;

            const toolUses = final.content.filter(
              (block): block is Anthropic.Messages.ToolUseBlock => block.type === 'tool_use'
            );
            const results: Anthropic.Messages.ToolResultBlockParam[] = [];

            /* A well-formed question ends the exchange: the next move is the
               visitor's. Checked before any other tool runs, so nothing is
               looked up for a pass that will never be read. A malformed one
               goes back to the model as an error it can correct or answer
               around in text. */
            const ask = askUserDefinition
              ? toolUses.find((block) => block.name === ASK_USER_TOOL_NAME)
              : undefined;
            const set = ask ? sanitizeQuestionSet(ask.input, `${exchangeId}-questions`) : null;
            if (set) {
              if (!streamedText) {
                // The reply must ask in words too; a model that skipped them
                // gets the question itself as its text.
                const lead = set.questions.length === 1 ? set.questions[0].prompt : copy.questionsIntro;
                reasoning.close();
                streamedText = true;
                firstTextMs = Date.now() - startedAt;
                answerText += lead;
                send({ type: 'delta', text: lead });
              }
              send({ type: 'question', set });
              break;
            }

            for (const block of toolUses) {
              if (block.name === ASK_USER_TOOL_NAME) {
                results.push({
                  type: 'tool_result',
                  tool_use_id: block.id,
                  is_error: true,
                  content:
                    'Those questions could not be shown. Each needs a short prompt and 2 to 5 distinct options of at most ' +
                    `${SUGGESTION_MAX_CHARS} characters, and a set holds at most 4. Fix them, or ask in plain text.`,
                });
                continue;
              }
              const args = (typeof block.input === 'object' && block.input !== null
                ? block.input
                : {}) as Record<string, unknown>;
              send({
                type: 'status',
                label: copy.lookingUp,
                point: toolByName.get(block.name)?.tracePoint?.(args) ?? `Used ${block.name}`,
              });
              const result = await runTool(block.name, block.input);
              if (result.card) send({ type: 'card', card: result.card });
              results.push({ type: 'tool_result', tool_use_id: block.id, content: result.text });
            }
            working.push(
              // The full content blocks go back, thinking included: the API
              // requires the thinking blocks intact on a tool-using turn.
              { role: 'assistant', content: final.content as Anthropic.Messages.ContentBlockParam[] },
              { role: 'user', content: results }
            );
          }

          if (final.stop_reason === 'refusal' && !streamedText) {
            noticeText = copy.refusal;
            send({ type: 'notice', text: noticeText });
          } else if (final.stop_reason === 'max_tokens') {
            send({ type: 'delta', text: copy.cutOff });
          }

          // The exchange log, written before the id goes out so a verdict
          // can never dangle. The id is only streamed when something logs:
          // thumbs on an exchange nobody recorded would rate nothing.
          if (guardrails.onExchange) {
            await log({
              id: exchangeId,
              question,
              answer: noticeText ?? answerText,
              path: parsed.path,
              model: serving.id,
              usage: final.usage,
              latencyMs: Date.now() - startedAt,
              firstTextMs,
              notice: noticeText !== null,
              visitor,
            });
            send({ type: 'exchange', id: exchangeId });
          }
        } catch (error) {
          const aborted =
            upstream.signal.aborted || (error instanceof Error && error.name === 'AbortError');
          if (!aborted && !streamedText) {
            console.error('[chat] upstream failed before any text:', error);
            send({ type: 'error', message: friendlyError(error, copy) });
          } else if (!aborted) {
            // Text is already on screen; an error event would erase it.
            console.error('[chat] upstream failed mid-stream, keeping the partial:', error);
          }
        } finally {
          send({ type: 'done' });
          if (!closed) {
            try {
              controller.close();
            } catch {
              /* already closed by a client disconnect */
            }
          }
        }
      },
      cancel() {
        upstream.abort();
      },
    });

    return new Response(body, { headers: NDJSON_HEADERS });
  };
}

/* ============================================
   The follow-ups handler
   ============================================ */

export interface FollowupsHandlerOptions {
  client?: Anthropic;
  apiKey?: string;
  enabled?: boolean;
  /** The model id that writes the questions. A small one: the job is three short lines. */
  model: string;
  /**
   * What the chat is about, in a phrase the prompt can use: "the Acme
   * workspace app and its documentation". Ignored when `system` is given.
   */
  about?: string;
  /** A complete system prompt, replacing the built-in one. */
  system?: string;
  /** Example questions in the voice wanted, shown to the model. */
  examples?: string[];
  guardrails?: Pick<ChatGuardrails, 'checkFollowups' | 'onUsage'>;
  /** Chips shown. */
  wanted?: number;
  /** Candidates asked for, so a few long ones still leave a full row. */
  candidates?: number;
  /** Cap on the upstream call, inside the widget's own wait. */
  timeoutMs?: number;
}

const DEFAULT_FOLLOWUP_EXAMPLES = [
  'How do I get started?',
  'What does the Team plan include?',
  'Can you show me an example?',
];

/** The built-in follow-ups prompt. */
export function followupsSystemPrompt({
  about,
  candidates,
  examples,
}: {
  about: string;
  candidates: number;
  examples: string[];
}): string {
  return `You write the follow-up questions offered under an answer from a chat assistant about ${about}.

You are given the visitor's last question and the answer they just read. Write the ${candidates} questions that visitor is most likely to want to ask next, best first.

Length matters more than anything else here. Each question is shown on a chip, on one line, in a narrow panel. It must be at most ${SUGGESTION_MAX_CHARS} characters including spaces, which is about six words. A question over that length is thrown away and never shown, so write the short version of the question rather than the complete one. Count the characters before you write each line.

Ask the plain question. Cut any phrase that does not change what is being asked: how long the answer should take, how many points it should have, how simple it should be, and the polite run-up to the question itself. A chip is a question, not a request.

Questions in the length and plainness wanted:
${examples.join('\n')}

The rest of the rules:
- Each question must be answerable by the assistant, about ${about}.
- Move the conversation forward. Never re-ask the question just asked, and never ask something the answer already covered.
- The visitor is asking the assistant: "What does the plan include?", never "What did you build?".
- Plain words, sentence case. No em dashes, no emoji, no quotation marks, no numbering, no markdown.
- Different angles on what was just said, not one question phrased several ways.

Output exactly ${candidates} lines, one question per line, and nothing else.`;
}

/**
 * The model's lines to the chips that are safe to show: plain text, one
 * short question each, no duplicates, at most `wanted`. Anything that does
 * not fit the shape is dropped rather than repaired.
 */
export function parseFollowups(text: string, wanted = 3): string[] {
  const seen = new Set<string>();
  const suggestions: string[] = [];
  for (const line of text.split('\n')) {
    const cleaned = line
      .replace(/^\s*(?:[-*•]|\d+[.)])\s*/, '')
      .replace(/[*_`#]/g, '')
      .replace(/^["'“”‘’]+|["'“”‘’]+$/g, '')
      .replace(/\s+/g, ' ')
      .trim();
    if (cleaned.length < 12 || !fitsChip(cleaned)) continue;
    if (!cleaned.endsWith('?')) continue;
    const key = cleaned.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    suggestions.push(cleaned);
    if (suggestions.length === wanted) break;
  }
  return suggestions;
}

/**
 * The follow-ups handler: POST `{ question, answer }`, respond
 * `{ suggestions: string[] }`, empty on every failure. A second call rather
 * than part of the answer's stream, because the questions are written from
 * the completed answer.
 */
export function createFollowupsHandler(
  options: FollowupsHandlerOptions
): (request: Request) => Promise<Response> {
  const wanted = options.wanted ?? 3;
  const candidates = options.candidates ?? 5;
  const timeoutMs = options.timeoutMs ?? 8_000;
  const client =
    options.client ??
    (options.apiKey ? new Anthropic({ apiKey: options.apiKey, timeout: timeoutMs, maxRetries: 0 }) : null);
  const enabled = options.enabled ?? client !== null;
  const system =
    options.system ??
    followupsSystemPrompt({
      about: options.about ?? 'this product',
      candidates,
      examples: options.examples ?? DEFAULT_FOLLOWUP_EXAMPLES,
    });
  const empty = () => Response.json({ suggestions: [] });

  return async function followupsHandler(request: Request): Promise<Response> {
    if (!enabled || !client) return empty();

    let payload: unknown;
    try {
      payload = await request.json();
    } catch {
      return Response.json({ error: 'invalid JSON' }, { status: 400 });
    }
    if (typeof payload !== 'object' || payload === null) {
      return Response.json({ error: 'body must be an object' }, { status: 400 });
    }
    const { question, answer } = payload as { question?: unknown; answer?: unknown };
    if (typeof question !== 'string' || question.trim() === '') {
      return Response.json({ error: 'question must be a non-empty string' }, { status: 400 });
    }
    if (typeof answer !== 'string' || answer.trim() === '') {
      return Response.json({ error: 'answer must be a non-empty string' }, { status: 400 });
    }

    if (options.guardrails?.checkFollowups && !(await options.guardrails.checkFollowups(request))) {
      return empty();
    }

    try {
      const message = await client.messages.create(
        {
          model: options.model,
          max_tokens: 200,
          // Thinking would spend the small token cap before the questions are written.
          thinking: { type: 'disabled' },
          system,
          messages: [
            {
              role: 'user',
              content: `The visitor asked:\n${question.slice(0, 4000)}\n\nThe assistant answered:\n${answer.slice(0, 4000)}`,
            },
          ],
        },
        // The visitor moving on stops this being billed; nothing waits on it.
        { signal: request.signal }
      );
      await options.guardrails?.onUsage?.(message.usage, options.model).catch(() => {});
      const text = message.content.map((block) => (block.type === 'text' ? block.text : '')).join('');
      return Response.json({ suggestions: parseFollowups(text, wanted) });
    } catch (error) {
      if (!request.signal.aborted) console.error('[chat] follow-up suggestions failed:', error);
      return empty();
    }
  };
}

/* ============================================
   The feedback handler
   ============================================ */

const EXCHANGE_ID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;

/**
 * The feedback handler: POST `{ id, verdict }`, respond 204. The id is never
 * trusted to exist; a verdict for an id no exchange used is a write nothing
 * will join against, so validation is a shape check, not a lookup.
 */
export function createFeedbackHandler(options: {
  guardrails?: Pick<ChatGuardrails, 'checkFeedback' | 'onFeedback' | 'visitorKey'>;
} = {}): (request: Request) => Promise<Response> {
  const guardrails = options.guardrails ?? {};
  return async function feedbackHandler(request: Request): Promise<Response> {
    let payload: unknown;
    try {
      payload = await request.json();
    } catch {
      return Response.json({ error: 'invalid JSON' }, { status: 400 });
    }
    if (typeof payload !== 'object' || payload === null) {
      return Response.json({ error: 'body must be an object' }, { status: 400 });
    }
    const { id, verdict } = payload as { id?: unknown; verdict?: unknown };
    if (typeof id !== 'string' || !EXCHANGE_ID.test(id)) {
      return Response.json({ error: 'id must be an exchange id' }, { status: 400 });
    }
    if (verdict !== 'up' && verdict !== 'down') {
      return Response.json({ error: "verdict must be 'up' or 'down'" }, { status: 400 });
    }
    if (guardrails.checkFeedback && !(await guardrails.checkFeedback(request))) {
      return new Response(null, { status: 429 });
    }
    const visitor = (await guardrails.visitorKey?.(request)) ?? 'anonymous';
    await guardrails.onFeedback?.(id, verdict, visitor).catch(() => {});
    return new Response(null, { status: 204 });
  };
}

import type { ReactNode } from 'react';
import { STARTER_COUNT } from './starters';
import { fitsChip } from './suggestions';
import type { ChatCard, ChatEvent, ChatQuestionSet, ChatTransport, ChatTransportMessage } from './types';

/* ============================================
   The scripted transport.

   A conversation written in advance and played back through the same event
   stream a real backend produces: scripted status steps at a steady beat, a
   handoff pause, then the reply revealed word by word, then any rich
   content and the follow-up chips. The widget cannot tell the difference,
   which is the point: a consumer mounts the widget, sees it working, and
   shows it round before there is a model, a route or a key anywhere.

   Routing is by the visitor's words. A chip sends its label as the message,
   so a scripted prompt matches exactly (normalised); typed free text falls
   back to a rotation of fallback replies; a turn with files and no matching
   prompt gets a reply about the files. Every path ends in `done`.

   `scriptChat()` below is the authoring API; `createSimTransport` is the
   player underneath it.
   ============================================ */

/** One status beat shown while the scripted reply "thinks". */
export interface ScriptStep {
  /** The AgentStatus label. */
  status: string;
  /** The reasoning trace point that collects under it. */
  point?: string;
}

/** What a scripted assistant says back, and what rides with it. */
export interface ScriptedReply {
  /** The status beats before the text, one per `statusMs`. */
  steps?: ScriptStep[];
  /** The reply, as markdown. */
  text: string;
  /** Rich content the provider's renderers draw with the turn. */
  card?: ChatCard;
  /** Rich content as a React node, for a script that lives beside its components. */
  content?: ReactNode;
  /** The chips offered under the reply. Each should be a scripted prompt so no path dead-ends. */
  followups?: string[];
  /**
   * Questions the reply asks, drawn as a QuestionCard in place of the chips.
   * The `text` should ask them in words too, as a live model's reply would.
   */
  question?: ChatQuestionSet;
  /**
   * The reply to whatever the visitor answers to `question`: one reply for
   * every answer, or a function of the answer as the message it was sent
   * as. A scripted prompt that matches the answer exactly still wins.
   */
  answered?: ScriptedReply | ((answer: string) => ScriptedReply);
}

/** A prompt the visitor can send, and the reply it routes to. */
export interface ScriptNode extends ScriptedReply {
  /** The exact chip text that routes here; matching forgives case and punctuation. */
  prompt: string;
}

/** A whole scripted conversation, the input to `createSimTransport`. */
export interface ChatScript {
  nodes: ScriptNode[];
  /** Replies for free text that matches no prompt, rotated per exchange. */
  fallbacks: ScriptedReply[];
  /** The reply to a turn that carried files and matched no prompt. */
  filesReply?: (names: string[]) => ScriptedReply;
}

/** The beats the player keeps. Schedule timings, not animation: reduced motion leaves them be. */
export interface SimTiming {
  /** Milliseconds per status step. */
  statusMs: number;
  /** The pause between the last step and the first word. */
  handoffMs: number;
  /** Milliseconds per word of the reply. */
  streamMs: number;
}

export const DEFAULT_SIM_TIMING: SimTiming = {
  statusMs: 1600,
  handoffMs: 350,
  streamMs: 30,
};

/** Chip labels route by text, so matching forgives case and punctuation. */
const normalize = (text: string) =>
  text
    .toLowerCase()
    .replace(/[^a-z0-9 ]/g, '')
    .replace(/\s+/g, ' ')
    .trim();

class SimAbortError extends Error {
  constructor() {
    super('Scripted response aborted');
    this.name = 'AbortError';
  }
}

const delay = (ms: number, signal: AbortSignal) =>
  new Promise<void>((resolve, reject) => {
    if (signal.aborted) {
      reject(new SimAbortError());
      return;
    }
    const timer = setTimeout(() => {
      signal.removeEventListener('abort', onAbort);
      resolve();
    }, ms);
    const onAbort = () => {
      clearTimeout(timer);
      reject(new SimAbortError());
    };
    signal.addEventListener('abort', onAbort, { once: true });
  });

/** The reply to a turn that carried files and matched no scripted prompt. */
export function defaultFilesReply(names: string[]): ScriptedReply {
  const shown = names.slice(0, 3).join(', ');
  const rest = names.length > 3 ? ` and ${names.length - 3} more` : '';
  const one = names.length === 1;
  return {
    steps: [
      {
        status: one ? 'Looking at the file' : 'Looking at the files',
        point: `${names.length} attached; note what each one is before answering.`,
      },
    ],
    text:
      `Got ${one ? 'it' : 'them'}: ${shown}${rest}. This chat is scripted, so ` +
      `${one ? 'the file' : 'the files'} stayed in your browser and nothing was ` +
      'uploaded or read. A live assistant would answer from the contents here.',
  };
}

/** What a script with no fallbacks says to free text. */
export const DEFAULT_FALLBACK_REPLY: ScriptedReply = {
  steps: [{ status: 'Reading the question', point: 'Nothing scripted matches this one.' }],
  text:
    'This chat is a scripted preview, so it only has answers written for the ' +
    'suggestions it offers. Pick one of them to see the conversation play out.',
};

/**
 * Plays a `ChatScript` as a transport.
 *
 * `followups` on a reply default to the first few scripted prompts that fit
 * a chip, so a script never ends on a reply with nowhere to go.
 */
export function createSimTransport(
  script: ChatScript,
  timing: Partial<SimTiming> = {}
): ChatTransport {
  const beats = { ...DEFAULT_SIM_TIMING, ...timing };
  const byPrompt = new Map(script.nodes.map((node) => [normalize(node.prompt), node]));
  const fallbacks = script.fallbacks.length > 0 ? script.fallbacks : [DEFAULT_FALLBACK_REPLY];
  const filesReply = script.filesReply ?? defaultFilesReply;
  /* Every reply that asks a question, by its text. The history the hook
     sends carries the asking reply word for word, so the answer's reply is
     found from the conversation itself, with no state kept here that a
     new chat would have to clear. */
  const asking = new Map<string, ScriptedReply>();
  const collect = (reply: ScriptedReply) => {
    if (!reply.question || asking.has(normalize(reply.text))) return;
    asking.set(normalize(reply.text), reply);
    if (reply.answered && typeof reply.answered !== 'function') collect(reply.answered);
  };
  for (const reply of [...script.nodes, ...script.fallbacks]) collect(reply);
  const defaultFollowups = script.nodes
    .map((node) => node.prompt)
    .filter(fitsChip)
    .slice(0, STARTER_COUNT);
  let exchangeCount = 0;

  return async function* simTransport(
    messages: ChatTransportMessage[],
    signal: AbortSignal
  ): AsyncGenerator<ChatEvent> {
    const lastUser = [...messages].reverse().find((m) => m.role === 'user');
    const prompted = lastUser ? byPrompt.get(normalize(lastUser.content)) : undefined;
    /* An answer to a scripted question routes to the reply written for it. */
    const previous = messages[messages.length - 2];
    const asked =
      !prompted && previous?.role === 'assistant' ? asking.get(normalize(previous.content)) : undefined;
    const answered =
      asked?.answered && lastUser
        ? typeof asked.answered === 'function'
          ? asked.answered(lastUser.content)
          : asked.answered
        : undefined;
    if (answered) collect(answered);
    const node: ScriptedReply | undefined = prompted ?? answered;

    /* Files with no scripted prompt behind them get an answer about the
       files, built from their names. Nothing was read: the bytes never left
       the visitor's browser, and the reply says so. */
    const attached = !node ? (lastUser?.attachments ?? []) : [];
    const reply: ScriptedReply =
      node ??
      (attached.length > 0
        ? filesReply(attached.map((file) => file.name))
        : fallbacks[exchangeCount % fallbacks.length]);
    if (!node && attached.length === 0) exchangeCount += 1;

    for (const step of reply.steps ?? []) {
      yield { type: 'status', label: step.status, point: step.point };
      await delay(beats.statusMs, signal);
    }

    await delay(beats.handoffMs, signal);

    const words = reply.text.split(' ');
    for (let i = 0; i < words.length; i += 1) {
      yield { type: 'delta', text: i === 0 ? words[i] : ` ${words[i]}` };
      await delay(beats.streamMs, signal);
    }

    if (reply.content) yield { type: 'content', node: reply.content };
    if (reply.card) yield { type: 'card', card: reply.card };

    /* Before `done`, like the event contract asks: the hook carries them
       into the turn when it commits, so the chips are there with the copy
       row rather than a beat behind it. */
    if (reply.question) {
      // A reply that asks ends in the question, not in chips beside it.
      yield { type: 'question', set: reply.question };
    } else {
      const followups = (reply.followups ?? defaultFollowups).filter(fitsChip);
      if (followups.length > 0) yield { type: 'followups', items: followups };
    }
    yield { type: 'done' };
  };
}

/* ============================================
   scriptChat(): the authoring API.

     const transport = scriptChat()
       .user('How do I get started?')
       .assistant('Create a workspace, then invite your team.', {
         steps: [{ status: 'Reading the first-run flow' }],
         followups: ['What do the plans include?'],
       })
       .user('What do the plans include?')
       .assistant('Every plan includes unlimited projects.')
       .transport();

   Each `.user()` names a prompt and the `.assistant()` that follows answers
   it. A reply's `followups` should name other prompts in the script, so the
   chips always lead somewhere; left out, they default to the script's first
   prompts. `.fallback()` adds a reply for typed text that matches nothing.
   ============================================ */

export interface ChatScriptBuilder {
  /** The next prompt the visitor can send. Must be followed by `.assistant()`. */
  user(prompt: string): ChatScriptBuilder;
  /** The reply to the last `.user()` prompt. */
  assistant(text: string, options?: Omit<ScriptedReply, 'text'>): ChatScriptBuilder;
  /** A reply for typed text that matches no prompt. Several rotate per exchange. */
  fallback(text: string, options?: Omit<ScriptedReply, 'text'>): ChatScriptBuilder;
  /** The reply to a turn that carried files and matched no prompt. */
  onFiles(reply: (names: string[]) => ScriptedReply): ChatScriptBuilder;
  /** The finished script, for `createSimTransport` or inspection. */
  build(): ChatScript;
  /** The finished script as a transport, ready for `ChatProvider`. */
  transport(timing?: Partial<SimTiming>): ChatTransport;
}

export function scriptChat(): ChatScriptBuilder {
  const nodes: ScriptNode[] = [];
  const fallbacks: ScriptedReply[] = [];
  let filesReply: ChatScript['filesReply'];
  let pendingPrompt: string | null = null;

  const builder: ChatScriptBuilder = {
    user(prompt) {
      if (pendingPrompt !== null) {
        throw new Error(`scriptChat: "${pendingPrompt}" has no .assistant() reply.`);
      }
      pendingPrompt = prompt;
      return builder;
    },
    assistant(text, options = {}) {
      if (pendingPrompt === null) {
        throw new Error('scriptChat: .assistant() needs a .user() prompt before it.');
      }
      nodes.push({ prompt: pendingPrompt, text, ...options });
      pendingPrompt = null;
      return builder;
    },
    fallback(text, options = {}) {
      fallbacks.push({ text, ...options });
      return builder;
    },
    onFiles(reply) {
      filesReply = reply;
      return builder;
    },
    build() {
      if (pendingPrompt !== null) {
        throw new Error(`scriptChat: "${pendingPrompt}" has no .assistant() reply.`);
      }
      return { nodes: [...nodes], fallbacks: [...fallbacks], filesReply };
    },
    transport(timing) {
      return createSimTransport(builder.build(), timing);
    },
  };
  return builder;
}

/**
 * Conversation starters: the welcome screen's first guess at why someone
 * opened the chat.
 *
 * A host holds a pool of pre-written questions per context (per page, per
 * screen) and a seeded pick draws a few of them. The seed lives in the chat
 * provider: rolled once per load and again on "New chat", so a refresh or a
 * fresh conversation shows a different mix while re-renders never reshuffle
 * under the visitor. Pre-written on purpose: the variety is theatre, not
 * tokens, and no model is asked for any of these.
 *
 * Every label has to fit on one chip (SUGGESTION_MAX_CHARS); the widget
 * drops one that does not rather than clipping it.
 */
import { fitsChip } from './suggestions';
import type { Starter } from './types';

export type { Starter };

/** How many chips the welcome screen shows, drawn from a pool. */
export const STARTER_COUNT = 3;

/** The named wording when it fits the chip, the unnamed one when it does not. */
export const namedStarter = (withName: string, without: string): string =>
  fitsChip(withName) ? withName : without;

/* FNV-1a over the key, so each context draws a different slice of the
   load's seed: two pages seen in one visit should not echo each other. */
export function hashString(input: string): number {
  let hash = 2166136261;
  for (let i = 0; i < input.length; i += 1) {
    hash ^= input.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  return hash >>> 0;
}

/* mulberry32, a tiny deterministic PRNG. Deterministic matters more than
   quality here: the same (seed, key) must pick the same chips on every
   render, or the set would churn as the visitor types. */
export function mulberry32(seed: number): () => number {
  let state = seed >>> 0;
  return () => {
    state = (state + 0x6d2b79f5) | 0;
    let t = Math.imul(state ^ (state >>> 15), 1 | state);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/**
 * Draw STARTER_COUNT starters from a pool, deterministically for a given
 * (seed, key) pair. A null seed returns the head of the pool unshuffled:
 * pools lead with their strongest questions, so callers without a seed (and
 * a server, if one ever renders this) get the curated order.
 */
export function pickStarters(pool: Starter[], seed: number | null, key: string): Starter[] {
  if (pool.length <= STARTER_COUNT) return pool;
  if (seed === null) return pool.slice(0, STARTER_COUNT);
  const rand = mulberry32(hashString(key) ^ Math.floor(seed * 0xffffffff));
  const shuffled = [...pool];
  for (let i = shuffled.length - 1; i > 0; i -= 1) {
    const j = Math.floor(rand() * (i + 1));
    [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
  }
  return shuffled.slice(0, STARTER_COUNT);
}

'use client';

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import type {
  ThreadPanelGroup,
  ThreadPanelProject,
  ThreadPanelThread,
  ThreadPanelThreadAction,
} from '../components/ThreadPanel/ThreadPanel';
import type { ThreadTab } from '../components/ThreadTabs/ThreadTabs';
import type { ChatState } from './useChat';
import { MOTION_THREAD_NAMING_DELAY_MS } from '../tokens/motion';

/* ============================================
   The thread lifecycle.

   The widget's history rail and tab strip are visual staging over this
   state machine: a thread is born from the first utterance (not from the
   New chat button), lands at the top of the home group already shimmering,
   and gets its name a beat later; the overflow menu renames inline, deletes,
   and pins (which moves the row into the leading Pinned group); tabs hold
   thread ids, a fresh thread arrives with one, and closing the last tab
   returns to the greeting. One rule keeps every entry point honest: no
   utterance means no active thread.

   Switching a thread or a tab moves the selection, never the transcript:
   the widget shows one conversation, and the rail says which the visitor
   is "in". A host that keeps real conversations per thread wires the
   callbacks below to its own store.
   ============================================ */

/**
 * How long the shimmer runs after the first utterance before the name
 * "arrives". Paced like a fast title-generation call, not a UI transition,
 * so it is a schedule rather than a motion token.
 */
export const THREAD_NAMING_DELAY_MS = MOTION_THREAD_NAMING_DELAY_MS;

/** The words the thread engine writes into its state, each with an English default. */
export interface ThreadsLabels {
  /** The row menu's pin action. Defaults to "Pin". */
  pin?: string;
  /** The row menu's unpin action. Defaults to "Unpin". */
  unpin?: string;
  /** The row menu's rename action. Defaults to "Rename". */
  rename?: string;
  /** The row menu's delete action. Defaults to "Delete". */
  delete?: string;
  /** A new project's name, given its ordinal. Defaults to "New project <n>". */
  newProject?: (index: number) => string;
  /** A new project's meta line. Defaults to "now". */
  newProjectMeta?: string;
}

export interface ThreadsOptions {
  /** The history to start from. The groups' labels are the host's. */
  groups?: ThreadPanelGroup[];
  /** The projects section, when the rail shows one. */
  projects?: ThreadPanelProject[];
  /** The group pinned threads move into. Created on first pin when absent. */
  pinnedGroup?: string;
  /** The group a new thread is born into. Defaults to the first non-pinned group. */
  homeGroup?: string;
  /**
   * The name a new thread gets once its shimmer resolves. Called with the
   * thread's ordinal; a host with a real title generator returns a promise.
   */
  nameThread?: (index: number) => string | Promise<string>;
  /** How long the naming shimmer runs. */
  namingDelayMs?: number;
  /** Offer pin and unpin in each row's menu, and keep the pinned group. */
  pins?: boolean;
  /** Keep each row's detail anatomy (description, status, icon, meta). Off strips rows to bare titles. */
  details?: boolean;
  /** The label of the New chat row and tab. */
  newThreadLabel?: string;
  /** The row actions' names and a new project's name and meta, merged over their English defaults. */
  labels?: ThreadsLabels;
  /** Called when a thread is selected, so a host can load its conversation. */
  onSelect?: (threadId: string) => void;
  onRename?: (threadId: string, title: string) => void;
  onDelete?: (threadId: string) => void;
  onPin?: (threadId: string, pinned: boolean) => void;
}

/** The thread lifecycle, shaped for ThreadPanel and ThreadTabs. */
export interface ThreadsState {
  /** The groups to hand ThreadPanel, shaped by the pins and details options. */
  groups: ThreadPanelGroup[];
  /** The selected thread, or '' on the greeting screen. */
  activeThreadId: string;
  /** Select a thread (and open its tab). */
  select: (threadId: string) => void;
  /** Back to the greeting: resets the conversation and deselects. */
  startNew: () => void;
  remove: (threadId: string) => void;
  rename: (threadId: string, title: string) => void;
  togglePin: (threadId: string) => void;
  /** The thread whose row is showing the inline rename editor. */
  renamingId: string | null;
  setRenamingId: (threadId: string | null) => void;
  /** Each row's overflow menu: pin or unpin (when pins are on), rename, delete. */
  actionsFor: (thread: ThreadPanelThread) => ThreadPanelThreadAction[];
  /** Run a row action by id: 'pin', 'rename' or 'delete'. */
  runAction: (threadId: string, actionId: string) => void;
  projects: ThreadPanelProject[];
  activeProjectId: string | undefined;
  selectProject: (projectId: string) => void;
  createProject: () => void;
  /** The open sessions, for ThreadTabs. Resolved live from the groups. */
  tabs: ThreadTab[];
  closeTab: (threadId: string) => void;
  newThreadLabel: string;
}

const DEFAULT_LABELS: Required<ThreadsLabels> = {
  pin: 'Pin',
  unpin: 'Unpin',
  rename: 'Rename',
  delete: 'Delete',
  newProject: (index) => `New project ${index}`,
  newProjectMeta: 'now',
};

const DEFAULT_NAMES = ['New conversation'];

/**
 * The thread lifecycle over a conversation. `chat` is the state from
 * `useChat` (the provider passes its own); the hook watches whether the
 * conversation has an utterance to decide when a thread is born and when
 * the selection clears.
 */
export function useThreads(
  chat: Pick<ChatState, 'turns' | 'live' | 'reset'>,
  options: ThreadsOptions = {}
): ThreadsState {
  const {
    pins = true,
    details = true,
    namingDelayMs = THREAD_NAMING_DELAY_MS,
    newThreadLabel = 'New chat',
    pinnedGroup = 'Pinned',
    onSelect,
    onRename,
    onDelete,
    onPin,
  } = options;
  const labelsOption = options.labels;
  const labels = useMemo(() => ({ ...DEFAULT_LABELS, ...labelsOption }), [labelsOption]);
  const nameThreadOption = options.nameThread;
  const nameThread = useMemo(
    () => nameThreadOption ?? ((index: number) => DEFAULT_NAMES[index % DEFAULT_NAMES.length]),
    [nameThreadOption]
  );
  const initialGroups = options.groups ?? [];
  const homeGroup =
    options.homeGroup ??
    initialGroups.find((group) => group.label !== pinnedGroup)?.label ??
    'Recent';

  const [groups, setGroups] = useState<ThreadPanelGroup[]>(initialGroups);
  const [activeThreadId, setActiveThreadId] = useState('');
  const [renamingId, setRenamingId] = useState<string | null>(null);
  const [projects, setProjects] = useState<ThreadPanelProject[]>(options.projects ?? []);
  const [activeProjectId, setActiveProjectId] = useState<string | undefined>(
    options.projects?.[0]?.id
  );
  const [openTabs, setOpenTabs] = useState<string[]>([]);

  /* The naming simulation's clockwork: a sequence for fresh ids, a cursor
     into the name source, and the pending timers so deleting a still-naming
     thread (or unmounting) cancels its reveal. */
  const threadSeq = useRef(0);
  const nameCursor = useRef(0);
  const projectSeq = useRef(0);
  const namingTimers = useRef(new Map<string, ReturnType<typeof setTimeout>>());
  useEffect(() => {
    const timers = namingTimers.current;
    return () => timers.forEach((timer) => clearTimeout(timer));
  }, []);

  const updateThread = useCallback(
    (id: string, patch: (thread: ThreadPanelThread) => ThreadPanelThread) => {
      setGroups((current) =>
        current.map((group) => ({
          ...group,
          threads: group.threads.map((thread) => (thread.id === id ? patch(thread) : thread)),
        }))
      );
    },
    []
  );

  /* A thread is born from the first utterance: the row lands at the top of
     the home group already shimmering, and its title arrives a beat later. */
  const beginThread = useCallback(() => {
    threadSeq.current += 1;
    const id = `thread-${threadSeq.current}`;
    setGroups((current) => {
      const hasHome = current.some((group) => group.label === homeGroup);
      const withHome = hasHome ? current : [...current, { label: homeGroup, threads: [] }];
      return withHome.map((group) =>
        group.label === homeGroup
          ? { ...group, threads: [{ id, title: newThreadLabel, pending: true }, ...group.threads] }
          : group
      );
    });
    setActiveThreadId(id);
    setOpenTabs((tabs) => (tabs.includes(id) ? tabs : [...tabs, id]));
    const ordinal = nameCursor.current;
    nameCursor.current += 1;
    const timer = setTimeout(async () => {
      namingTimers.current.delete(id);
      const title = await nameThread(ordinal);
      updateThread(id, () => ({ id, title }));
    }, namingDelayMs);
    namingTimers.current.set(id, timer);
  }, [homeGroup, nameThread, namingDelayMs, newThreadLabel, updateThread]);

  /* No utterance means no active thread. The greeting screen deselects the
     rail whether it arrived via New chat, a reset, or a deleted thread, and
     the first utterance sent with nothing selected is what creates the
     pending row. Transition-guarded so merely selecting a thread while the
     greeting shows keeps its pill. */
  const hasUtterance = chat.turns.length > 0 || chat.live !== null;
  const hadUtteranceRef = useRef(hasUtterance);
  const birthingRef = useRef(false);
  useEffect(() => {
    const had = hadUtteranceRef.current;
    hadUtteranceRef.current = hasUtterance;
    if (hasUtterance && activeThreadId === '') {
      if (!birthingRef.current) {
        birthingRef.current = true;
        beginThread();
      }
    } else {
      birthingRef.current = false;
      if (!hasUtterance && had && activeThreadId !== '') {
        setActiveThreadId('');
        setRenamingId(null);
      }
    }
  }, [hasUtterance, activeThreadId, beginThread]);

  const { reset } = chat;
  const startNew = useCallback(() => {
    reset();
    setActiveThreadId('');
    setRenamingId(null);
  }, [reset]);

  /* Selecting a thread, from the rail or its tab, moves the pill, opens (or
     revisits) the session's tab, and settles an unread row to idle. */
  const select = useCallback(
    (id: string) => {
      setActiveThreadId(id);
      setOpenTabs((tabs) => (tabs.includes(id) ? tabs : [...tabs, id]));
      updateThread(id, (thread) =>
        thread.status === 'unread' ? { ...thread, status: 'idle' } : thread
      );
      onSelect?.(id);
    },
    [onSelect, updateThread]
  );

  const remove = useCallback(
    (id: string) => {
      const timer = namingTimers.current.get(id);
      if (timer != null) {
        clearTimeout(timer);
        namingTimers.current.delete(id);
      }
      setGroups((current) =>
        current.map((group) => ({
          ...group,
          threads: group.threads.filter((thread) => thread.id !== id),
        }))
      );
      setOpenTabs((tabs) => tabs.filter((tab) => tab !== id));
      setRenamingId((renaming) => (renaming === id ? null : renaming));
      if (activeThreadId === id) {
        /* The open conversation went with its thread: back to the greeting. */
        setActiveThreadId('');
        reset();
      }
      onDelete?.(id);
    },
    [activeThreadId, onDelete, reset]
  );

  const rename = useCallback(
    (id: string, title: string) => {
      updateThread(id, (thread) => ({ ...thread, title }));
      setRenamingId(null);
      onRename?.(id, title);
    },
    [onRename, updateThread]
  );

  /* Pinning moves the thread into the leading Pinned group; unpinning
     returns it to the top of the home group. */
  const togglePin = useCallback(
    (id: string) => {
      let nowPinned = false;
      setGroups((current) => {
        let moved: ThreadPanelThread | undefined;
        let wasPinned = false;
        const stripped = current.map((group) => ({
          ...group,
          threads: group.threads.filter((thread) => {
            if (thread.id !== id) return true;
            moved = thread;
            wasPinned = Boolean(thread.pinned);
            return false;
          }),
        }));
        const taken = moved as ThreadPanelThread | undefined;
        if (!taken) return current;
        nowPinned = !wasPinned;
        const hasPinned = stripped.some((group) => group.label === pinnedGroup);
        const withPinned =
          hasPinned || wasPinned ? stripped : [{ label: pinnedGroup, threads: [] }, ...stripped];
        return withPinned.map((group) => {
          if (!wasPinned && group.label === pinnedGroup) {
            return { ...group, threads: [...group.threads, { ...taken, pinned: true }] };
          }
          if (wasPinned && group.label === homeGroup) {
            return { ...group, threads: [{ ...taken, pinned: undefined }, ...group.threads] };
          }
          return group;
        });
      });
      onPin?.(id, nowPinned);
    },
    [homeGroup, onPin, pinnedGroup]
  );

  /* Closing a tab closes the session view, never the thread: the history
     keeps the row. Closing the active tab moves to a neighbour; closing the
     last one returns to the greeting. */
  const closeTab = useCallback(
    (id: string) => {
      const index = openTabs.indexOf(id);
      setOpenTabs((tabs) => tabs.filter((tab) => tab !== id));
      if (activeThreadId === id) {
        const neighbour = openTabs[index + 1] ?? openTabs[index - 1];
        if (neighbour) select(neighbour);
        else startNew();
      }
    },
    [activeThreadId, openTabs, select, startNew]
  );

  const selectProject = useCallback((id: string) => setActiveProjectId(id), []);
  const createProject = useCallback(() => {
    projectSeq.current += 1;
    const id = `project-${projectSeq.current}`;
    const index = projectSeq.current;
    setProjects((list) => [...list, { id, label: labels.newProject(index), meta: labels.newProjectMeta }]);
    setActiveProjectId(id);
  }, [labels]);

  const actionsFor = useCallback(
    (thread: ThreadPanelThread): ThreadPanelThreadAction[] =>
      pins
        ? [
            { id: 'pin', label: thread.pinned ? labels.unpin : labels.pin, icon: 'keep' },
            { id: 'rename', label: labels.rename, icon: 'edit' },
            { id: 'delete', label: labels.delete, icon: 'delete', destructive: true },
          ]
        : [
            { id: 'rename', label: labels.rename, icon: 'edit' },
            { id: 'delete', label: labels.delete, icon: 'delete', destructive: true },
          ],
    [pins, labels]
  );

  const runAction = useCallback(
    (threadId: string, actionId: string) => {
      if (actionId === 'rename') setRenamingId(threadId);
      else if (actionId === 'delete') remove(threadId);
      else if (actionId === 'pin') togglePin(threadId);
    },
    [remove, togglePin]
  );

  /* The rail's render shape follows the options: pins off folds the pinned
     group back into the home group, details off strips the rows to bare
     titles, and each row carries its menu. */
  const shapedGroups = useMemo(() => {
    let shaped = groups;
    if (!pins) {
      const pinned = shaped.find((group) => group.label === pinnedGroup)?.threads ?? [];
      shaped = shaped
        .filter((group) => group.label !== pinnedGroup)
        .map((group) =>
          group.label === homeGroup
            ? {
                ...group,
                threads: [
                  ...pinned.map((thread) => ({ ...thread, pinned: undefined })),
                  ...group.threads,
                ],
              }
            : group
        );
    }
    return shaped.map((group) => ({
      ...group,
      threads: group.threads.map((thread) => {
        const row = details
          ? thread
          : { ...thread, description: undefined, status: undefined, icon: undefined, meta: undefined };
        return { ...row, actions: actionsFor(thread) };
      }),
    }));
  }, [groups, pins, pinnedGroup, homeGroup, details, actionsFor]);

  /* The strip's tabs resolve live from the history, so a rename or the
     naming shimmer's reveal flows straight into the label. */
  const tabs = useMemo<ThreadTab[]>(() => {
    const byId = new Map<string, ThreadPanelThread>();
    for (const group of groups) for (const thread of group.threads) byId.set(thread.id, thread);
    return openTabs.flatMap((id) => {
      const thread = byId.get(id);
      return thread
        ? [{ id, label: thread.title, icon: 'chat_bubble', status: details ? thread.status : undefined }]
        : [];
    });
  }, [openTabs, groups, details]);

  return {
    groups: shapedGroups,
    activeThreadId,
    select,
    startNew,
    remove,
    rename,
    togglePin,
    renamingId,
    setRenamingId,
    actionsFor,
    runAction,
    projects,
    activeProjectId,
    selectProject,
    createProject,
    tabs,
    closeTab,
    newThreadLabel,
  };
}

import type { ChatEvent, ChatTransport, ChatTransportMessage } from './types';

/* ============================================
   The fetch transport.

   Posts the conversation to a server handler (createChatHandler, or any
   endpoint speaking the same NDJSON protocol) and yields the events it
   streams back. Same event shapes as the scripted transport, so the widget
   cannot tell which one it is running on.

   Three obligations come from the ChatTransport contract: close the reader
   in a finally (the consumer breaks on `done`, which invokes the iterator's
   return()), check the signal between yields, and run its own first-byte
   watchdog because the consumer has no timeout of its own.
   ============================================ */

/**
 * How long to wait for the first byte before giving up. Generous on purpose:
 * a cold prompt cache costs several seconds before the model starts, and a
 * false timeout is worse than a slow answer.
 */
export const FIRST_BYTE_TIMEOUT_MS = 15_000;

/** Turns sent upstream. The handler re-enforces this; sending less saves bytes. */
export const MAX_TRANSPORT_TURNS = 10;

/** The copy a failed request becomes, by its HTTP status. */
export interface FetchTransportCopy {
  /** The request could not be sent at all. */
  unreachable: string;
  /** 400: the server rejected the message shape. */
  badRequest: string;
  /** 429: too many requests. */
  rateLimited: string;
  /** 5xx. */
  serverError: string;
  /** Anything else. */
  other: string;
}

export const DEFAULT_FETCH_COPY: FetchTransportCopy = {
  unreachable: 'Could not reach the chat backend. Check your connection and try again.',
  badRequest: 'That message did not go through. Try rephrasing it.',
  rateLimited: 'That is a lot of questions at once. Give it a minute and try again.',
  serverError: 'The chat backend is having trouble. Try again in a moment.',
  other: 'Something went wrong sending that. Try again.',
};

function httpErrorMessage(status: number, copy: FetchTransportCopy): string {
  if (status === 400) return copy.badRequest;
  if (status === 429) return copy.rateLimited;
  if (status >= 500) return copy.serverError;
  return copy.other;
}

export interface FetchTransportOptions {
  /**
   * The visitor's explicit model pick (a wire value from the host's model
   * list), read at send time so a mid-conversation switch applies from the
   * next message. Null means no pick was made: the server applies its own
   * default, which is the distinction that lets a budget tier move the
   * default without fighting a visitor who never touched the picker.
   */
  getModel?: () => string | null;
  /**
   * The context the request carries as `path`: by default the page the
   * visitor is on, read at send time so a conversation that spans several
   * pages sends each question with the page it was asked from. The handler
   * treats it as untrusted input and sanitises it. Return null to send none.
   */
  getContext?: () => string | null;
  /** Replacement copy for the failure messages. */
  copy?: Partial<FetchTransportCopy>;
}

/**
 * A transport over `fetch` to an NDJSON chat endpoint.
 *
 * `endpoint` defaults to `/api/chat`, which is where `npx rift-ds init chat`
 * writes the server handler; a host with its own URL passes it.
 */
export function createFetchTransport(
  endpoint = '/api/chat',
  options: FetchTransportOptions = {}
): ChatTransport {
  const copy = { ...DEFAULT_FETCH_COPY, ...options.copy };
  const getContext =
    options.getContext ??
    (() => (typeof window !== 'undefined' ? window.location.pathname : null));

  return async function* fetchTransport(
    messages: ChatTransportMessage[],
    signal: AbortSignal
  ): AsyncGenerator<ChatEvent> {
    const path = getContext() ?? undefined;
    const model = options.getModel?.() ?? undefined;
    // One controller for both stop conditions: the caller aborting, and the
    // watchdog firing. The fetch only ever sees this composed signal.
    const controller = new AbortController();
    const abort = () => controller.abort();
    signal.addEventListener('abort', abort);

    let watchdog: ReturnType<typeof setTimeout> | null = setTimeout(
      abort,
      FIRST_BYTE_TIMEOUT_MS
    );
    const clearWatchdog = () => {
      if (watchdog !== null) {
        clearTimeout(watchdog);
        watchdog = null;
      }
    };

    let reader: ReadableStreamDefaultReader<Uint8Array> | null = null;

    try {
      let response: Response;
      try {
        response = await fetch(endpoint, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            /* Role and text, named field by field: a message may carry
               attachment details for a scripted chat, and nothing about a
               file is ever sent to the server. */
            messages: messages
              .slice(-MAX_TRANSPORT_TURNS)
              .map(({ role, content }) => ({ role, content })),
            path,
            model,
          }),
          signal: controller.signal,
        });
      } catch {
        // An abort from the caller is not a failure to report: the hook
        // already handles a stopped stream, and an error event would replace
        // whatever text had arrived.
        if (signal.aborted) return;
        yield { type: 'error', message: copy.unreachable };
        return;
      }

      if (!response.ok || !response.body) {
        yield { type: 'error', message: httpErrorMessage(response.status, copy) };
        return;
      }

      reader = response.body.getReader();
      const decoder = new TextDecoder();
      let buffer = '';

      while (true) {
        if (signal.aborted) return;

        const { done, value } = await reader.read();

        // The stream is open, so the connection is no longer at risk of
        // hanging before it starts.
        clearWatchdog();

        if (done) break;

        buffer += decoder.decode(value, { stream: true });

        // The last segment is whatever arrived after the final newline, which
        // is usually a partial line. Hold it until the rest turns up.
        const lines = buffer.split('\n');
        buffer = lines.pop() ?? '';

        for (const line of lines) {
          const event = parseEvent(line);
          if (!event) continue;
          yield event;
          if (signal.aborted) return;
        }
      }

      // A well-formed stream ends with a newline, so this is normally empty.
      const trailing = parseEvent(buffer);
      if (trailing) yield trailing;
    } finally {
      clearWatchdog();
      signal.removeEventListener('abort', abort);
      if (reader) {
        // Releases the connection when the consumer breaks out early.
        await reader.cancel().catch(() => {});
      }
    }
  };
}

/** One NDJSON line to an event, ignoring blank or malformed lines. */
function parseEvent(line: string): ChatEvent | null {
  const trimmed = line.trim();
  if (!trimmed) return null;
  try {
    return JSON.parse(trimmed) as ChatEvent;
  } catch {
    // A truncated final line is expected when a stream is cut mid-write;
    // dropping it is better than failing the whole turn.
    return null;
  }
}

import type { ReactNode } from 'react';
import type { AttachmentItem } from '../components/Attachment/fileTypes';
import type { QuestionCardAnswer, QuestionCardQuestion } from '../components/QuestionCard/QuestionCard';

/* ============================================
   The chat event contract.

   A transport turns a conversation into a stream of these events. The
   scripted transport plays them from a script; the fetch transport parses
   the same shapes off an NDJSON response the server handler streams; a
   consumer's own transport yields whatever it likes. Swapping transports is
   the whole integration: the widget cannot tell which one it is running on.
   ============================================ */

/**
 * Rich content that can cross a network: a kind the host knows how to draw
 * and the data to draw it from. The provider's `renderers` map turns one
 * into a React node when the turn renders. A tool can answer with one from
 * the server handler, and a script can attach one to a reply.
 */
export interface ChatCard {
  /** The renderer key, e.g. "chart" or "plan". Unknown kinds render nothing. */
  kind: string;
  /** Whatever the renderer for `kind` expects. Must survive JSON. */
  data: unknown;
}

/**
 * Something the chat made that is worth more room than a turn can give it: a
 * dashboard, a document, a page, a site. It travels as an ordinary card of
 * kind `ARTIFACT_CARD_KIND`, so any transport that can send a card can send
 * one; the thread draws it as a tile, and the tile opens the artifact panel
 * beside the conversation.
 */
export interface ChatArtifact {
  /** Stable identity: the same id reopened is the same artifact. */
  id: string;
  /** The artifact's name, on the tile and in the panel's header. */
  title: string;
  /**
   * How to draw it. `html` frames the `html` document, `url` frames the
   * `url`, `code` shows the `code` alone; any other kind is drawn by the
   * provider's `artifactRenderers`. An unknown kind with no renderer falls
   * back to whichever of `html`, `url` and `code` it carries.
   */
  kind: string;
  /** A quiet line beside the name: what it is, or which version. */
  meta?: string;
  /** A Material Symbol name for the tile and the header. */
  icon?: string;
  /** A complete HTML document, drawn in a sandboxed frame. */
  html?: string;
  /** A page to frame. Only http(s) URLs and same-site paths are framed. */
  url?: string;
  /** The source, offered as the panel's Code view. An `html` artifact offers its document when this is absent. */
  code?: string;
  /** The source's language. */
  language?: string;
  /** Whatever a custom renderer for `kind` expects. Must survive JSON. */
  data?: unknown;
}

/** The card kind an artifact travels as. Its `data` is a `ChatArtifact`. */
export const ARTIFACT_CARD_KIND = 'artifact';

/** One question the agent asks: a prompt and the answers on offer. The shape QuestionCard draws. */
export type ChatQuestion = QuestionCardQuestion;

/** What the visitor answered to one question. */
export type ChatQuestionAnswer = QuestionCardAnswer;

/**
 * Questions the agent asks at the end of a reply, with the answers it can
 * list: one question or a short set, each taking one option or several.
 * The reply's text asks in words too, so a transport or a renderer that
 * drops the set still leaves a conversation that reads correctly.
 */
export interface ChatQuestionSet {
  /** Stable identity within the conversation. */
  id: string;
  /** Asked one at a time when there is more than one. A set of more than one holds the composer until it is answered or skipped. */
  questions: ChatQuestion[];
}

/**
 * The answers to a question set as a user turn draws them: each question's
 * prompt and the labels picked. The turn's `text` is the same answers as
 * the plain message the model reads.
 */
export interface ChatReply {
  items: { prompt: string; answers: string[] }[];
}

export type ChatEvent =
  /** A live status step: the AgentStatus label, with an optional reasoning trace point. */
  | { type: 'status'; label: string; point?: string }
  /** The model serving this exchange, as a display label ("Sonnet 5").
      The server's per-answer ground truth; kept in state but not rendered
      by the widget today, whose picker follows the `models` offer event. */
  | { type: 'model'; label: string }
  /** What the server is offering right now: the wire value it defaults to,
      and any values the day's budget has locked out. The picker follows
      this: the server owns the default and the lock, the client only
      expresses a preference. */
  | { type: 'models'; default: string; locked: string[] }
  /** A chunk of response text. The first delta ends the thinking phase. */
  | { type: 'delta'; text: string }
  /** The server-side log id for this exchange. Feedback references it, so a
      thumbs verdict can be joined back to the logged question and answer.
      A transport that never sends one hides the thumbs, which is what a
      script does. */
  | { type: 'exchange'; id: string }
  /** Follow-up questions to offer under the finished answer. A transport that
      can produce them yields this before `done`; the fetch transport cannot
      (they are written from the completed answer, so waiting for them would
      hold the turn open) and the provider fetches them after the turn
      commits instead. */
  | { type: 'followups'; items: string[] }
  /** Rich content, as a React node, drawn on the live reply as it arrives
      and kept with the committed turn. Only an in-browser transport can
      yield one (a script, or `injectTurn`); the network form is `card`. */
  | { type: 'content'; node: ReactNode }
  /** Rich content as serialisable data the provider's `renderers` draw,
      on the live reply as it arrives and with the committed turn. The form
      a server can send. */
  | { type: 'card'; card: ChatCard }
  /** Questions the agent asks with answers to pick, drawn under the committed
      turn in place of follow-ups: a turn that asks is never asked about. */
  | { type: 'question'; set: ChatQuestionSet }
  /** Terminal: the response is complete. */
  | { type: 'done' }
  /** A guardrail response (rate limit, circuit breaker): rendered as a normal assistant message. */
  | { type: 'notice'; text: string }
  /** A failure the user should see, phrased for humans. */
  | { type: 'error'; message: string };

/** Every event kind, for documentation that enumerates the protocol. */
export const CHAT_EVENT_KINDS = [
  'status',
  'model',
  'models',
  'delta',
  'exchange',
  'followups',
  'content',
  'card',
  'question',
  'done',
  'notice',
  'error',
] as const satisfies readonly ChatEvent['type'][];

export interface ChatTransportMessage {
  role: 'user' | 'assistant';
  content: string;
  /**
   * What was attached to a user message: names and kinds, never bytes. The
   * scripted transport reads it to answer about the files. The fetch
   * transport drops it before the request is built, so nothing about an
   * attachment reaches the server.
   */
  attachments?: { name: string; kind: AttachmentItem['kind']; size?: number }[];
}

/**
 * A transport streams events for one exchange. Abort the signal to stop it.
 *
 * Contract notes for implementations:
 * - The consumer `break`s out of its `for await` loop on `done` (and on
 *   abort), which invokes the iterator's `return()`: close any underlying
 *   reader or connection in a `try/finally`.
 * - Check the signal between yields; the consumer also guards its own loop,
 *   but a transport that ignores abort keeps its own work running.
 * - There is no first-event timeout on the consumer side: a transport that
 *   can hang before its first yield should implement its own watchdog.
 */
export type ChatTransport = (
  messages: ChatTransportMessage[],
  signal: AbortSignal
) => AsyncIterable<ChatEvent>;

/* ============================================
   Conversation state
   ============================================ */

/** One committed turn. Assistant turns keep their reasoning for the collapsed disclosure. */
export interface ChatTurn {
  id: string;
  role: 'user' | 'assistant';
  text: string;
  /** Reasoning trace points gathered while the response was live (assistant turns). */
  tracePoints?: string[];
  /** Seconds spent before the first response text (assistant turns). */
  durationSeconds?: number;
  /** The server's log id for the exchange, absent on scripted and placeholder turns. */
  exchangeId?: string;
  /** The visitor's thumbs verdict on this turn, kept for the session only. */
  feedback?: 'up' | 'down';
  /**
   * Follow-up questions offered under this answer. Undefined means none have
   * been asked for yet; an empty array means they were and none came back,
   * which is what stops a failed attempt being retried on every render.
   */
  followups?: string[];
  /**
   * Files sent with a user turn, drawn above its bubble. Their picture
   * previews are object URLs the hook owns from the moment of the send:
   * they are revoked on reset and on unmount.
   */
  attachments?: AttachmentItem[];
  /**
   * Rich content rendered with the turn as a React node: a tool call, a
   * card. Set by `injectTurn` or carried from a transport's `content` event.
   * Assistant turns render it between the reasoning and the prose; user
   * turns stack it above the bubble, like an attachment.
   */
  content?: ReactNode;
  /**
   * Rich content rendered with the turn through the provider's `renderers`,
   * carried from a transport's `card` event. Drawn where `content` is.
   */
  card?: ChatCard;
  /**
   * Questions this assistant turn asks, drawn under it as a QuestionCard in
   * place of follow-ups. Carried from a transport's `question` event.
   */
  question?: ChatQuestionSet;
  /**
   * The answers given to `question`. Undefined while it is open; an empty
   * array records a skip. Kept on the asking turn, so the card renders its
   * answered state where it was asked.
   */
  answers?: ChatQuestionAnswer[];
  /**
   * The answers a user turn carries, drawn as the bubble when there is more
   * than one to show. Its `text` is the same answers as a plain message.
   */
  reply?: ChatReply;
  /**
   * The follow-up chip the visitor sent from under this turn. Once set the
   * row is a record: the chip marked, the rest dimmed and inert.
   */
  followupChosen?: string;
  /**
   * Render `content` on its own in the thread, outside any message chrome,
   * for conversation furniture like a day marker.
   */
  bare?: boolean;
}

export type LivePhase = 'thinking' | 'streaming';

/** The assistant turn currently in flight, rendered after the committed turns. */
export interface LiveResponse {
  /**
   * The turn's stable id, minted at send time and kept when the turn
   * commits, so the rendered element keeps its identity and React
   * reconciles the finished response in place instead of remounting it.
   */
  id: string;
  phase: LivePhase;
  /** Current AgentStatus label while thinking. */
  statusLabel: string;
  tracePoints: string[];
  text: string;
  durationSeconds?: number;
  /** Carried from the transport's `exchange` event into the committed turn. */
  exchangeId?: string;
  /** Carried from the transport's `followups` event into the committed turn. */
  followups?: string[];
  /** The transport's `content` event, drawn on the live reply and carried into the committed turn. */
  content?: ReactNode;
  /** The transport's `card` event, drawn on the live reply and carried into the committed turn. */
  card?: ChatCard;
  /** Carried from the transport's `question` event into the committed turn. */
  question?: ChatQuestionSet;
}

/* ============================================
   Shared option shapes
   ============================================ */

/**
 * One model the widget can offer in its picker and the server handler can
 * serve. Shared by both halves so the wire value the client sends is one the
 * server knows.
 */
export interface ChatModelOption {
  /** Stable wire value: what the picker holds and the client sends. */
  value: string;
  /** The provider's model id the server calls. */
  id: string;
  /** Display name in the picker. */
  label: string;
  /** One line under the name in the picker. */
  description: string;
  /**
   * Whether the model takes adaptive thinking and the effort dial. A model
   * that predates them rejects both, so the handler sends it a plain request.
   */
  adaptiveThinking: boolean;
}

/** One conversation starter on the welcome screen. */
export interface Starter {
  id: string;
  label: string;
}

/** The thumbs verdict a visitor can give an answer. */
export type ChatFeedbackVerdict = 'up' | 'down';

/**
 * rift-ds/chat/upstash: the handlers' guardrails over Upstash Redis.
 *
 * Four layers, outermost last: the stateless caps in the chat handler
 * (message length, turn count), per-visitor rate limits so one visitor
 * cannot drain the day's budget, a site-wide daily circuit breaker on both
 * message count and estimated spend, and whatever spend cap the model
 * provider's console holds, which is the only layer that still stands if
 * this file has a bug.
 *
 * Fail-open by design. If Redis is unreachable or unconfigured, requests
 * are allowed through and the failure is logged: a guardrail outage should
 * not take the chat down, and the provider's cap still bounds the damage.
 * Every rejection returns copy for a `notice` event, which the widget
 * renders as an ordinary assistant message.
 *
 * Needs the optional peers `@upstash/ratelimit` and `@upstash/redis`.
 */
import { Ratelimit } from '@upstash/ratelimit';
import { Redis } from '@upstash/redis';
import type {
  ChatGuardrails,
  ExchangeLog,
  GuardrailVerdict,
  ModelTier,
  TokenUsage,
} from './server';
import type { ChatFeedbackVerdict } from './types';

/** List prices in USD per million tokens for one model id. */
export interface PriceRow {
  input: number;
  output: number;
  /** Cache writes; 2x input for a 1-hour cache TTL, 1.25x for the default. */
  cacheWrite: number;
  cacheRead: number;
}

/**
 * The built-in price table, keyed by model id. Over-estimating trips the
 * breaker early, which is the safe direction to be wrong in; real billing
 * comes from the provider's console. An unknown id prices at `fallbackPrice`.
 */
export const DEFAULT_PRICES: Record<string, PriceRow> = {
  'claude-sonnet-5': { input: 3.0, output: 15.0, cacheWrite: 6.0, cacheRead: 0.3 },
  'claude-haiku-5-5': { input: 0.5, output: 2.5, cacheWrite: 1.0, cacheRead: 0.05 },
};

export interface UpstashGuardrailsCopy {
  /** Too many messages in a minute. */
  burst: string;
  /** The per-visitor daily limit. */
  daily: string;
  /** The site-wide breaker. */
  paused: string;
}

export const DEFAULT_GUARDRAILS_COPY: UpstashGuardrailsCopy = {
  burst: 'That is a lot of questions at once. Give it a minute and ask again.',
  daily: 'You have reached the daily limit for this chat. It resets tomorrow.',
  paused: 'This chat has hit its budget for today and is paused until midnight UTC.',
};

export interface UpstashGuardrailsOptions {
  /** The Upstash REST URL. Missing means every check fails open. */
  url?: string;
  /** The Upstash REST token. */
  token?: string;
  /** Salts the hashed visitor address. Set it: an unsalted hash over the IPv4 space is reversible. */
  salt?: string;
  /** Redis key prefix, so several chats can share one database. */
  prefix?: string;
  /** Messages per visitor per minute. */
  perMinute?: number;
  /** Messages per visitor per day. */
  perDay?: number;
  /** Follow-up requests per visitor per minute. */
  followupsPerMinute?: number;
  /** Feedback posts per visitor per minute. */
  feedbackPerMinute?: number;
  /** The site-wide daily message cap. */
  dailyMessageCap?: number;
  /** The site-wide daily spend cap, in US cents. */
  dailySpendCapCents?: number;
  /** Past this fraction of the spend cap the default model steps down. */
  stepdownFraction?: number;
  /** Past this fraction only the budget model serves. */
  lockFraction?: number;
  /** Price rows by model id, merged over the built-in table. */
  prices?: Record<string, PriceRow>;
  /** The row an unknown model id prices at. Defaults to the dearest built-in row. */
  fallbackPrice?: PriceRow;
  /** How long an exchange log line lives, in seconds. */
  logTtlSeconds?: number;
  copy?: Partial<UpstashGuardrailsCopy>;
}

const dayKey = () => new Date().toISOString().slice(0, 10);
const COUNTER_TTL_SECONDS = 60 * 60 * 48;

async function sha256Hex(text: string): Promise<string> {
  const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(text));
  return Array.from(new Uint8Array(digest), (byte) => byte.toString(16).padStart(2, '0')).join('');
}

/**
 * Guardrails over Upstash Redis: per-visitor rate limits, a daily breaker
 * with model tiers, the exchange log (30 days by default) and the feedback
 * store. Pass the result as `guardrails` to all three handlers.
 */
export function createUpstashGuardrails(options: UpstashGuardrailsOptions = {}): ChatGuardrails {
  const prefix = options.prefix ?? 'chat';
  const perMinute = options.perMinute ?? 10;
  const perDay = options.perDay ?? 60;
  const followupsPerMinute = options.followupsPerMinute ?? 15;
  const feedbackPerMinute = options.feedbackPerMinute ?? 30;
  const dailyMessageCap = options.dailyMessageCap ?? 300;
  const dailySpendCapTenths = (options.dailySpendCapCents ?? 500) * 10;
  const stepdownFraction = options.stepdownFraction ?? 0.5;
  const lockFraction = options.lockFraction ?? 0.85;
  const prices = { ...DEFAULT_PRICES, ...options.prices };
  const fallbackPrice = options.fallbackPrice ?? DEFAULT_PRICES['claude-sonnet-5'];
  const logTtl = options.logTtlSeconds ?? 60 * 60 * 24 * 30;
  const copy = { ...DEFAULT_GUARDRAILS_COPY, ...options.copy };
  const salt = options.salt ?? '';

  let warned = false;
  const redis: Redis | null =
    options.url && options.token ? new Redis({ url: options.url, token: options.token }) : null;
  const getRedis = () => {
    if (!redis && !warned) {
      warned = true;
      console.warn('[chat] Upstash url/token unset: rate limits and the daily breaker are inactive.');
    }
    return redis;
  };

  const limiter = (instance: Redis, name: string, limit: number, window: '60 s' | '24 h') =>
    new Ratelimit({
      redis: instance,
      limiter: Ratelimit.slidingWindow(limit, window),
      prefix: `${prefix}:rl:${name}`,
      analytics: false,
    });

  const messagesKey = () => `${prefix}:day:${dayKey()}:messages`;
  const spendKey = () => `${prefix}:day:${dayKey()}:tenths-cents`;
  const logKey = () => `${prefix}:log:${dayKey()}`;
  const feedbackKey = (id: string) => `${prefix}:feedback:${id}`;

  /* A stable per-visitor key. The address is hashed (salted) before it
     becomes a Redis key, so no raw address is stored. */
  const visitorKey = async (request: Request): Promise<string> => {
    const forwarded = request.headers.get('x-forwarded-for')?.split(',')[0]?.trim();
    const ip = forwarded || request.headers.get('x-real-ip')?.trim() || 'local';
    return (await sha256Hex(salt + ip)).slice(0, 32);
  };

  const ALLOWED: GuardrailVerdict = { allowed: true, tier: 'open' };

  const check = async (request: Request): Promise<GuardrailVerdict> => {
    const instance = getRedis();
    if (!instance) return ALLOWED;
    try {
      const visitor = await visitorKey(request);
      const [burst, daily] = await Promise.all([
        limiter(instance, 'burst', perMinute, '60 s').limit(visitor),
        limiter(instance, 'day', perDay, '24 h').limit(visitor),
      ]);
      if (!burst.success) return { allowed: false, notice: copy.burst };
      if (!daily.success) return { allowed: false, notice: copy.daily };

      const [messages, spendTenths] = await Promise.all([
        instance.get<number>(messagesKey()),
        instance.get<number>(spendKey()),
      ]);
      if ((messages ?? 0) >= dailyMessageCap || (spendTenths ?? 0) >= dailySpendCapTenths) {
        return { allowed: false, notice: copy.paused };
      }

      // Counted before the call, so a request that dies mid-stream still
      // counts against the cap. Under-counting is what lets a retry loop run.
      const count = await instance.incr(messagesKey());
      if (count === 1) await instance.expire(messagesKey(), COUNTER_TTL_SECONDS);

      const spentFraction = (spendTenths ?? 0) / dailySpendCapTenths;
      const tier: ModelTier =
        spentFraction >= lockFraction ? 'locked' : spentFraction >= stepdownFraction ? 'reduced' : 'open';
      return { allowed: true, tier };
    } catch (error) {
      console.error('[chat] guardrail check failed, allowing the request:', error);
      return ALLOWED;
    }
  };

  const onUsage = async (usage: TokenUsage, modelId: string): Promise<void> => {
    const instance = getRedis();
    if (!instance) return;
    const price = prices[modelId] ?? fallbackPrice;
    const usd =
      ((usage.input_tokens ?? 0) * price.input +
        (usage.output_tokens ?? 0) * price.output +
        (usage.cache_creation_input_tokens ?? 0) * price.cacheWrite +
        (usage.cache_read_input_tokens ?? 0) * price.cacheRead) /
      1_000_000;
    // Integer tenths of a cent: INCRBY is integer-only, and rounding up means
    // the breaker can never drift low across a busy day.
    const tenths = Math.ceil(usd * 1000);
    if (tenths <= 0) return;
    try {
      const total = await instance.incrby(spendKey(), tenths);
      if (total === tenths) await instance.expire(spendKey(), COUNTER_TTL_SECONDS);
    } catch (error) {
      console.error('[chat] recording spend failed:', error);
    }
  };

  const onExchange = async (entry: ExchangeLog): Promise<void> => {
    const instance = getRedis();
    if (!instance) return;
    try {
      const line = JSON.stringify({ at: new Date().toISOString(), ...entry });
      const length = await instance.rpush(logKey(), line);
      // The whole day's list expires together, after its first line.
      if (length === 1) await instance.expire(logKey(), logTtl);
    } catch (error) {
      console.error('[chat] recording exchange failed:', error);
    }
  };

  const perVisitorLimit = (name: string, limit: number) => async (request: Request) => {
    const instance = getRedis();
    if (!instance) return true;
    try {
      const { success } = await limiter(instance, name, limit, '60 s').limit(await visitorKey(request));
      return success;
    } catch (error) {
      console.error(`[chat] ${name} limit check failed, allowing:`, error);
      return true;
    }
  };

  const onFeedback = async (id: string, verdict: ChatFeedbackVerdict, visitor: string): Promise<void> => {
    const instance = getRedis();
    if (!instance) return;
    try {
      await instance.set(feedbackKey(id), JSON.stringify({ at: new Date().toISOString(), verdict, visitor }), {
        ex: logTtl,
      });
    } catch (error) {
      console.error('[chat] recording feedback failed:', error);
    }
  };

  return {
    check,
    visitorKey,
    onUsage,
    onExchange,
    checkFollowups: perVisitorLimit('followups', followupsPerMinute),
    checkFeedback: perVisitorLimit('feedback', feedbackPerMinute),
    onFeedback,
  };
}

'use client';

import { useCallback, useEffect, useRef, useState, type ReactNode } from 'react';
import { revokeAttachmentUrls } from '../components/Attachment/useAttachments';
import type { AttachmentItem } from '../components/Attachment/fileTypes';
import { createStreamReveal } from '../components/StreamingText/useStreamReveal';
import { describeAnswers, sanitizeQuestionSet, serializeReply } from './questions';
import type {
  ChatQuestionAnswer,
  ChatReply,
  ChatTransport,
  ChatTransportMessage,
  ChatTurn,
  LiveResponse,
} from './types';

let nextId = 0;
const makeId = () => `turn-${++nextId}`;

/* ============================================
   Display pacing.

   A real model's deltas arrive in phrase-sized clumps at irregular
   intervals. Rendering each one the moment it lands is honest but reads as
   blocky text, however smoothly the markdown renders: the unevenness is in
   the arrival times, not the drawing. So hold what has arrived and reveal it
   at a steady rate.

   The engine that does the holding is createStreamReveal, the pacing inside
   StreamingText, published headless for exactly this shape of consumer: one
   that streams markdown and must render it itself. The rate scales with the
   backlog rather than being fixed, so whatever is waiting drains within
   MOTION_STREAM_DRAIN_MS and a thin trickle still moves at
   MOTION_STREAM_FLOOR_CPS, both from tokens/motion.
   ============================================ */

/** The copy the hook writes itself: the status line of a reply that has not started, and the reply it shows when a transport ends a turn with nothing to show. */
export interface ChatPlaceholderCopy {
  /** A completion that produced no text. */
  empty: string;
  /** The reader stopped the response before any text arrived. */
  stopped: string;
  /** The transport failed before any text arrived. */
  failed: string;
  /**
   * The status line of a reply in flight before the transport reports one of
   * its own. Defaults to "Thinking". Optional so a full object written
   * against the earlier shape still type-checks.
   */
  thinking?: string;
}

export const DEFAULT_PLACEHOLDER_COPY: Required<ChatPlaceholderCopy> = {
  empty: 'The reply came back empty. Try sending that again.',
  stopped: 'Stopped before a reply arrived.',
  failed: 'Something went wrong while replying. Try sending that again.',
  thinking: 'Thinking',
};

/** What `useChat` returns: the conversation and the actions that move it. */
export interface ChatState {
  /** The committed turns, oldest first. */
  turns: ChatTurn[];
  /** The assistant turn in flight, or null between exchanges. */
  live: LiveResponse | null;
  /** Whether a response is in flight. */
  streaming: boolean;
  /** Display label of the model the transport last reported, null before the first exchange. */
  modelLabel: string | null;
  /** The transport's current model offer (default + locked values), null before it first reports. */
  modelPolicy: { default: string; locked: string[] } | null;
  /**
   * Send a message. Returns whether the send was accepted: false while a
   * response is in flight or for an empty draft, so the caller knows not to
   * clear its input. Files alone are a whole message, so an empty draft is
   * accepted when there are some.
   */
  send: (
    text: string,
    options?: { content?: ReactNode; attachments?: AttachmentItem[]; reply?: ChatReply }
  ) => boolean;
  /**
   * Answer the questions an assistant turn asked: records the answers on
   * that turn, so its card renders the record, and sends them as the next
   * message. Returns false, recording nothing, when the send is refused
   * (a response in flight) or the turn asks nothing.
   */
  answerQuestion: (turnId: string, answers: ChatQuestionAnswer[]) => boolean;
  /** Decline the questions an assistant turn asked. Records the skip and sends nothing. */
  skipQuestion: (turnId: string) => void;
  /**
   * Send a follow-up chip from under a turn and record which it was, so the
   * row keeps the choice. Returns whether the send was accepted.
   */
  chooseFollowup: (turnId: string, label: string) => boolean;
  /** Stop the in-flight response, keeping the text that already arrived. */
  stop: () => void;
  /** New chat: abort anything in flight and clear the conversation. */
  reset: () => void;
  /**
   * Append a committed turn directly, bypassing the transport. Injected turns
   * are stage dressing: they never enter the transport history, so a live
   * model is never fed words it did not say.
   */
  injectTurn: (turn: Omit<ChatTurn, 'id'>) => void;
  /** Record the visitor's thumbs verdict on a committed turn. State only: the caller tells the server. */
  setTurnFeedback: (turnId: string, feedback: 'up' | 'down') => void;
  /**
   * Attach follow-up questions to a committed turn. State only: the caller
   * produces them. Writing an empty array records that the attempt was made
   * and came back with nothing, so it is never repeated for that turn.
   */
  setTurnFollowups: (turnId: string, followups: string[]) => void;
}

/**
 * useChat owns the conversation: the committed turns, the assistant turn in
 * flight, and the phase machine that drives the AgentStatus, Reasoning and
 * streamed-text choreography. It knows nothing about rendering or about
 * where events come from; the transport decides that.
 */
export function useChat(
  transport: ChatTransport,
  placeholders: ChatPlaceholderCopy = DEFAULT_PLACEHOLDER_COPY
): ChatState {
  const [turns, setTurns] = useState<ChatTurn[]>([]);
  const [live, setLive] = useState<LiveResponse | null>(null);
  /* The model label the transport last reported, null until a first exchange.
     Survives reset on purpose: the serving model is a fact about the
     backend, not about one conversation. */
  const [modelLabel, setModelLabel] = useState<string | null>(null);
  /* The transport's current model offer (default + locked values), null until
     it first reports. Survives reset like the label. */
  const [modelPolicy, setModelPolicy] = useState<{
    default: string;
    locked: string[];
  } | null>(null);

  const abortRef = useRef<AbortController | null>(null);
  const busyRef = useRef(false);
  /* The transport-facing history, maintained in event handlers only so it
     can be read synchronously when a send starts. UI-only placeholder text
     (stop/error/empty fallbacks) never enters it: the real model must not
     receive our apologies as its own prior speech. */
  const historyRef = useRef<ChatTransportMessage[]>([]);
  /* Bumped on reset. A send whose generation is stale must not touch state,
     otherwise new-chat during a stream repaints the aborted turn into the
     fresh conversation. */
  const generationRef = useRef(0);

  /* Leaving the page mid-stream: abort so a real transport's connection
     does not run to completion against an unmounted consumer. */
  useEffect(() => () => abortRef.current?.abort(), []);

  /* The turns as they stand, for the two moments that release what they
     hold: a reset and the unmount. Sent files keep their preview URLs alive
     for as long as the thread shows them, and no longer. */
  const turnsRef = useRef<ChatTurn[]>(turns);
  useEffect(() => {
    turnsRef.current = turns;
  }, [turns]);
  const releaseAttachments = useCallback(() => {
    for (const turn of turnsRef.current) {
      if (turn.attachments) revokeAttachmentUrls(turn.attachments);
    }
  }, []);
  useEffect(() => releaseAttachments, [releaseAttachments]);

  const streaming = live !== null;

  /**
   * Move the finished live response into the committed turns.
   * `historyText` is what the transport history records: null when the
   * turn is a UI-only placeholder that must not reach the model.
   */
  const commit = useCallback(
    (finished: LiveResponse, startedAt: number, historyText: string | null) => {
      if (historyText !== null && historyText !== '') {
        historyRef.current = [
          ...historyRef.current,
          { role: 'assistant', content: historyText },
        ];
      }
      setLive(null);
      setTurns((prev) => [
        ...prev,
        {
          id: finished.id,
          role: 'assistant',
          text: finished.text,
          tracePoints: finished.tracePoints,
          exchangeId: finished.exchangeId,
          followups: finished.followups,
          content: finished.content,
          card: finished.card,
          question: finished.question,
          durationSeconds:
            finished.durationSeconds ??
            Math.max(1, Math.round((Date.now() - startedAt) / 1000)),
        },
      ]);
    },
    []
  );

  const send = useCallback<ChatState['send']>(
    (text, options) => {
      const trimmed = text.trim();
      const attachments = options?.attachments?.length ? options.attachments : undefined;
      if ((trimmed === '' && !attachments) || busyRef.current) return false;
      busyRef.current = true;

      const controller = new AbortController();
      abortRef.current = controller;
      const generation = generationRef.current;
      const startedAt = Date.now();

      const history: ChatTransportMessage[] = [
        ...historyRef.current,
        {
          role: 'user',
          content: trimmed,
          attachments: attachments?.map(({ name, kind, size }) => ({ name, kind, size })),
        },
      ];
      historyRef.current = history;

      // The user turn and the live assistant turn appear in the same update,
      // so ChatThread anchors the user turn to the top of the viewport.
      const userTurnId = makeId();
      setTurns((prev) => [
        ...prev,
        {
          id: userTurnId,
          role: 'user',
          text: trimmed,
          content: options?.content,
          attachments,
          reply: options?.reply,
        },
      ]);

      let current: LiveResponse = {
        id: makeId(),
        phase: 'thinking',
        statusLabel: placeholders.thinking ?? DEFAULT_PLACEHOLDER_COPY.thinking,
        tracePoints: [],
        text: '',
      };
      setLive(current);

      const update = (next: LiveResponse) => {
        current = next;
        setLive(next);
      };

      /* The engine holds what the transport has yielded and moves the
         on-screen slice towards it once a frame, which also coalesces
         renders: a fast stream never re-parses the markdown more than once
         a frame. `onUpdate` merges into `current`, so the phase and duration
         recorded at arrival ride along with the next slice. */
      const reveal = createStreamReveal({
        onUpdate: (visible) => update({ ...current, text: visible }),
        /* Someone who has asked for less motion is asking for less of this. */
        paced: !window.matchMedia('(prefers-reduced-motion: reduce)').matches,
      });

      const run = async () => {
        try {
          for await (const event of transport(history, controller.signal)) {
            /* A transport may deliver one more event after an abort or
               reset resolves: never let it touch the fresh conversation. */
            if (generation !== generationRef.current || controller.signal.aborted) break;
            switch (event.type) {
              case 'model':
                setModelLabel(event.label);
                break;
              case 'models':
                setModelPolicy({ default: event.default, locked: event.locked });
                break;
              case 'exchange':
                /* A fact about the turn, not about what is on screen: no
                   render needed; commit carries it into the turn. */
                current = { ...current, exchangeId: event.id };
                break;
              case 'followups':
                // Same: nothing renders until the turn commits with them.
                current = { ...current, followups: event.items };
                break;
              case 'content':
                /* Drawn on the live reply as it arrives, where a tool's
                   result belongs, and carried into the turn on commit. */
                update({ ...current, content: event.node });
                break;
              case 'card':
                update({ ...current, card: event.card });
                break;
              case 'question': {
                /* Checked again here, whatever the transport did: the set is
                   about to be drawn as choices the host appears to offer. */
                const set = sanitizeQuestionSet(event.set, `${current.id}-questions`);
                if (set) current = { ...current, question: set };
                break;
              }
              case 'status':
                update({
                  ...current,
                  statusLabel: event.label,
                  tracePoints: event.point
                    ? [...current.tracePoints, event.point]
                    : current.tracePoints,
                });
                break;
              case 'delta':
                /* The phase and duration are facts about arrival, not about
                   the reveal, so they are recorded here; the reveal loop
                   carries them into the next render along with the text. */
                current = {
                  ...current,
                  phase: 'streaming',
                  // Thinking ends at the first delta; freeze the duration then.
                  durationSeconds:
                    current.durationSeconds ??
                    Math.max(1, Math.round((Date.now() - startedAt) / 1000)),
                };
                reveal.append(event.text);
                break;
              /* A guardrail line and a failure are not the model speaking, so
                 they are not paced like it: they appear whole. */
              case 'notice':
              case 'error':
                current = {
                  ...current,
                  phase: 'streaming',
                  durationSeconds: current.durationSeconds ?? 1,
                };
                reveal.showWhole(event.type === 'notice' ? event.text : event.message);
                break;
              case 'done':
                break;
            }
            if (event.type === 'done') break;
          }
          /* The transport is done, but the reveal may not be. Committing now
             would pop the unrevealed remainder in whole, undoing the pacing
             at the very end of every response, so let it finish first.
             A stop or a reset does not wait: it shows what arrived and ends. */
          if (controller.signal.aborted || generation !== generationRef.current) {
            reveal.flush();
          } else {
            await reveal.drained();
          }
          reveal.cancel();
          if (generation !== generationRef.current) return;
          if (current.text === '') {
            // A completion that never produced text is a failure, not a reply.
            commit({ ...current, text: placeholders.empty }, startedAt, null);
          } else {
            commit(current, startedAt, current.text);
          }
        } catch (err) {
          reveal.flush();
          if (generation !== generationRef.current) {
            // The conversation was reset out from under this send: drop it.
          } else if (controller.signal.aborted) {
            // Stopped by the reader: keep whatever streamed in; the partial
            // is real assistant speech, so it belongs in the history too.
            if (current.text === '') {
              commit({ ...current, text: placeholders.stopped }, startedAt, null);
            } else {
              commit(current, startedAt, current.text);
            }
          } else {
            // Keep any partial (it is real); placeholder only when empty.
            if (current.text === '') {
              commit({ ...current, text: placeholders.failed }, startedAt, null);
            } else {
              commit(current, startedAt, current.text);
            }
            // Surface the real cause for the person building, not the visitor.
            console.error(err);
          }
        } finally {
          if (generation === generationRef.current) busyRef.current = false;
        }
      };

      void run();
      return true;
    },
    [transport, commit, placeholders]
  );

  const setTurnFeedback = useCallback((turnId: string, feedback: 'up' | 'down') => {
    setTurns((prev) =>
      prev.map((turn) => (turn.id === turnId ? { ...turn, feedback } : turn))
    );
  }, []);

  const setTurnFollowups = useCallback((turnId: string, followups: string[]) => {
    setTurns((prev) =>
      prev.map((turn) => (turn.id === turnId ? { ...turn, followups } : turn))
    );
  }, []);

  const patchTurn = useCallback((turnId: string, patch: Partial<ChatTurn>) => {
    setTurns((prev) => prev.map((turn) => (turn.id === turnId ? { ...turn, ...patch } : turn)));
  }, []);

  const answerQuestion = useCallback(
    (turnId: string, answers: ChatQuestionAnswer[]) => {
      const set = turnsRef.current.find((turn) => turn.id === turnId)?.question;
      if (!set) return false;
      const reply = describeAnswers(set, answers);
      /* Sent first, recorded after: a refused send leaves the card open to
         try again rather than marked with an answer nobody received. */
      if (!send(serializeReply(reply), { reply })) return false;
      patchTurn(turnId, { answers });
      return true;
    },
    [send, patchTurn]
  );

  const skipQuestion = useCallback(
    (turnId: string) => patchTurn(turnId, { answers: [] }),
    [patchTurn]
  );

  const chooseFollowup = useCallback(
    (turnId: string, label: string) => {
      if (!send(label)) return false;
      patchTurn(turnId, { followupChosen: label });
      return true;
    },
    [send, patchTurn]
  );

  const injectTurn = useCallback((turn: Omit<ChatTurn, 'id'>) => {
    setTurns((prev) => [...prev, { ...turn, id: makeId() }]);
  }, []);

  const stop = useCallback(() => {
    abortRef.current?.abort();
  }, []);

  const reset = useCallback(() => {
    generationRef.current += 1;
    abortRef.current?.abort();
    // The generation guard makes the old stream inert, so the fresh
    // conversation accepts sends immediately.
    busyRef.current = false;
    historyRef.current = [];
    releaseAttachments();
    setTurns([]);
    setLive(null);
  }, [releaseAttachments]);

  return {
    turns,
    live,
    streaming,
    modelLabel,
    modelPolicy,
    send,
    stop,
    reset,
    injectTurn,
    setTurnFeedback,
    setTurnFollowups,
    answerQuestion,
    skipQuestion,
    chooseFollowup,
  };
}
